import { useCallback } from "react";
import { LiveKitConfig } from "../services/livekit";
import { useLiveKit } from "./useLiveKit";

interface UseAgentLiveKit {
  joinVoice: (forceReconnect?: boolean) => Promise<LiveKitConfig | undefined>;
}

export const useAgentLiveKit = ({ joinVoice }: UseAgentLiveKit) => {
  const {
    connect: doConnect,
    disconnect,
    isConnected,
    isConnecting,
    room,
    localParticipant,
    remoteParticipants,
  } = useLiveKit();

  const getConfig = useCallback(
    async (forceReconnect = false) => {
      const config = await joinVoice(forceReconnect);
      if (!config) return undefined;

      return config;
    },
    [joinVoice]
  );

  const connect = useCallback(
    async (forceReconnect = false) => {
      const config = await getConfig(forceReconnect);
      if (!config) {
        throw new Error("Unable to obtain a valid configuration");
      }
      return doConnect(config);
    },
    [doConnect, getConfig]
  );

  return {
    connect,
    disconnect,
    isConnected,
    isConnecting,
    room,
    localParticipant,
    remoteParticipants,
  };
};
