import { useCallback, useRef } from "react";
import { useAppSelector } from "../store/hooks";
import { selectConversationId } from "../store/slices";

interface ExtraLoggingFields {
  session_id?: string;
  // host_url?: string; // added by LWC
  entry_id?: string;
  trace_id?: string;
}
const O11Y_EVENT = "onAgentforceMessagingLogEvent";

const dispatchO11yLogEvent = (
  source: string,
  message: string,
  extraData?: ExtraLoggingFields
) => {
  window.dispatchEvent(
    new CustomEvent(O11Y_EVENT, {
      detail: { message: `[${source}] ${message}`, ...extraData },
    })
  );
};

export const useO11y = () => {
  const sessionId = useAppSelector(selectConversationId);

  // make `sessionId` stable
  const sessionIdRef = useRef(sessionId);
  sessionIdRef.current = sessionId;

  const log = useCallback(
    (
      source: string,
      message: string,
      extraData?: Omit<ExtraLoggingFields, "session_id">
    ) => {
      dispatchO11yLogEvent(source, message, {
        ...extraData,
        session_id: sessionIdRef.current,
      });
    },
    []
  );

  return { log };
};
