import { Loader, Mic, MicOff } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import React, { useCallback, useEffect, useMemo } from "react";
import "setimmediate";
import { useConfigurationContext } from "../hooks/useConfigurationContext";
import { useVoice } from "../providers/VoiceProvider";
import { useAppDispatch, useAppSelector } from "../store/hooks";
import {
  ConversationStatus,
  getAllowVoiceMode,
  selectConversationStatus,
  startConversation,
} from "../store/slices";
import { selectIsSessionStarting } from "../store/slices/conversation";
import { cn } from "../utils";
import { useChatContext } from "./ChatProvider";
import { ChatBubbleIcon } from "./icons/ChatBubbleIcon";
import { CloseIcon } from "./icons/CloseIcon";
import { WaveformIcon } from "./icons/WaveformIcon";
import { MicrophoneVisualization } from "./MicrophoneVisualization";

const CHAT_FAB_VOICE_MODE_WIDTH = 256;

// custom hook for managing container width
function useContainerWidth(
  ref: React.RefObject<HTMLDivElement | null>,
  isVoiceMode: boolean,
  isChatOpen: boolean,
  isOtherVoiceMode: boolean,
  fabText: string | undefined
) {
  const [width, setWidth] = React.useState<number | "auto">("auto");

  useEffect(() => {
    if (ref.current) {
      const width = ref.current.scrollWidth;
      setWidth(
        isVoiceMode && !isOtherVoiceMode
          ? Math.max(CHAT_FAB_VOICE_MODE_WIDTH, width)
          : width
      );
    }
    // we don't need to re-run this effect when the ref changes
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isVoiceMode, isChatOpen, isOtherVoiceMode, fabText]);

  return width;
}

export function ChatFAB() {
  const {
    isVoiceMode,
    isMuted,
    toggleMute,
    voiceModeError,
    isVoiceModeLoading,
    microphonePermission,
    isOtherVoiceMode,
  } = useVoice();
  const {
    isChatOpen,
    isTabActive,
    openChat,
    closeChat,
    toggleVoiceModeAfterStartingSession,
    setClosedWidth,
  } = useChatContext();
  const allowVoiceMode = useAppSelector(getAllowVoiceMode);

  const conversationStatus = useAppSelector(selectConversationStatus);
  const isSessionStarting = useAppSelector(selectIsSessionStarting);
  const isSessionUnstarted =
    !isSessionStarting &&
    (conversationStatus === undefined ||
      conversationStatus === ConversationStatus.NotStarted);
  // const isSessionActive = conversationStatus === ConversationStatus.InProgress;
  const dispatch = useAppDispatch();

  const { chatFab, chatVoice } = useConfigurationContext();
  const { cta } = chatFab;
  const { backgroundColor, textColor } = isVoiceMode ? chatVoice : chatFab;

  const fabText = useMemo(() => {
    // Show error if there's a voice mode error
    if (voiceModeError) {
      if (microphonePermission !== "granted") {
        return "Allow microphone access";
      }
      return voiceModeError;
    }

    // Show loading state if voice mode is loading
    if (isVoiceModeLoading) {
      return "Connecting...";
    }

    // Show the CTA
    return cta;
  }, [isVoiceModeLoading, microphonePermission, voiceModeError, cta]);

  const containerRef = React.useRef<HTMLDivElement>(null);
  const containerWidth = useContainerWidth(
    containerRef,
    isVoiceMode,
    isChatOpen,
    isOtherVoiceMode,
    fabText
  );

  const handleChatToggle = useCallback(() => {
    if (isChatOpen) {
      closeChat();
      return;
    }
    if (isSessionUnstarted) {
      if (isVoiceMode) {
        toggleVoiceModeAfterStartingSession();
      } else {
        dispatch(startConversation());
        openChat();
      }
    } else {
      openChat();
    }
  }, [
    closeChat,
    dispatch,
    isChatOpen,
    isSessionUnstarted,
    openChat,
    isVoiceMode,
    toggleVoiceModeAfterStartingSession,
  ]);

  useEffect(() => {
    if (!isChatOpen) {
      setImmediate(() => {
        // need this to wait for the container to be fully rendered
        if (containerWidth === "auto") {
          setClosedWidth(
            `${Math.ceil(containerRef.current?.getBoundingClientRect().width ?? 0)}px`
          );
        } else {
          setClosedWidth(`${containerWidth}px`);
        }
      });
    }
  }, [isChatOpen, setClosedWidth, containerWidth]);

  const buttonRef = React.useCallback(
    (node: HTMLButtonElement | null) => {
      if (node !== null && !isChatOpen) {
        setTimeout(() => {
          node.focus();
        }, 350);
      }
    },
    [isChatOpen]
  );

  return (
    <AnimatePresence initial={false}>
      {!isChatOpen && (
        <motion.div
          ref={containerRef}
          layout="size"
          layoutId="chat-fab"
          {...(isTabActive && {
            initial: { opacity: 0 },
            animate: { opacity: 1 },
            transition: {
              duration: 0.3,
              ease: "easeInOut",
              delay: 0.2,
            },
          })}
          style={{
            width: isVoiceMode && !isOtherVoiceMode ? containerWidth : "auto",
            backgroundColor,
          }}
          className={cn(
            "fixed right-0 bottom-0 inline-flex h-14 items-center justify-center rounded-[15px] px-2 py-2 transition-all duration-300 ease-in-out"
          )}
          role="region"
          aria-label="Chat controls"
        >
          {isVoiceMode ? (
            <motion.div
              key="voice-mode"
              className="flex w-full items-center"
              {...(isTabActive && {
                initial: { opacity: 0 },
                animate: { opacity: 1 },
                transition: { duration: 0.2 },
              })}
              aria-label="Voice chat controls"
            >
              <button
                onClick={openChat}
                className="flex items-center justify-center rounded-full transition-colors"
                style={{ color: textColor }}
                title="Open voice chat"
              >
                <div className="flex h-8 items-center justify-center pr-1 pl-2">
                  {isOtherVoiceMode ? (
                    <div
                      className="flex rounded-full text-left text-sm font-medium whitespace-nowrap transition-colors"
                      style={{ color: textColor + "99" }}
                    >
                      Connected from another tab
                    </div>
                  ) : (
                    <MicrophoneVisualization color={textColor} />
                  )}
                </div>
              </button>
              <div className="flex-1" />

              <div className="flex items-center gap-2">
                <button
                  onClick={toggleMute}
                  className="flex items-center justify-center rounded-full p-1.5 hover:bg-white/10"
                  title={isMuted ? "Unmute microphone" : "Mute microphone"}
                  aria-pressed={isMuted}
                  role="switch"
                >
                  {isMuted ? (
                    <MicOff
                      className="size-6"
                      style={{
                        color: chatVoice.microphoneIcon.textColorMuted,
                      }}
                      aria-hidden="true"
                    />
                  ) : (
                    <Mic
                      className="size-6"
                      style={{
                        color: chatVoice.microphoneIcon.textColorUnmuted,
                      }}
                      aria-hidden="true"
                    />
                  )}
                </button>

                <div
                  className="h-10 border-l"
                  style={{ borderColor: textColor + "33" }}
                  role="separator"
                />

                <button
                  onClick={toggleVoiceModeAfterStartingSession}
                  className="group flex items-center justify-center rounded-full p-1.5 text-white hover:bg-white/10 focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-black focus:outline-none"
                  title="Exit voice mode"
                >
                  <CloseIcon
                    className="size-6"
                    style={{ color: textColor }}
                    aria-hidden="true"
                  />
                </button>
              </div>
            </motion.div>
          ) : (
            <motion.div
              key="normal-mode"
              className="flex items-center"
              {...(isTabActive && {
                initial: { opacity: 0 },
                animate: { opacity: 1 },
                transition: { duration: 0.2, delay: 0.2 },
              })}
              role="group"
              aria-label="Text chat controls"
            >
              {fabText && (
                <div className="flex items-center justify-center">
                  <div
                    className={cn(
                      "flex items-center justify-center rounded-xl p-2",
                      voiceModeError && "bg-error-container-1"
                    )}
                  >
                    <div
                      className={cn(
                        "font-avant-garde flex items-center justify-center text-base font-bold tracking-[0.02px] whitespace-nowrap select-none",
                        voiceModeError && "text-error-1 px-1.5"
                      )}
                      style={{ color: textColor }}
                    >
                      {fabText}
                    </div>
                  </div>
                  {voiceModeError && (
                    <div
                      className="border-l-error-container-1 h-0 w-0 border-t-[6px] border-b-[6px] border-l-[6px] border-t-transparent border-b-transparent"
                      aria-hidden="true"
                    />
                  )}
                </div>
              )}
              <div className="flex-1" />
              {allowVoiceMode && !isVoiceModeLoading && (
                <button
                  onClick={toggleVoiceModeAfterStartingSession}
                  className={cn(
                    "flex cursor-pointer items-center justify-center rounded-full p-2.5 text-white transition-colors",
                    "hover:bg-black/5 focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2 focus-visible:outline-none"
                  )}
                  title="Enable voice mode"
                >
                  <WaveformIcon
                    className="shrink-0"
                    style={{ color: textColor }}
                    aria-hidden="true"
                  />
                </button>
              )}
              {allowVoiceMode && isVoiceModeLoading && (
                <div className="flex items-center justify-center rounded-full p-2.5">
                  <Loader
                    strokeWidth={3}
                    className="size-6 shrink-0 animate-spin text-black"
                    aria-label="Starting voice mode"
                  />
                </div>
              )}

              <button
                ref={buttonRef}
                onClick={handleChatToggle}
                className={cn(
                  "group flex cursor-pointer items-center justify-center rounded-full p-2.5 transition-colors",
                  "text-black hover:bg-black/5 focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2 focus-visible:outline-none"
                )}
                title={"Open Agentforce chat"}
              >
                <ChatBubbleIcon
                  className="size-6 shrink-0"
                  aria-hidden="true"
                  style={{ color: textColor }}
                />
              </button>
            </motion.div>
          )}
        </motion.div>
      )}
    </AnimatePresence>
  );
}
