import { Store } from "@reduxjs/toolkit";
import "setimmediate";
import { ConversationState, setConversationData } from "./slices/conversation";

interface PartialState {
  conversation: ConversationState;
}

class ConversationDataManager {
  private store: Store | undefined;
  private currentConversationId: string | undefined;
  private cache: Record<string, any> = {};
  private pendingData: Record<string, any> = {};

  public init(store: Store) {
    this.store = store;

    // schedule an immediate update from state
    // this is to ensure our cache is up to date when the store is initialized
    // it is mostly relevant for multi-tab scenarios
    setImmediate(() => {
      this._updateFromState(this.store!.getState());
    });
  }

  public setData(data: Record<string, any>) {
    if (!this.store) {
      console.warn(
        "ConversationDataManager used before store initialization. Data will be queued."
      );
    }

    if (this.currentConversationId) {
      this.store?.dispatch(
        setConversationData({
          conversationId: this.currentConversationId,
          data: {
            // ensure we include any pending data that has not been set yet
            ...this.pendingData,
            ...data,
          },
        })
      );
    } else {
      this.pendingData = {
        ...this.pendingData,
        ...data,
      };
    }
  }

  public getData(): Record<string, any> {
    return { ...this.cache, ...this.pendingData };
  }

  /**
   * @internal
   * Used by the listener middleware to update the manager's internal state.
   */
  public _updateFromState(state: PartialState) {
    const newConversationId = state.conversation.currentConversationId;
    const oldConversationId = this.currentConversationId;
    this.currentConversationId = newConversationId;

    const conversationState = newConversationId
      ? state.conversation.conversations[newConversationId]
      : undefined;

    this.cache = conversationState?.data ?? {};

    // If we just started a NEW session, dispatch pending data
    if (newConversationId && newConversationId !== oldConversationId) {
      if (Object.keys(this.pendingData).length > 0) {
        this.store?.dispatch(
          setConversationData({
            conversationId: newConversationId,
            data: this.pendingData,
          })
        );
      }
    }

    // Now, independently, check if pending data can be cleared because it has arrived in the cache.
    const pendingKeys = Object.keys(this.pendingData);
    if (pendingKeys.length > 0) {
      const allPendingKeysInCache = pendingKeys.every(
        (key) =>
          Object.prototype.hasOwnProperty.call(this.cache, key) &&
          this.cache[key] === this.pendingData[key]
      );
      if (allPendingKeysInCache) {
        this.pendingData = {};
      }
    }
  }

  /**
   * @internal
   * Used by the listener middleware to clear session data.
   */
  public _clearSession() {
    this.currentConversationId = undefined;
    this.cache = {};
    this.pendingData = {};
  }
}

export const conversationDataManager = new ConversationDataManager();
