import { EventSource } from "eventsource";
import { v4 } from "uuid";
import { MIAW_SCRT_PATH } from "../../utils/constants";
import { doDelete, doGet, doPost } from "../../utils/fetch";
/**
 * TODO - Empty methods are stubs, need to implement
 */
export const createMiawInAppService = ({
  orgId,
  name,
  scrt2URL,
}: MiawInAppServiceConfiguration): InAppService => {
  if (!orgId || !name || !scrt2URL) {
    throw new Error("Missing required parameters for Miaw InAppService");
  }
  const scrt2Endpoint = new URL("iamessage/v1/", scrt2URL);
  const sseEndpoint = () =>
    new URL(`eventrouter/v1/sse?_ts=${Date.now()}`, scrt2URL);
  let currentConversationId: string | undefined;
  let currentJwtData: JWTData | undefined;
  let eventSource: EventSource | undefined;

  const generateUnauthenticatedJwt = async () => {
    const endpoint = new URL(
      `${MIAW_SCRT_PATH.authorization}/${MIAW_SCRT_PATH.unauthenticated}/${MIAW_SCRT_PATH.accessToken}`,
      scrt2Endpoint
    ).toString();
    const response = await doPost(endpoint, {
      orgId,
      developerName: name,
      capabilitiesVersion: "254",
    });
    const jwtData = await response.json();
    currentJwtData = jwtData;
    return jwtData;
  };

  return {
    getConversationId: () => currentConversationId,
    setConversationId: (newConversationId: string | undefined) => {
      currentConversationId = newConversationId;
    },
    getAccessToken: async () => {
      if (currentJwtData) {
        return currentJwtData;
      } else {
        return await generateUnauthenticatedJwt();
      }
    },
    subscribeToEventSource: (
      eventListenerMap: Record<string, AnyFunction>
    ): Promise<void> => {
      return new Promise((resolve, reject) => {
        eventSource = new EventSource(sseEndpoint().toString(), {
          fetch: (input, init) =>
            doGet(input.toString(), {
              ...init,
              headers: {
                ...init?.headers,
                Authorization: "Bearer " + currentJwtData?.accessToken,
                "X-Org-ID": orgId,
                ...(currentJwtData?.lastEventId && {
                  "Last-Event-ID": currentJwtData.lastEventId,
                }),
              },
            }),
        });

        eventSource.onopen = () => {
          Object.entries(eventListenerMap).forEach(
            ([eventName, eventHandler]) => {
              eventSource!.addEventListener(eventName, eventHandler);
            }
          );
          resolve();
        };

        eventSource.onerror = (error) => {
          console.error("EventSource error", error);
          reject();
        };
      });
    },
    closeEventSource: async () => {
      if (eventSource) eventSource.close();
    },
    createConversation: async () => {
      const endpoint = new URL(
        `${MIAW_SCRT_PATH.conversation}`,
        scrt2Endpoint
      ).toString();
      const conversationId = v4();
      await doPost(
        endpoint,
        {
          language: "en-US",
          conversationId,
        },
        {
          headers: {
            Authorization: "Bearer " + currentJwtData?.accessToken,
          },
        }
      );
      currentConversationId = conversationId;
      return conversationId;
    },
    closeConversation: async () => {
      const endpoint = new URL(
        `${MIAW_SCRT_PATH.conversation}/${currentConversationId}`,
        scrt2Endpoint
      ).toString();
      return doDelete(endpoint, undefined, {
        headers: {
          Authorization: "Bearer " + currentJwtData?.accessToken,
        },
      });
    },
    sendTextMessage: async (
      text: string,
      id: string,
      inReplyToMessageId?: string,
      isNewMessagingSession?: boolean,
      routingAttributes?: Record<string, unknown>
    ) => {
      const endpoint = new URL(
        `${MIAW_SCRT_PATH.conversation}/${currentConversationId}/${MIAW_SCRT_PATH.message}`,
        scrt2Endpoint
      ).toString();
      return doPost(
        endpoint,
        {
          id,
          messageType: "StaticContentMessage",
          staticContent: {
            formatType: "Text",
            text,
          },
          ...(inReplyToMessageId && { inReplyToMessageId }),
          ...(isNewMessagingSession && { isNewMessagingSession }),
          ...(routingAttributes && { routingAttributes }),
        },
        {
          headers: {
            Authorization: "Bearer " + currentJwtData?.accessToken,
          },
        }
      );
    },
    // Stub methods - TODO: implement these
    getAuthenticatedJwt: async () => {
      throw new Error("getAuthenticatedJwt not implemented");
    },
    getContinuityJwt: async () => {
      throw new Error("getContinuityJwt not implemented");
    },
    getExpSiteAuthenticatedJwt: (_expSiteUrl: string) => {
      throw new Error("getExpSiteAuthenticatedJwt not implemented");
    },
    sendChoicesResponseMessage: async (
      _optionIdentifier: string,
      _id: string,
      _inReplyToMessageId: string,
      _isNewMessagingSession?: boolean,
      _routingAttributes?: Record<string, unknown>
    ) => {
      throw new Error("sendChoicesResponseMessage not implemented");
    },
    sendFileAttachment: async (
      _file: unknown,
      _messageId: string,
      _message?: string,
      _inReplyToMessageId?: string,
      _isNewMessagingSession?: boolean,
      _routingAttributes?: Record<string, unknown>
    ) => {
      throw new Error("sendFileAttachment not implemented");
    },
    sendFormResponseMessage: async (
      _inputValues: string,
      _id: string,
      _inReplyToMessageId: string,
      _isNewMessagingSession?: boolean,
      _routingAttributes?: unknown
    ) => {
      throw new Error("sendFormResponseMessage not implemented");
    },
    sendTypingIndicator: async (_typingIndicator: string) => {
      throw new Error("sendTypingIndicator not implemented");
    },
    sendDeliveryAcknowledgement: async (_conversationEntryId: string) => {
      throw new Error("sendDeliveryAcknowledgement not implemented");
    },
    sendReadAcknowledgement: async (_conversationEntryId: string) => {
      throw new Error("sendReadAcknowledgement not implemented");
    },
    getConversationEntries: async (
      _limit: number,
      _endTimestamp: number,
      _startTimestamp: number,
      _direction: "FromStart" | "FromEnd"
    ) => {
      throw new Error("getConversationEntries not implemented");
    },
  };
};
