import { RPCEvent, RPCManager } from "@local/rpc-manager";
import { Unsubscribe } from "@reduxjs/toolkit";
import {
  createContext,
  ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { v4 } from "uuid";
import { getCurrentAdapters } from "../adapters";
import { useAdapters } from "../hooks/useAdapters";
import { useLayoutMode } from "../hooks/useLayoutMode";
import { useVoice, VoiceProvider } from "../providers/VoiceProvider";
import { conversationDataManager, store } from "../store";
import { useAppDispatch, useAppSelector, useAppState } from "../store/hooks";
import {
  addConversationEntry,
  ConversationStatus,
  endConversation,
  selectConversationEntriesAsArray,
  selectConversationId,
  selectConversationStartedAt,
  selectConversationStatus,
  selectHostUrl,
  selectIsChatOpen,
  selectIsLoading,
  selectIsSessionStarting,
  selectIsVoiceMode,
  selectProgressIndicatorText,
  selectShowProgressIndicator,
  sendMessage,
  setConversationChatState,
  setIsChatOpen as setIsChatOpenAction,
  startConversation,
} from "../store/slices";
import { Message } from "../types/Message";
import { subscribeToSelectorOnce } from "../utils";
import { CHAT_WINDOW_DIMENSIONS } from "../utils/constants";
import { dispatchEventToHost } from "../utils/events";

const ERROR_MESSAGES = {
  CONTEXT_ERROR: "useChatContext must be used within a ChatProvider",
  FETCH_ERROR: "Failed to send message",
  READER_ERROR: "No reader available",
} as const;

export interface ChatContextType {
  isChatOpen: boolean;
  isSessionActive: boolean;
  isTabActive: boolean;
  messages: Message[];
  conversationStartedAt: string | undefined;
  openChat: () => void;
  closeChat: () => void;
  sendMessage: (message: string) => Promise<void>;
  isExpanded: boolean;
  toggleExpanded: (expanded?: boolean) => void;
  appendMessage: (message: Message) => void;
  chatDimensions: typeof CHAT_WINDOW_DIMENSIONS;
  showProgressIndicator: boolean;
  progressIndicatorText?: string;
  setClosedWidth: (width: string) => void;
  toggleVoiceMode: () => Promise<void>;
  toggleVoiceModeAfterStartingSession: () => Promise<Unsubscribe | undefined>;
}

const ChatContext = createContext<ChatContextType | undefined>(undefined);

// Custom hook with error boundary
export const useChatContext = () => {
  const context = useContext(ChatContext);
  if (context === undefined) {
    throw new Error(ERROR_MESSAGES.CONTEXT_ERROR);
  }
  return context;
};

/**
 * ChatProvider context for the chat UI.
 *
 * @prop enableRPC If true, the client expects a host to be present and will treat missing host as an error.
 *                If false, the client will gracefully fallback to standalone mode, resolving RPC calls with defaultValue (if provided).
 *                This is useful for embedding the chat in environments where a host may not be available.
 *
 * The global error handler for RPCManager uses enableRPC to determine how to handle HostNotConnected errors.
 */
interface ChatProviderProps {
  children: ReactNode;
  enableRPC?: boolean;
}

const setIsVoiceModeAction = (isVoiceMode: boolean) =>
  setConversationChatState({ isVoiceMode });

export const ChatProvider = ({ children, enableRPC }: ChatProviderProps) => {
  const { isInlineMode } = useLayoutMode();

  // State management
  const dispatch = useAppDispatch();
  const [isChatOpen = isInlineMode, setIsChatOpen] = useAppState(
    selectIsChatOpen,
    setIsChatOpenAction
  );
  const [isVoiceMode, setIsVoiceMode] = useAppState(
    selectIsVoiceMode,
    setIsVoiceModeAction
  );
  const [closedWidth, setClosedWidth] = useState("");
  const [isExpanded, setIsExpanded] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isTabActive, setIsTabActive] = useState(() => !document.hidden);
  const hostUrl = useAppSelector(selectHostUrl) || "*";
  const adapters = useAdapters();
  const adaptersRef = useRef(adapters);
  adaptersRef.current = getCurrentAdapters();
  const conversationStatus = useAppSelector(selectConversationStatus);
  const isSessionActive = conversationStatus === ConversationStatus.InProgress;
  const isSessionStarting = useAppSelector(selectIsSessionStarting);
  const conversationId = useAppSelector(selectConversationId);
  const conversationStartedAt = useAppSelector(selectConversationStartedAt);
  const messages = useAppSelector(selectConversationEntriesAsArray);
  const showProgressIndicator =
    useAppSelector(selectShowProgressIndicator) ?? false;
  const progressIndicatorText =
    useAppSelector(selectProgressIndicatorText) ?? undefined;

  // RPC Client setup
  const rpcManagerRef = useRef<RPCManager | undefined>(undefined);
  const [_rpcConnected, setRpcConnected] = useState(false);

  useEffect(() => {
    // This is used to track the visibility of the tab and only run animations when the tab is active
    const handleVisibilityChange = () => {
      setIsTabActive(!document.hidden);
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  // Initialize RPC Client
  useEffect(() => {
    let rpcManager: RPCManager | undefined = rpcManagerRef.current;
    if (!rpcManager) {
      rpcManager = new RPCManager({
        isHost: false,
        /**
         * Global error handler for all RPC errors.
         *
         * - If error is HostNotConnected and enableRPC is false, resolve with defaultValue (if provided), else reject.
         * - For all other errors, reject.
         */
        onError: async (error, request, resolve, reject) => {
          if (error.type === "HostNotConnected") {
            if (!enableRPC) {
              console.debug(
                "[RPC-CLIENT] Host not connected, but enableRPC is false. Returning default/fallback."
              );
              if (request.defaultValue !== undefined) {
                resolve(request.defaultValue);
                return;
              } else {
                reject(
                  new Error("RPC not enabled and no default value provided")
                );
                return;
              }
            }
          }
          // For all other errors, reject
          reject(error);
        },
      });
      rpcManagerRef.current = rpcManager;
    }

    // Register client-side handlers for host-initiated calls
    rpcManager.registerHandler("endSession", async (event: RPCEvent) => {
      console.debug("[RPC-CLIENT] Host requested session end:", event.data);

      // End the actual conversation session using Redux action
      dispatch(endConversation());

      // Disconnect voice if active
      if (isVoiceMode) {
        setIsVoiceMode(false);
      }

      return { success: true, message: "Session ended successfully" };
    });

    rpcManager.registerHandler("startSession", async (event: RPCEvent) => {
      console.debug("[RPC-CLIENT] Host requested session start:", event.data);

      // Start the actual conversation session using Redux action
      dispatch(startConversation());

      // Wait for the conversation ID to be set, indicating successful start
      return subscribeToSelectorOnce(store, selectConversationId).then(
        (conversationId) => {
          if (conversationId) {
            return { success: true, message: "Session started successfully" };
          }
          return {
            success: false,
            message: "Session did not start successfully",
          };
        }
      );
    });

    rpcManager.registerHandler("sendMessage", async (event: RPCEvent) => {
      console.debug("[RPC-CLIENT] Host requested message send:", event.data);

      const { message } = event.data;
      if (!message || typeof message !== "string") {
        return {
          success: false,
          message: "Message text is required and must be a string",
        };
      }

      // Check if session is active, starting, or agent is busy
      const state = store.getState();
      const isSessionStarting = selectIsSessionStarting(state);
      const isSessionActive =
        selectConversationStatus(state) === ConversationStatus.InProgress;
      const isAgentBusy = selectIsLoading(state);

      if (isSessionStarting) {
        return {
          success: false,
          message: "Cannot send message while session is starting.",
        };
      }

      if (!isSessionActive) {
        return {
          success: false,
          message: "Session has not been started.",
        };
      }

      if (isAgentBusy) {
        return {
          success: false,
          message: "Agent is currently processing a message. Please wait.",
        };
      }

      try {
        // Create Message object and use the same flow as user messages
        const userMessage: Message = {
          id: v4(),
          message,
          sentTime: new Date().toISOString(),
          sender: "user",
          direction: "outgoing",
          position: "single",
        };
        await appendMessage(userMessage);
        return { success: true, message: "Message sent successfully" };
      } catch (error) {
        return {
          success: false,
          message:
            error instanceof Error ? error.message : "Failed to send message",
        };
      }
    });

    rpcManager.registerHandler(
      "setContextVariables",
      async (event: RPCEvent) => {
        console.debug(
          "[RPC-CLIENT] Host requested setting context variables:",
          event.data
        );

        const newVariables: CustomContextVariable[] = event.data.variables;
        conversationDataManager.setData({
          contextVariables: newVariables,
        });

        return { success: true, message: "Context variables set successfully" };
      }
    );

    // Set up connection status listener
    rpcManager.onConnectionChange((connected) => {
      setRpcConnected(connected);
      console.debug(
        `[RPC-CLIENT] Connection status changed: ${connected ? "Connected" : "Disconnected"}`
      );
    });

    rpcManager.startListening();

    // Always attempt to connect to host immediately
    const connectToHost = async () => {
      try {
        await rpcManager.connect();
        console.debug("[RPC-CLIENT] Successfully connected to host");
      } catch (error) {
        console.warn("[RPC-CLIENT] Failed to connect to host:", error);
        // Continue without RPC - not all environments will have a host
      }
    };

    connectToHost();

    return () => {
      rpcManager.stopListening();
      rpcManagerRef.current = undefined;
      setRpcConnected(false);
    };
  }, [setIsChatOpen, setIsVoiceMode, dispatch, enableRPC, isVoiceMode]);

  // Helper function to check with host before connecting
  const checkHostPermission = useCallback(
    async (eventType: "voice" | "chat", data?: any): Promise<boolean> => {
      const rpcManager = rpcManagerRef.current;

      if (!rpcManager) {
        // No RPC available, proceed as normal
        console.debug(
          "[RPC-CLIENT] No RPC connection, proceeding without host check"
        );
        return true;
      }

      try {
        console.debug(
          `[RPC-CLIENT] Checking host permission for ${eventType} connection...`
        );
        const result = await rpcManager.callRemote(
          "connect",
          {
            type: eventType,
            timestamp: Date.now(),
            ...data,
          },
          {
            timeout: 0,
            defaultValue: true,
          }
        );

        console.debug(
          `[RPC-CLIENT] Host ${result ? "approved" : "denied"} ${eventType} connection`
        );
        return result === true;
      } catch (error) {
        console.error(
          `[RPC-CLIENT] Error checking host permission for ${eventType}:`,
          error
        );
        // On error, proceed as normal (fail-open)
        return true;
      }
    },
    []
  );

  // Helper function to send resize message to parent iframe
  const sendResizeMessage = useCallback(
    (
      state: "init" | "closed" | "normal" | "expanded",
      width: string,
      height: string
    ) => {
      if (window.parent === window) return;
      window.parent.postMessage(
        { type: "resize", state, width, height },
        hostUrl
      );
    },
    [hostUrl]
  );

  // Chat window control functions
  const openChat = useCallback(async () => {
    // Check with host before opening chat
    const hostApproval = await checkHostPermission("chat", {
      currentlyOpen: isChatOpen,
      isVoiceMode: isVoiceMode,
    });

    if (!hostApproval) {
      console.debug("Host denied chat connection attempt");
      return;
    }

    setIsChatOpen(true);
  }, [checkHostPermission, isChatOpen, isVoiceMode, setIsChatOpen]);

  const closeChat = useCallback(() => {
    setIsChatOpen(false);
  }, [setIsChatOpen]);

  // Ensure chat is open when in inline mode
  useEffect(() => {
    if (isInlineMode && !isChatOpen) {
      setIsChatOpen(true);
    }
  }, [isInlineMode, isChatOpen, setIsChatOpen]);

  // Auto-start session for inline mode
  useEffect(() => {
    if (
      isInlineMode &&
      conversationStatus !== ConversationStatus.InProgress &&
      conversationStatus !== ConversationStatus.Ended
    ) {
      dispatch(startConversation());
    }
  }, [isInlineMode, conversationStatus, dispatch]);

  // Initialize chat dimensions
  useEffect(() => {
    if (!isInitialized && (closedWidth || isChatOpen)) {
      if (isChatOpen) {
        // Chat starts opened - send init with open dimensions
        const dimensions = isExpanded
          ? CHAT_WINDOW_DIMENSIONS.EXPANDED
          : CHAT_WINDOW_DIMENSIONS.NORMAL;

        sendResizeMessage("init", dimensions.WIDTH, dimensions.HEIGHT);
      } else {
        // Chat starts closed - send init with closed dimensions

        sendResizeMessage(
          "init",
          closedWidth,
          CHAT_WINDOW_DIMENSIONS.CLOSED.HEIGHT
        );
      }

      setTimeout(() => {
        setIsInitialized(true);
      }, 250);
    }
  }, [sendResizeMessage, closedWidth, isChatOpen, isInitialized, isExpanded]);

  useEffect(() => {
    if (!isInitialized) return;

    if (!isChatOpen) {
      sendResizeMessage(
        "closed",
        closedWidth,
        CHAT_WINDOW_DIMENSIONS.CLOSED.HEIGHT
      );
    } else {
      const dimensions = isExpanded
        ? CHAT_WINDOW_DIMENSIONS.EXPANDED
        : CHAT_WINDOW_DIMENSIONS.NORMAL;

      sendResizeMessage(
        isExpanded ? "expanded" : "normal",
        dimensions.WIDTH,
        dimensions.HEIGHT
      );
    }
  }, [isChatOpen, isExpanded, closedWidth, sendResizeMessage, isInitialized]);

  const toggleExpanded = useCallback(
    (expanded?: boolean) => {
      setIsExpanded((prev) => {
        const newIsExpanded = expanded ?? !prev;
        // Send resize event to parent iframe
        if (window.parent !== window) {
          const newHeight = newIsExpanded
            ? CHAT_WINDOW_DIMENSIONS.EXPANDED.HEIGHT
            : CHAT_WINDOW_DIMENSIONS.NORMAL.HEIGHT;
          const newWidth = newIsExpanded
            ? CHAT_WINDOW_DIMENSIONS.EXPANDED.WIDTH
            : CHAT_WINDOW_DIMENSIONS.NORMAL.WIDTH;
          sendResizeMessage(
            newIsExpanded ? "expanded" : "normal",
            newWidth,
            newHeight
          );
        }
        return newIsExpanded;
      });
    },
    [sendResizeMessage]
  );

  const checkAndHandleSlashCommand = useCallback(
    (message: Message) => {
      const { message: messageText = "" } = message;
      const isSlashCommand = messageText.startsWith("/");
      if (!isSlashCommand) return false;
      const command = messageText.match(/^\/([^ ]*)/)?.[1];

      switch (command) {
        case "feedback":
          dispatchEventToHost("onAgentforceMessagingLogEvent", {
            session_id: conversationId,
            message: messageText,
          });
          break;
        case "debug": {
          // show debug info (like session ID) as a system message
          const messageId = v4();
          let debugMessage = `Session Information\n- **Session ID**: ${conversationId || "Not connected"}`;
          if (conversationId) {
            debugMessage += `\n- **Session Status**: ${conversationStatus}\n- **Session Started At**: ${conversationStartedAt}`;
          }
          dispatch(
            addConversationEntry({
              id: messageId,
              message: debugMessage,
              sentTime: new Date().toISOString(),
              sender: "assistant",
              type: "system",
              direction: "incoming",
              position: "single",
            })
          );
          break;
        }
        default:
          // TODO show error message
          break;
      }

      return true;
    },
    [conversationId, conversationStartedAt, conversationStatus, dispatch]
  );

  const appendMessage = useCallback(
    (message: Message) => {
      if (!checkAndHandleSlashCommand(message)) {
        dispatch(sendMessage(message));
      }
      return Promise.resolve(); // TODO update this
    },
    [checkAndHandleSlashCommand, dispatch]
  );

  const sendMessageFn = useCallback(
    async (message: string) => {
      const userMessage: Message = {
        id: v4(),
        message,
        sentTime: new Date().toISOString(),
        sender: "user",
        direction: "outgoing",
        position: "single",
      };
      await appendMessage(userMessage);
    },
    [appendMessage]
  );

  // Define joinVoice for VoiceProvider
  const joinVoice = useCallback(async () => {
    if (!adaptersRef.current) return undefined;
    const conversationAdapter = adaptersRef.current.conversation;
    if (!conversationAdapter.adapterFeatures?.includes("voice"))
      return undefined;
    return (conversationAdapter as ConversationWithVoiceAdapter).joinVoice();
  }, []);

  return (
    <VoiceProvider joinVoice={joinVoice}>
      <ChatContextInner
        isChatOpen={isChatOpen}
        isSessionActive={isSessionActive}
        isTabActive={isTabActive}
        messages={messages}
        conversationStartedAt={conversationStartedAt}
        openChat={openChat}
        closeChat={closeChat}
        sendMessageFn={sendMessageFn}
        isExpanded={isExpanded}
        toggleExpanded={toggleExpanded}
        appendMessage={appendMessage}
        showProgressIndicator={showProgressIndicator}
        progressIndicatorText={progressIndicatorText}
        setClosedWidth={setClosedWidth}
        isSessionStarting={isSessionStarting}
        dispatch={dispatch}
        children={children}
      />
    </VoiceProvider>
  );
};

interface ChatContextProps
  extends Pick<
    ChatContextType,
    | "isChatOpen"
    | "isSessionActive"
    | "isTabActive"
    | "messages"
    | "conversationStartedAt"
    | "openChat"
    | "closeChat"
    | "isExpanded"
    | "toggleExpanded"
    | "appendMessage"
    | "showProgressIndicator"
    | "progressIndicatorText"
    | "setClosedWidth"
  > {
  sendMessageFn: ChatContextType["sendMessage"];
  chatDimensions?: ChatContextType["chatDimensions"];
  setClosedWidth: ChatContextType["setClosedWidth"];
  isSessionStarting: boolean;
  dispatch: ReturnType<typeof useAppDispatch>;
  children: React.ReactNode;
}

// New internal component to provide ChatContext and useVoice
const ChatContextInner = ({
  isChatOpen,
  isSessionActive,
  isTabActive,
  messages,
  conversationStartedAt,
  openChat,
  closeChat,
  sendMessageFn,
  isExpanded,
  toggleExpanded,
  appendMessage,
  showProgressIndicator,
  progressIndicatorText,
  chatDimensions = CHAT_WINDOW_DIMENSIONS,
  setClosedWidth,
  isSessionStarting,
  dispatch,
  children,
}: ChatContextProps) => {
  const {
    toggleVoiceMode,
    setIsVoiceModeLoading,
    requestMicrophonePermission,
    microphonePermission,
  } = useVoice();
  const toggleVoiceModeAfterStartingSession = useCallback(async () => {
    setIsVoiceModeLoading(true);

    if (!isSessionActive && !isSessionStarting) {
      if (microphonePermission !== "granted") {
        if (!(await requestMicrophonePermission())) {
          return;
        }
      }
      const startSessionResult = await dispatch(
        startConversation({ directToVoiceAction: true })
      );
      const sessionId = startSessionResult.payload;
      if (!sessionId) {
        setIsVoiceModeLoading(false);
        return;
      }
      // TODO improve this once Stu's `subscribeToSelectorOnce` code is available
      const unsubscribe = store.subscribe(() => {
        const state = store.getState();
        const sessionId = selectConversationId(state);
        if (sessionId) {
          unsubscribe();
          void toggleVoiceMode();
        }
      });

      return unsubscribe;
    } else {
      await toggleVoiceMode();
    }
  }, [
    isSessionActive,
    isSessionStarting,
    dispatch,
    toggleVoiceMode,
    setIsVoiceModeLoading,
    requestMicrophonePermission,
    microphonePermission,
  ]);

  const contextValue = useMemo<ChatContextType>(
    () => ({
      isChatOpen,
      isTabActive,
      isSessionActive,
      messages,
      conversationStartedAt,
      openChat,
      closeChat,
      sendMessage: sendMessageFn,
      isExpanded,
      toggleExpanded,
      appendMessage,
      chatDimensions,
      showProgressIndicator,
      progressIndicatorText,
      setClosedWidth,
      toggleVoiceMode,
      toggleVoiceModeAfterStartingSession,
    }),
    [
      isChatOpen,
      isTabActive,
      isSessionActive,
      messages,
      conversationStartedAt,
      openChat,
      closeChat,
      sendMessageFn,
      isExpanded,
      toggleExpanded,
      appendMessage,
      chatDimensions,
      showProgressIndicator,
      progressIndicatorText,
      setClosedWidth,
      toggleVoiceMode,
      toggleVoiceModeAfterStartingSession,
    ]
  );

  return (
    <ChatContext.Provider value={contextValue}>{children}</ChatContext.Provider>
  );
};
