import * as DropdownMenu from "@radix-ui/react-dropdown-menu";
import { ChevronDown, EllipsisVertical } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import { useCallback, useMemo, useState } from "react";
import { useConfigurationContext } from "../hooks/useConfigurationContext";
import { useAppDispatch, useAppSelector } from "../store/hooks";
import {
  endConversation,
  selectConversationStatus,
  selectIsSessionStarting,
  startConversation,
} from "../store/slices";
import { cn } from "../utils";
import { useChatContext } from "./ChatProvider";
import { ContractIcon } from "./icons/ContractIcon";
import { ExpandIcon } from "./icons/ExpandIcon";

// Header Icon Button Component
interface HeaderIconButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  children: React.ReactNode;
}

function HeaderIconButton({
  children,
  className,
  ...props
}: HeaderIconButtonProps) {
  const { chatHeader } = useConfigurationContext();
  const { iconHoverBackgroundColor } = chatHeader;

  return (
    <button
      className={cn(
        "rounded-full focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2 focus-visible:outline-none",
        className
      )}
      onMouseEnter={(e) => {
        e.currentTarget.style.backgroundColor = iconHoverBackgroundColor;
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.backgroundColor = "transparent";
      }}
      {...props}
    >
      {children}
    </button>
  );
}

// Expand/Collapse Button Component
function ExpandCollapseButton() {
  const { toggleExpanded, isExpanded } = useChatContext();
  const { chatHeader } = useConfigurationContext();
  const { textColor } = chatHeader;

  return (
    <HeaderIconButton
      onClick={() => toggleExpanded()}
      className="p-2.5"
      title={isExpanded ? "Collapse chat window" : "Expand chat window"}
      aria-expanded={isExpanded}
    >
      {isExpanded ? (
        <ContractIcon
          className="size-5 rotate-90"
          data-testid="contract-icon"
          style={{ color: textColor }}
        />
      ) : (
        <ExpandIcon
          className="size-5 rotate-90"
          data-testid="expand-icon"
          style={{ color: textColor }}
        />
      )}
    </HeaderIconButton>
  );
}

function OptionsMenuButton({
  setIsFocusTrapActive,
}: {
  setIsFocusTrapActive: React.Dispatch<React.SetStateAction<boolean>>;
}) {
  const dispatch = useAppDispatch();
  const sessionStatus = useAppSelector(selectConversationStatus);
  const isSessionStarting = useAppSelector(selectIsSessionStarting);
  const sessionInProgress = sessionStatus === "in-progress";
  const sessionEnded = sessionStatus === "ended";
  const [isOpen, setIsOpen] = useState(false);
  const { chatHeader } = useConfigurationContext();
  const { textColor } = chatHeader;

  const handleOpenChange = useCallback(
    (open: boolean) => {
      if (!open) {
        setTimeout(() => {
          setIsFocusTrapActive(true);
        }, 300);
        setIsOpen(open);
      } else {
        setIsFocusTrapActive(false);
        setIsOpen(open);
      }
    },
    [setIsFocusTrapActive]
  );

  const menuOptions = useMemo(
    () => [
      // {
      //   label: "Download Chat Transcript",
      //   onClick: () => console.log("Download Chat Transcript"),
      //   disabled: !sessionInProgress || true,
      //   className:
      //     // todo: disabled until we have a way to download the transcript
      //     // eslint-disable-next-line no-constant-binary-expression
      //     cn((!sessionInProgress || true) && "text-disabled-1 cursor-default"),
      // },
      ...(sessionInProgress
        ? [
            {
              label: "End Conversation",
              onClick: () => {
                if (!sessionInProgress) return;
                dispatch(endConversation());
              },
              className: !sessionInProgress
                ? "cursor-default text-disabled-1"
                : "text-(--neutral-10)",
            },
          ]
        : []),
      ...(sessionEnded
        ? [
            {
              label: "Start New Conversation",
              onClick: () => {
                if (isSessionStarting) return;
                dispatch(startConversation());
              },
            },
          ]
        : []),
    ],
    [dispatch, isSessionStarting, sessionInProgress, sessionEnded]
  );

  return (
    <DropdownMenu.Root open={isOpen} onOpenChange={handleOpenChange}>
      <DropdownMenu.Trigger asChild>
        <HeaderIconButton
          className="p-1.5"
          title="More options"
          aria-expanded={isOpen}
          aria-haspopup="menu"
        >
          <EllipsisVertical
            className="size-7"
            aria-hidden="true"
            style={{ color: textColor }}
          />
        </HeaderIconButton>
      </DropdownMenu.Trigger>

      <AnimatePresence>
        {isOpen && (
          <DropdownMenu.Portal forceMount>
            <DropdownMenu.Content
              asChild
              className="divide-border-1 border-container-3 z-50 min-w-[200px] divide-y-[0.5px] overflow-hidden rounded-lg border bg-white shadow-md ring-1 ring-gray-200/5"
              sideOffset={0}
              align="end"
              forceMount
              role="menu"
              aria-orientation="vertical"
            >
              <motion.div
                initial={{ opacity: 0, scale: 0.95, y: -8 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: -8 }}
                transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
                style={{ originX: 1, originY: 0 }}
              >
                {menuOptions.map((opt, i) => (
                  <DropdownMenu.Item
                    key={i}
                    onSelect={opt.onClick}
                    className={cn(
                      "relative flex cursor-pointer items-center px-4 py-4 text-sm transition-colors select-none",
                      "outline-none",
                      "hover:bg-black/5",
                      "focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-0 focus-visible:ring-inset first:focus-visible:rounded-t-lg last:focus-visible:rounded-b-lg",
                      "data-[highlighted]:bg-gray-100",
                      opt.className
                    )}
                    role="menuitem"
                  >
                    {opt.label}
                  </DropdownMenu.Item>
                ))}
              </motion.div>
            </DropdownMenu.Content>
          </DropdownMenu.Portal>
        )}
      </AnimatePresence>
    </DropdownMenu.Root>
  );
}

function MinimizeButton() {
  const { closeChat } = useChatContext();
  const { chatHeader } = useConfigurationContext();
  const { textColor } = chatHeader;

  return (
    <HeaderIconButton
      onClick={closeChat}
      className="p-1.5"
      title="Minimize chat"
    >
      <ChevronDown className="size-7" style={{ color: textColor }} />
    </HeaderIconButton>
  );
}

interface ChatHeaderProps {
  setIsFocusTrapActive: React.Dispatch<React.SetStateAction<boolean>>;
}
export function ChatHeader({ setIsFocusTrapActive }: ChatHeaderProps) {
  const { chatHeader, layout } = useConfigurationContext();
  const { agentName, backgroundColor, textColor } = chatHeader;
  const { mode } = layout;
  const sessionStatus = useAppSelector(selectConversationStatus);

  const headerOptions = useMemo(
    () => [
      {
        id: "expand-collapse",
        render: () => <ExpandCollapseButton />,
        hidden: mode == "inline",
      },
      {
        id: "options-menu",
        render: () => (
          <OptionsMenuButton setIsFocusTrapActive={setIsFocusTrapActive} />
        ),
        hidden: !sessionStatus,
      },
      {
        id: "minimize",
        render: () => <MinimizeButton />,
        hidden: mode == "inline",
      },
    ],
    [setIsFocusTrapActive, mode, sessionStatus]
  );

  return (
    <div
      className="flex h-[72px] items-center justify-between border-b border-gray-200 bg-white p-4"
      style={{ backgroundColor }}
    >
      <div className="flex items-center justify-center gap-2">
        <h2
          id="agent-name"
          className="font-avant-garde text-xl leading-none font-semibold"
          style={{ color: textColor }}
        >
          {agentName}
        </h2>
      </div>
      <div className="flex items-center gap-1">
        {headerOptions
          .filter((option) => !option.hidden)
          .map((option) => (
            <div key={option.id}>{option.render()}</div>
          ))}
      </div>
    </div>
  );
}
