import { Mic, MicOff, RotateCcw } from "lucide-react";
import { motion } from "motion/react";
import { useMemo, useState } from "react";
import { useConfigurationContext } from "../hooks/useConfigurationContext";

import { useVoice } from "../providers/VoiceProvider";
import { CloseIcon } from "./icons/CloseIcon";
import { MicrophoneVisualization } from "./MicrophoneVisualization";

interface ChatVoiceModeProps {
  children?: React.ReactNode;
}

const ConnectedListeningMode = () => {
  const { isMuted, toggleVoiceMode, toggleMute, isConnectingToAgent } =
    useVoice();
  const { chatVoice } = useConfigurationContext();
  const { backgroundColor, textColor, microphoneIcon } = chatVoice;

  const statusText = useMemo(
    () =>
      isConnectingToAgent
        ? "Waiting for agent to join..."
        : "Connected to voice chat",
    [isConnectingToAgent]
  );

  return (
    <motion.div
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 20 }}
      transition={{ duration: 0.15 }}
      className="flex w-full items-center gap-2 rounded-full border py-2.5 pr-3 pl-2"
      style={{
        backgroundColor,
        borderColor: backgroundColor,
      }}
      data-testid="chat-listening-mode"
      role="status"
      aria-label="Voice mode"
    >
      <motion.div className="relative flex items-center justify-center">
        <div className="flex h-8 items-center justify-center pl-2">
          <MicrophoneVisualization color={textColor} />
        </div>
      </motion.div>
      <div className="flex-1">
        <div
          className="text-sm font-medium whitespace-nowrap select-none"
          aria-live="polite"
          style={{ color: textColor + "99" }}
        >
          {statusText}
        </div>
      </div>
      <div className="flex-1" />

      <button
        onClick={toggleMute}
        className="rounded-full p-1.5 hover:bg-white/10 focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:outline-none"
        style={
          {
            color: isMuted
              ? microphoneIcon.textColorMuted
              : microphoneIcon.textColorUnmuted,
            "--tw-ring-offset-color": backgroundColor,
          } as React.CSSProperties
        }
        title={isMuted ? "Unmute microphone" : "Mute microphone"}
      >
        {isMuted ? (
          <MicOff className="size-6" aria-hidden="true" />
        ) : (
          <Mic className="size-6" aria-hidden="true" />
        )}
      </button>
      <div className="h-8 border-l" style={{ borderColor: textColor + "33" }} />
      <button
        onClick={toggleVoiceMode}
        title="Exit voice mode"
        className="rounded-full p-1.5 hover:bg-white/10 focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:outline-none"
        style={
          {
            color: textColor,
            "--tw-ring-offset-color": backgroundColor,
          } as React.CSSProperties
        }
      >
        <CloseIcon
          className="size-6"
          style={{ color: textColor }}
          aria-hidden="true"
        />
      </button>
    </motion.div>
  );
};

export const ChatListeningMode = ({ children }: ChatVoiceModeProps) => {
  const {
    toggleVoiceMode,
    isConnected,
    isConnecting,
    toggleMute,
    isOtherVoiceMode,
    handleRetryJoinVoice,
    isConnectingToAgent,
    isMuted,
  } = useVoice();
  const { chatVoice } = useConfigurationContext();
  const { backgroundColor, textColor, microphoneIcon } = chatVoice;

  const [hasTriedToConnect, _setHasTriedToConnect] = useState(false);
  //   useEffect(() => {
  //     if (hasTriedToConnect) return;
  //     setHasTriedToConnect(true);

  //     if (isConnecting || isConnected) return;

  //     toggleVoiceMode();
  //   }, [hasTriedToConnect, isConnected, isConnecting, toggleVoiceMode]);

  // This inner function is a bit of a hack to make this component play nicely with
  // `<AnimatePresence>` which doesn't like when the contents of the component change
  // due to the props from `useVoice` affecting its output. By wrapping everything
  // inside a "virtual" component, `AnimatePresence` only sees that component and
  // doesn't care about what's actually being rendered inside it. This could be
  // elevated to a top-level component, but since it's _only_ needed to make this
  // work, that isn't really necessary.
  const RenderForAnimatePresence = () => {
    if (isOtherVoiceMode) {
      return (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: 20 }}
          transition={{ duration: 0.15 }}
          className="flex w-full items-center gap-2 rounded-full border py-2.5 pr-3 pl-2"
          style={{
            backgroundColor,
            borderColor: backgroundColor,
          }}
          data-testid="other-voice-mode"
        >
          <div className="flex-1">
            <div
              className="pl-4 text-sm font-medium whitespace-nowrap select-none"
              style={{ color: textColor + "99" }}
            >
              Connected to voice chat from another tab
            </div>
          </div>
          <div className="flex-1" />
          <button
            onClick={toggleMute}
            className="rounded-full p-1.5 hover:bg-white/10 focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-black focus:outline-none"
            style={{
              color: isMuted
                ? microphoneIcon.textColorMuted
                : microphoneIcon.textColorUnmuted,
            }}
            title={isMuted ? "Unmute microphone" : "Mute microphone"}
          >
            {isMuted ? (
              <MicOff className="size-6" aria-hidden="true" />
            ) : (
              <Mic className="size-6" aria-hidden="true" />
            )}
          </button>
          <div className="h-8 border-l" role="separator" />

          <button
            onClick={toggleVoiceMode}
            className="group flex items-center justify-center rounded-full p-1.5 transition-colors hover:bg-white/10 focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-black focus:outline-none"
            title="Exit voice mode"
          >
            <CloseIcon
              className="size-6 text-white"
              fill="#ffffff"
              aria-hidden="true"
            />
          </button>
        </motion.div>
      );
    }

    if (isConnected) {
      return <ConnectedListeningMode />;
    }

    return (
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: 20 }}
        transition={{ duration: 0.15 }}
        className="flex w-full items-center gap-2 rounded-full border py-2.5 pr-3 pl-2"
        style={{
          backgroundColor,
          borderColor: backgroundColor,
        }}
        data-testid="chat-listening-mode"
      >
        <div className="flex h-8 items-center justify-center pl-2">
          <MicrophoneVisualization color={textColor} />
        </div>
        <div className="flex-1">
          <div
            className="text-sm font-medium whitespace-nowrap select-none"
            style={{ color: textColor + "99" }}
          >
            {!hasTriedToConnect || isConnecting
              ? "Connecting to voice chat..."
              : "Failed to connect to voice chat"}
          </div>
        </div>
        <div className="flex items-center gap-2">
          {!isConnecting && !isConnectingToAgent && !isConnected && (
            <button
              onClick={handleRetryJoinVoice}
              className="rounded-full p-1.5 transition-colors hover:bg-gray-800"
              title="Retry connection"
            >
              <RotateCcw className="size-5" style={{ color: textColor }} />
            </button>
          )}
          <button
            onClick={toggleMute}
            className="rounded-full p-1.5 hover:bg-white/10 focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-black focus:outline-none"
            style={{
              color: isMuted
                ? microphoneIcon.textColorMuted
                : microphoneIcon.textColorUnmuted,
            }}
            title={isMuted ? "Unmute microphone" : "Mute microphone"}
          >
            {isMuted ? (
              <MicOff className="size-6" aria-hidden="true" />
            ) : (
              <Mic className="size-6" aria-hidden="true" />
            )}
          </button>
          <div
            className="h-8 border-l"
            style={{ borderColor: textColor + "33" }}
          />
          <button
            onClick={toggleVoiceMode}
            className="rounded-full p-1.5 text-white hover:bg-white/10 focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-black focus:outline-none"
            title="Exit voice mode"
          >
            <CloseIcon className="size-6" style={{ color: textColor }} />
          </button>
          {children && (
            <>
              <div
                className="h-8 border-l"
                style={{ borderColor: textColor + "33" }}
              />
              {children}
            </>
          )}
        </div>
      </motion.div>
    );
  };

  return <RenderForAnimatePresence />;
};
