import { miawAdapterDefinition } from "../../adapters/miaw";
import { store } from "../../store";
import {
  addParticipant,
  ConversationStatus,
  removeParticipant,
  sessionTerminated,
  setConversationStatus,
  setCurrentConversationId,
  updateConversationEntry,
} from "../../store/slices";

interface CreateMiawAdapterListenerProps {
  getMiawAdapter: () => Adapters | undefined;
  getAdapterDefinition: () => AdapterDefinition | undefined;
}

export const createMiawAdapterListener = ({
  getMiawAdapter,
  getAdapterDefinition,
}: CreateMiawAdapterListenerProps): AdapterListener => {
  return {
    onAdapterCreated: (adapter: Adapter) =>
      console.debug(`Adapter ${adapter.adapterType} created`, adapter),
    onAdapterDestroyed: (adapter: Adapter) =>
      console.debug(`Adapter ${adapter.adapterType} destroyed`, adapter),
    onAdapterEvent: (event: AdapterEvent) => {
      console.debug(
        `Received adapter ${event.adapter.adapterType} event ${event.eventName}`,
        event
      );

      const adapter = getMiawAdapter();
      if (!adapter) return;

      const adapterDefinition = getAdapterDefinition();
      if (
        !adapterDefinition ||
        adapterDefinition.name !== miawAdapterDefinition.name
      )
        return;

      switch (event.eventName) {
        case "startConversation": {
          const sessionData = event.eventData as { sessionId: string };
          store.dispatch(setCurrentConversationId(sessionData.sessionId));
          store.dispatch(setConversationStatus(ConversationStatus.InProgress));
          break;
        }
        case "receivedMessage": {
          const message = event.eventData as Message;
          store.dispatch(updateConversationEntry(message));
          break;
        }
        case "participantChanged": {
          const participantChanged =
            event.eventData as ConversationParticipantChangedEntryPayload;
          if (participantChanged.entries[0].operation === "add") {
            store.dispatch(
              addParticipant(participantChanged.entries[0].participant)
            );
          } else if (participantChanged.entries[0].operation === "remove") {
            store.dispatch(
              removeParticipant(participantChanged.entries[0].participant)
            );
          }
          break;
        }
        case "endConversation": {
          store.dispatch(setConversationStatus(ConversationStatus.Ended));
          break;
        }
        case "sessionTerminated":
          store.dispatch(sessionTerminated());
          break;
      }
    },
  };
};
