/**
 * Cleans a message by removing excessive whitespace and newlines
 * @param message - The raw message to clean
 * @returns The cleaned message
 */
export function cleanMessage(message: string): string {
  return message
    .replace(/\t/g, " ") // Convert tabs to spaces
    .replace(/[ ]{2,}/g, " ") // Replace multiple spaces with single space
    .replace(/^[ ]+|[ ]+$/gm, "") // Remove leading/trailing spaces from each line
    .replace(/\n{3,}/g, "\n\n") // Limit consecutive newlines to max 2
    .replace(/^\n+|\n+$/g, ""); // Remove leading/trailing newlines from message
}
