import * as Popover from "@radix-ui/react-popover";
import { ArrowUp, Loader } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import { KeyboardEvent, useCallback, useEffect, useRef, useState } from "react";
import { isMobile } from "react-device-detect";
import { getAgentApiConfiguration } from "../connectors";
import { useConfigurationContext } from "../hooks/useConfigurationContext";
import { useVoice } from "../providers/VoiceProvider";
import {
  useAppDispatch,
  useAppSelector,
  useScriptResolver,
} from "../store/hooks";
import {
  ConversationStatus,
  getAllowVoiceMode,
  selectConversationStatus,
  selectIsLoading,
  selectIsSessionStarting,
  startConversation,
  stopMessage,
} from "../store/slices";
import { cleanMessage, cn } from "../utils";
import {
  TEXTAREA_INPUT_MAX_HEIGHT,
  TEXTAREA_INPUT_MIN_HEIGHT,
} from "../utils/constants";
import { useChatContext } from "./ChatProvider";
import { ChatListeningMode } from "./ChatVoiceMode";
import { ChatBubbleIcon } from "./icons/ChatBubbleIcon";
import { WaveformIcon } from "./icons/WaveformIcon";

export function ChatInput({
  onTextAreaHeightChange,
  textAreaHeight,
}: {
  onTextAreaHeightChange: (height: number) => void;
  textAreaHeight: number;
}) {
  const [message, setMessage] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const { sendMessage, isChatOpen } = useChatContext();
  const {
    isVoiceMode,
    isOtherVoiceMode,
    isVoiceModeLoading,
    toggleVoiceMode,
    voiceModeError,
  } = useVoice();

  const { chatInput } = useConfigurationContext();
  const { poweredByEnabled, backgroundColor, placeholder, textColor } =
    chatInput;

  const { url } = useScriptResolver();
  const allowVoiceMode = useAppSelector(getAllowVoiceMode);

  const enableStopMessage = getAgentApiConfiguration()?.enableStopMessage;
  const isLoading = useAppSelector(selectIsLoading);
  const isSessionStarting = useAppSelector(selectIsSessionStarting);
  const isSessionActive =
    useAppSelector(selectConversationStatus) === ConversationStatus.InProgress;
  const dispatch = useAppDispatch();
  const [isFocused, setIsFocused] = useState(false);

  const handleSubmit = useCallback(async () => {
    if (!message.trim()) return;

    try {
      setIsSubmitting(true);
      setMessage("");
      // Reset textarea height to default
      if (textareaRef.current) {
        textareaRef.current.style.height = `${TEXTAREA_INPUT_MIN_HEIGHT}px`;
        onTextAreaHeightChange(TEXTAREA_INPUT_MIN_HEIGHT);
      }

      // Clean the message to prevent excessive newlines and whitespace
      const cleanedMessage = cleanMessage(message);

      await sendMessage(cleanedMessage);
    } catch (error) {
      console.error("Failed to send message:", error);
    } finally {
      setIsSubmitting(false);
    }
  }, [message, onTextAreaHeightChange, sendMessage]);

  const handleCancel = useCallback(() => {
    if (!enableStopMessage) {
      return;
    }
    dispatch(stopMessage());
  }, [dispatch, enableStopMessage]);

  const handleKeyPress = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault(); // Always prevent default for Enter without shift
        // Do nothing if
        // - Session is not active
        // - Message is being submitted
        // - Chat is loading
        if (!isSessionActive || isSubmitting || isLoading) {
          return;
        }
        handleSubmit();
        if (isMobile) {
          textareaRef.current?.blur();
        }
      }
    },
    [isSessionActive, isSubmitting, isLoading, handleSubmit]
  );

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = `${TEXTAREA_INPUT_MIN_HEIGHT}px`;
      textareaRef.current.focus();
    }
  }, [isChatOpen]);

  const getScaledHeight = useCallback((windowHeight = window.innerHeight) => {
    if (windowHeight >= 700) return TEXTAREA_INPUT_MAX_HEIGHT;
    if (windowHeight <= 300) return TEXTAREA_INPUT_MIN_HEIGHT;

    // Linear interpolation for heights between 300px and 700px
    const ratio = (windowHeight - 300) / 400;
    return (
      TEXTAREA_INPUT_MIN_HEIGHT +
      ratio * (TEXTAREA_INPUT_MAX_HEIGHT - TEXTAREA_INPUT_MIN_HEIGHT)
    );
  }, []);

  // Update textarea dimensions on window resize
  useEffect(() => {
    const handleResize = () => {
      if (textareaRef.current) {
        const maxHeight = getScaledHeight();

        textareaRef.current.style.maxHeight = `${maxHeight}px`;

        // Adjust current height if needed
        if (textareaRef.current.scrollHeight > maxHeight) {
          textareaRef.current.style.height = `${maxHeight}px`;
          onTextAreaHeightChange(maxHeight);
        }
      }
    };

    window.addEventListener("resize", handleResize);
    // Cleanup to prevent multiple listeners.
    return () => window.removeEventListener("resize", handleResize);
  }, [getScaledHeight, onTextAreaHeightChange]);

  const handleInput = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const textarea = e.target;
      setMessage(textarea.value);

      // Reset height to auto to get the correct scrollHeight
      textarea.style.height = "auto";

      const maxHeight = getScaledHeight();
      // Set the height to match the content, but respect max height
      const newHeight = Math.min(textarea.scrollHeight, maxHeight);
      textarea.style.height = `${newHeight}px`;
      onTextAreaHeightChange(newHeight);
    },
    [getScaledHeight, onTextAreaHeightChange]
  );

  const textareaIsLarge = textAreaHeight > TEXTAREA_INPUT_MIN_HEIGHT;

  const showVoiceInput = (isLoading && enableStopMessage) || !!message.trim();

  const minHeight = TEXTAREA_INPUT_MIN_HEIGHT;
  const maxHeight = getScaledHeight();

  const handleStartNewConversation = useCallback(() => {
    // Dispatch an action or update state to reset the session status
    dispatch(startConversation());
  }, [dispatch]);

  return (
    <div
      className={`relative mx-4 ${poweredByEnabled ? "mb-3" : "my-4"} w-full`}
    >
      <AnimatePresence mode="wait">
        {isVoiceMode ? (
          <ChatListeningMode key="listening" />
        ) : !isSessionStarting && !isSessionActive ? (
          <motion.div
            key="connect"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 20 }}
            transition={{ duration: 0.15 }}
            className="flex w-full items-center justify-center gap-2 text-white"
          >
            <button
              onClick={handleStartNewConversation}
              className="flex flex-1 items-center justify-center gap-2 rounded-full bg-black p-2 hover:bg-gray-800"
            >
              <ChatBubbleIcon className="chat-icon h-5 w-5" />
              Start New Conversation
            </button>
            <button
              data-testid="start-new-conversation-voice-button"
              onClick={() => toggleVoiceMode()}
              className="rounded-full border border-black bg-white p-2 hover:bg-gray-200"
            >
              <WaveformIcon className="text-black" />
            </button>
          </motion.div>
        ) : (
          <motion.div
            key="input"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 20 }}
            transition={{ duration: 0.15 }}
            className={cn(
              "flex w-full items-end justify-center gap-2 overflow-hidden border p-2 transition-colors duration-300 hover:border-gray-400",
              textareaIsLarge ? "rounded-[28px]" : "rounded-full",
              isFocused ? "border-gray-400" : "border-gray-300"
            )}
            style={{ backgroundColor }}
            data-testid="chat-input-container"
          >
            {/* <button
                onClick={() => {
                  console.log("Attachment clicked");
                }}
                className="flex items-center justify-center rounded-full p-2 hover:bg-black/5"
              >
                <Plus className="size-6 text-gray-500" />
              </button> */}
            <textarea
              ref={textareaRef}
              value={message}
              onChange={handleInput}
              onKeyDown={handleKeyPress}
              onFocus={() => setIsFocused(true)}
              onBlur={() => setIsFocused(false)}
              aria-label="Chat message"
              placeholder={placeholder}
              rows={1}
              id="chat-input"
              aria-multiline="true"
              aria-describedby={isLoading ? "chat-input-status" : undefined}
              className={cn(
                "font-segoe-ui placeholder:text-on-surface-1 flex-1 resize-none self-center overflow-y-auto rounded-none border-none py-2 pl-4 placeholder:select-none focus:outline-none"
              )}
              style={{
                minHeight: `${minHeight}px`,
                maxHeight: `${maxHeight}px`,
                color: textColor,
              }}
            />
            {/* Voice input button */}
            {showVoiceInput ? (
              <button
                onClick={
                  enableStopMessage && isLoading ? handleCancel : handleSubmit
                }
                disabled={
                  isSubmitting ||
                  (!enableStopMessage && isLoading) ||
                  isSessionStarting ||
                  !isSessionActive
                }
                className={cn(
                  "mr-1 mb-1 flex size-8 items-center justify-center rounded-full bg-black text-white transition-colors duration-200",
                  isSessionActive && "hover:bg-black/80 disabled:bg-black/25"
                )}
                title={isLoading ? "Cancel message" : "Send message"}
              >
                {isLoading && enableStopMessage && !isSessionStarting ? (
                  <div className="size-[10px] bg-white" />
                ) : (
                  <ArrowUp className="size-5 text-white" />
                )}
              </button>
            ) : allowVoiceMode ? (
              <div className="flex items-center">
                <Popover.Root open={!!voiceModeError}>
                  <Popover.Trigger asChild>
                    <button
                      onClick={toggleVoiceMode}
                      title="Use voice mode"
                      className={cn(
                        "flex items-center justify-center rounded-full p-2",
                        isSessionActive && "hover:bg-black/5"
                      )}
                      disabled={
                        !isSessionActive ||
                        isOtherVoiceMode ||
                        isVoiceModeLoading
                      }
                    >
                      {isVoiceModeLoading ? (
                        <Loader className="size-6 animate-spin" />
                      ) : (
                        <WaveformIcon
                          className={cn(
                            "text-black",
                            voiceModeError && "text-error-1"
                          )}
                        />
                      )}
                    </button>
                  </Popover.Trigger>
                  {voiceModeError && (
                    <Popover.Portal forceMount>
                      <Popover.Content
                        side="top"
                        align="center"
                        asChild
                        collisionPadding={8}
                        forceMount
                      >
                        <motion.div
                          initial={{ opacity: 0, scale: 0.9, y: 8 }}
                          animate={{ opacity: 1, scale: 1, y: 0 }}
                          exit={{ opacity: 0, scale: 0.9, y: 8 }}
                          transition={{
                            duration: 0.15,
                            ease: [0.16, 1, 0.3, 1],
                          }}
                          className="bg-error-container-1 font-avant-garde text-on-error-1 z-50 rounded-lg px-3 py-2 text-sm font-medium shadow-md select-none"
                        >
                          {voiceModeError}
                          <Popover.Arrow className="fill-error-container-1" />
                        </motion.div>
                      </Popover.Content>
                    </Popover.Portal>
                  )}
                </Popover.Root>
              </div>
            ) : null}
          </motion.div>
        )}
      </AnimatePresence>
      {poweredByEnabled && (
        <div className="font-avant-garde -mt-5 flex items-center justify-center pt-8 text-center text-xs text-[#444444] select-none">
          Powered by{" "}
          <img
            src={url("agentforce.svg")}
            alt="Agentforce"
            className="mt-0.5 ml-1"
          />
        </div>
      )}
    </div>
  );
}
