import { ReactNode, useEffect } from "react";
import { useDispatch } from "react-redux";
import { defaultUiConfiguration } from "../defaults/ui";
import { updateUI } from "../store/slices/ui";

interface ConfigurationProviderProps {
  children: ReactNode;
  uiConfiguration?: DeepPartialUIConfiguration;
}

export function ConfigurationProvider({
  children,
  uiConfiguration,
}: ConfigurationProviderProps) {
  const dispatch = useDispatch();

  // Update Redux state when uiConfiguration props change
  useEffect(() => {
    if (uiConfiguration) {
      const { layout: defaultLayout, components: defaultComponents } =
        defaultUiConfiguration as Required<UIConfiguration>;

      const { layout = {}, components = {} } = uiConfiguration;

      // Destructure all component configurations
      const {
        chatInput: defaultChatInput,
        chatHeader: defaultChatHeader,
        chatFab: defaultChatFab,
        chatVoice: defaultChatVoice,
        chatWindow: defaultChatWindow,
        chatMessage: defaultChatMessage,
      } = defaultComponents;

      // Destructure user-provided component configurations with defaults as user may not provide all components
      const {
        chatInput = {},
        chatHeader = {},
        chatFab = {},
        chatVoice = {},
        chatWindow = {},
        chatMessage = {},
      } = components;

      // Update UI configuration, using defaults for any missing values
      dispatch(
        updateUI({
          layout: {
            ...defaultLayout,
            ...layout,
          },
          components: {
            chatInput: {
              ...defaultChatInput,
              ...chatInput,
            },
            chatHeader: {
              ...defaultChatHeader,
              ...chatHeader,
            },
            chatFab: {
              ...defaultChatFab,
              ...chatFab,
            },
            chatVoice: {
              ...defaultChatVoice,
              ...chatVoice,
            },
            chatWindow: {
              ...defaultChatWindow,
              ...chatWindow,
            },
            chatMessage: {
              ...defaultChatMessage,
              ...chatMessage,
            },
          },
        })
      );
    }
  }, [dispatch, uiConfiguration]);

  return <>{children}</>;
}
