/**
 * Subscribes to events related to participants speaking and calculates delta between
 * a user finishing speaking and the agent responding
 *
 * This is reported to O11y. Future iterations may allow for more options/interaction.
 */

import {
  ParticipantEvent,
  RemoteParticipant,
  type Room,
  RoomEvent,
} from "livekit-client";
import { useEffect } from "react";
import { useO11y } from "./useO11y";

interface SpeakingTime {
  who: "local" | "remote";
  what: "start" | "end";
  when: number;
  diffFromPrevious: number;
}

export const useAgentSpeakingDeltas = (room?: Room) => {
  const { log } = useO11y();

  useEffect(() => {
    if (!room) return;

    const speakingTimes: SpeakingTime[] = [];

    const handleIsSpeaking =
      (who: "local" | "remote") => (isSpeaking: boolean) => {
        const previous = speakingTimes[speakingTimes.length - 1];
        const when = +new Date();
        const diffFromPrevious = previous ? when - previous.when : 0;
        speakingTimes.push({
          who,
          what: isSpeaking ? "start" : "end",
          when,
          diffFromPrevious,
        });

        // log when the speaker is the agent and it has started speaking
        if (previous?.who === "local" && who === "remote" && isSpeaking) {
          // calculate the average across all the available data
          const remoteSpeakingTimes = speakingTimes.filter(
            (time, index) =>
              index !== 0 &&
              time.who === "remote" &&
              time.what === "start" &&
              speakingTimes[index - 1]?.who !== "remote"
          );
          const average =
            remoteSpeakingTimes.length === 0
              ? 0
              : Math.round(
                  remoteSpeakingTimes.reduce(
                    (total, { diffFromPrevious }) => total + diffFromPrevious,
                    0
                  ) / remoteSpeakingTimes.length
                );
          log(
            "voice-lag",
            `speaking delta (agent response): ${diffFromPrevious}ms, average ${average}ms`
          );
          console.debug("voice-lag", {
            type: "delta: agent response",
            value: `${diffFromPrevious}ms`,
            average: `${average}ms`,
          });
        }

        // truncate to 100 entries
        if (speakingTimes.length > 100) {
          speakingTimes.splice(0, speakingTimes.length - 100);
        }
      };

    const remoteSpeaking = handleIsSpeaking("remote");
    const handleParticipantConnected = (participant: RemoteParticipant) => {
      participant.on(ParticipantEvent.IsSpeakingChanged, remoteSpeaking);
    };
    const handleParticipantDisconnected = (participant: RemoteParticipant) => {
      participant.off(ParticipantEvent.IsSpeakingChanged, remoteSpeaking);
    };
    room.on(RoomEvent.ParticipantConnected, handleParticipantConnected);
    room.on(RoomEvent.ParticipantDisconnected, handleParticipantDisconnected);

    // subscribe to any current `remoteParticipants`
    room.remoteParticipants.forEach((participant) => {
      participant.on(ParticipantEvent.IsSpeakingChanged, remoteSpeaking);
    });

    const localSpeaking = handleIsSpeaking("local");
    room.localParticipant.on(ParticipantEvent.IsSpeakingChanged, localSpeaking);

    return () => {
      room.remoteParticipants.forEach((participant) => {
        try {
          participant.off(ParticipantEvent.IsSpeakingChanged, remoteSpeaking);
        } catch (ex) {
          console.error(
            "Unsuccessfully tried to stop listening for remote participant events",
            participant,
            ex
          );
        }
      });
      room.off(RoomEvent.ParticipantConnected, handleParticipantConnected);
      room.off(
        RoomEvent.ParticipantDisconnected,
        handleParticipantDisconnected
      );
      room.localParticipant.off(
        ParticipantEvent.IsSpeakingChanged,
        localSpeaking
      );
    };
  }, [room, log]);
};
