import { motion } from "motion/react";
import { useConfigurationContext } from "../hooks/useConfigurationContext";
import { TEXTAREA_INPUT_MIN_HEIGHT } from "../utils/constants";

export function ChatProgressIndicator({
  message,
  textAreaHeight = TEXTAREA_INPUT_MIN_HEIGHT,
}: {
  message?: string;
  textAreaHeight?: number;
}) {
  const { chatInput } = useConfigurationContext();
  const { poweredByEnabled } = chatInput;

  // Lower the padding when powered by is not shown
  const bottomPadding = textAreaHeight + (poweredByEnabled ? 0 : -24);

  return (
    <motion.div
      data-testid="progress-indicator"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 20 }}
      transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
      className="absolute bottom-[76px] left-0 z-50 ml-4 flex items-center justify-start"
      style={{ paddingBottom: `${bottomPadding}px` }}
    >
      <div className="flex items-center gap-3 text-sm text-gray-700">
        <div className="flex shrink-0 items-center justify-center rounded-md bg-white">
          <div className="relative h-7 w-7">
            <motion.div
              data-testid="outer-spinner"
              className="absolute inset-0 h-7 w-7 rounded-full border-[3px] border-gray-700"
              animate={{
                rotate: 360,
              }}
              transition={{
                duration: 1.5,
                repeat: Infinity,
                ease: "linear",
              }}
              style={{
                clipPath:
                  "polygon(50% 50%, 50% 0%, 100% 0%, 100% 100%, 0% 100%, 0% 50%)",
              }}
            />
            <motion.div
              data-testid="inner-spinner"
              className="absolute inset-0 m-auto h-4 w-4 rounded-full border-[3px] border-gray-700 border-b-transparent"
              animate={{
                rotate: -360,
              }}
              transition={{
                duration: 2,
                repeat: Infinity,
                ease: "linear",
              }}
              style={{ clipPath: "inset(0 0 50% 0)" }}
            />
          </div>
        </div>
        <span className="text-sm">{message}</span>
      </div>
    </motion.div>
  );
}
