import { v4 } from "uuid";
import {
  createTokenManager,
  doDelete,
  doPost,
  isTokenStatus,
} from "../../utils";

declare const __STRIP_PATH__: string;

type AgentApiProps = AgentApiConfiguration & {
  currentSessionId?: string;
  getData: () => Record<string, unknown>;
  setData: (data: Record<string, unknown>) => void;
};

interface Endpoints {
  messages: string;
  messagesStream: string;
  session: string;
  endSession: string;
}

const generateSessionKey = () => v4();

const DEFAULT_ENDPOINT =
  "https://api.salesforce.com/einstein/ai-agent/v1.1/agents/{AGENT_ID}/sessions";
const DEFAULT_VOICE_ENDPOINT =
  "https://api.salesforce.com/einstein/ai-agent/v1.1/realtime/sessions/{SESSION_ID}/join";
export const createAgentApi = ({
  agentId,
  authToken,
  authTokenEndpoint,
  apiKey,
  domainUrl,
  enableStreaming = true,
  enableSurfaces = false,
  enableStopMessage,
  endpoint = DEFAULT_ENDPOINT,
  voiceEndpoint = DEFAULT_VOICE_ENDPOINT,
  tenantId,
  region,
  currentSessionId,
  getData,
  setData,
  additionalHeaders,
}: AgentApiProps): AgentAdapterApi => {
  const endpointRequiresAgentId = endpoint.match(/\{(?:0|AGENT_ID)\}/);
  if (endpointRequiresAgentId && !agentId) {
    throw new Error(
      "agentId must be specified unless an endpoint is provided that does not require it"
    );
  }
  if (endpoint.includes("{0}")) {
    console.warn(
      "`endpoint` URL format has changed; use {AGENT_ID} instead of {0}"
    );
  }

  let tokenManager: ReturnType<typeof createTokenManager> | undefined;
  let tokenUrl: string | undefined;
  if (authTokenEndpoint) {
    if (authTokenEndpoint.includes("{AGENT_ID}") && !agentId) {
      throw new Error(
        "agentId must be specified unless an authTokenEndpoint is provided that does not require it"
      );
    }
    tokenUrl = authTokenEndpoint.replace(/\{AGENT_ID\}/g, agentId!);
  } else if (!apiKey && !authToken) {
    // guess the bootstrap URL
    tokenUrl = new URL(
      `${location.pathname.replace(/\/$/, "")}/agentforce/bootstrap?agentid=${agentId}`,
      location.href
    ).toString();
  }
  if (tokenUrl) {
    tokenManager = createTokenManager({
      authEndpoint: tokenUrl,
    });
  }

  const getAuthToken = async (): Promise<AuthToken | undefined> => {
    if (authToken) return { access_token: authToken } as unknown as AuthToken;
    if (!tokenManager) return undefined;

    const token = await tokenManager.getAuthToken();
    if (!isTokenStatus(token)) {
      return token;
    }

    console.error("Did not receive a valid token", token);
    return undefined;
  };

  const createDefaultHeaders = async () => {
    const headers = new Headers();
    headers.append("Content-Type", "application/json");
    if (apiKey) {
      headers.append("Authorization", `API_KEY ${apiKey}`);
    } else {
      const token = await getAuthToken();
      headers.append("Authorization", `Bearer ${token?.access_token}`);
    }
    if (tenantId) {
      headers.append("x-sfdc-tenant-id", tenantId);
    }
    if (region) {
      headers.append("x-salesforce-region", region);
    }

    if (additionalHeaders) {
      for (const [header, value] of Object.entries(additionalHeaders)) {
        headers.append(header, value);
        console.log(
          `Appending additional header from local config to request: ${header}: ${value}`
        );
      }
    }

    return headers;
  };

  const getContextVariables = (): Array<CustomContextVariable> => {
    return (getData()?.contextVariables as Array<CustomContextVariable>) || [];
  };

  const resolvedEndpoint = endpointRequiresAgentId
    ? endpoint.replace(/\{(?:0|AGENT_ID)\}/, agentId!)
    : endpoint;
  const sessionKey = generateSessionKey();
  let sessionId: string | undefined = currentSessionId;
  let sequenceId = 0;
  let currentRequestController: AbortController | undefined;

  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

  // Helper functions to access data from getData()
  const getEndpoints = (): Endpoints | undefined => {
    return getData().endpoints as Endpoints | undefined;
  };

  const startSession = async (): Promise<{
    sessionId: string;
    messages: AgentApiMessage[];
    data: Record<string, unknown>;
  }> => {
    sequenceId = 0;

    const headers = await createDefaultHeaders();

    return await doPost(
      resolvedEndpoint,
      {
        externalSessionKey: sessionKey,
        instanceConfig: {
          endpoint: domainUrl,
        },
        tz: timezone,
        variables: [
          {
            name: "$Context.EndUserLanguage",
            type: "Text",
            value: "en_US",
          },
          {
            name: "$Context.Timezone",
            type: "Text",
            value: timezone,
          },
          ...getContextVariables(),
        ],
        featureSupport: enableStreaming ? "Streaming" : "",
        ...(enableStreaming && {
          streamingCapabilities: {
            chunkTypes: ["Text"],
          },
        }),
        ...(enableSurfaces && {
          surfaceConfig: {
            surfaceType: "AgentforceMessaging",
          },
        }),
        bypassUser: true,
      },
      {
        headers,
        credentials: "include",
      }
    ).then(async (response) => {
      const text = await response.text();
      if (!text) {
        throw new Error("Session start response was empty");
      }
      const json = JSON.parse(text);
      sessionId = json["sessionId"];
      if (!sessionId) {
        throw new Error("Failed to create session");
      }
      const respMessages: AgentApiMessage[] = json.messages ?? [];
      const stripToPath = (url: string) =>
        __STRIP_PATH__ ? url.replace(/^https?:\/\/[^/]+/, __STRIP_PATH__) : url;

      // Store endpoints in data rather than locally
      const endpoints = {
        messages: stripToPath(json._links.messages.href),
        messagesStream: stripToPath(json._links.messagesStream.href),
        session: stripToPath(json._links.session.href),
        endSession: stripToPath(json._links.end.href),
      };

      const data = {
        endpoints,
      };

      // Update data with the new endpoints
      setData(data);

      return {
        sessionId,
        messages: respMessages,
        data,
      };
    });
  };

  return {
    startSession,
    getSessionId: function (): string | undefined {
      return sessionId;
    },
    setSessionId: (newSessionId) => {
      sessionId = newSessionId;
    },
    setData,
    sendMessage: async (messageText: string) => {
      if (!sessionId) {
        throw new Error("No session is in progress");
      }

      const endpoints = getEndpoints();
      if (!endpoints?.messages) {
        throw new Error("Endpoints not initialized");
      }

      if (enableStopMessage) {
        // Cancel any existing request
        currentRequestController?.abort();
      }

      // Create new controller for this request
      currentRequestController = new AbortController();

      const headers = await createDefaultHeaders();
      return doPost(
        endpoints.messages,
        {
          message: {
            sequenceId,
            type: "Text",
            text: messageText,
          },
          variables: [
            {
              name: "$Context.Timezone",
              type: "Text",
              value: timezone,
            },
            ...getContextVariables(),
          ],
        },
        { headers, credentials: "include" }
      ).then(async (response) => {
        sequenceId++;
        const json = await response.json();
        currentRequestController = undefined;
        return (json.messages ?? []) as AgentApiMessage[];
      });
    },
    sendMessageStream: async (messageText: string) => {
      if (!sessionId) {
        throw new Error("No session is in progress");
      }

      const endpoints = getEndpoints();
      if (!endpoints?.messagesStream) {
        throw new Error("Endpoints not initialized");
      }

      if (enableStopMessage) {
        // Cancel any existing request
        currentRequestController?.abort();
      }

      // Create new controller for this request
      currentRequestController = new AbortController();

      const headers = await createDefaultHeaders();
      return doPost(
        endpoints.messagesStream,
        {
          message: {
            sequenceId,
            type: "Text",
            text: messageText,
          },
          variables: [
            {
              name: "$Context.Timezone",
              type: "Text",
              value: timezone,
            },
            ...getContextVariables(),
          ],
        },
        {
          headers,
          credentials: "include",
          signal: currentRequestController?.signal,
        }
      ).then((response) => {
        sequenceId++;
        currentRequestController = undefined;
        return response.body ?? new ReadableStream();
      });
    },
    stopMessage: async () => {
      if (currentRequestController) {
        try {
          currentRequestController.abort();
          currentRequestController = undefined;
          return Promise.resolve();
        } catch (error: unknown) {
          // Ignore abort errors since they are expected
          if (error instanceof Error && error.name === "AbortError") {
            return Promise.resolve();
          }
          throw error;
        }
      }
      return Promise.resolve();
    },
    endSession: async () => {
      if (!sessionId) {
        throw new Error("No session is in progress");
      }

      if (currentRequestController) {
        // Cancel any existing request
        currentRequestController.abort();
        currentRequestController = undefined;
      }

      const endpoints = getEndpoints();
      if (!endpoints?.endSession) {
        throw new Error("Endpoints not initialized");
      }

      const headers = await createDefaultHeaders();
      headers.append("x-session-end-reason", "UserRequest");
      return await doDelete(endpoints.endSession, undefined, {
        headers,
        credentials: "include",
      }).then(async (response) => {
        const json = await response.json();
        return json;
      });
    },
    joinVoice: async (greeted: boolean = false) => {
      if (!voiceEndpoint) {
        throw new Error("No voice endpoint has been provided");
      }
      if (!sessionId) {
        throw new Error("Cannot join voice without an existing session");
      }
      const headers = await createDefaultHeaders();
      const resolvedVoiceEndpoint = voiceEndpoint.replace(
        /\{SESSION_ID\}/,
        sessionId
      );

      const result = await doPost(
        resolvedVoiceEndpoint,
        { greeted },
        {
          headers,
          credentials: "include",
        }
      ).then(async (response) => {
        if (response.status !== 200) return undefined;
        const json = await response.json();
        return json;
      });

      if (result) {
        // Store livekitConfig in data
        setData({
          ...getData(),
          livekitConfig: result,
        });
      }

      return { livekitConfig: result };
    },
  };
};
