import React, { ReactNode } from "react";
import ReactDOM from "react-dom/client";
import { Chat } from "./components/Chat";
import { ChatProvider } from "./components/ChatProvider";
import { EventDispatcher } from "./components/EventDispatcher";
import "./index.css";
import { ConfigurationProvider } from "./providers/ConfigurationProvider";
import { ReduxProvider, ReduxProviderProps } from "./providers/ReduxProvider";

/**
 * Options for initializing the chat UI.
 *
 * @property enableRPC If true, the client expects a host to be present and will treat missing host as an error.
 *                    If false, the client will gracefully fallback to standalone mode, resolving RPC calls with defaultValue (if provided).
 *                    This is useful for embedding the chat in environments where a host may not be available.
 */
export interface Options extends Omit<ReduxProviderProps, "children"> {
  childrenBefore?: ReactNode;
  childrenAfter?: ReactNode;
  uiConfiguration?: DeepPartialUIConfiguration;
  /**
   * If true, require a host for RPC. If false, allow standalone mode with fallback/defaultValue.
   */
  enableRPC?: boolean;
}

/**
 * Initializes the chat UI in the given container.
 *
 * @param container The DOM element to render into
 * @param options   Configuration options, including enableRPC
 *
 * Example usage:
 *   initReact(document.getElementById('root'), { enableRPC: false });
 */
export const initReact = (container: HTMLElement, options?: Options) => {
  const Component = ({ options }: { options?: Options }) => {
    const {
      childrenBefore,
      childrenAfter,
      uiConfiguration,
      enableRPC,
      ...otherOptions
    } = options ?? {};
    return (
      <React.StrictMode>
        <ReduxProvider {...otherOptions}>
          <ConfigurationProvider uiConfiguration={uiConfiguration}>
            <ChatProvider enableRPC={enableRPC}>
              {childrenBefore}
              <Chat />
              {childrenAfter}
            </ChatProvider>
          </ConfigurationProvider>
          <EventDispatcher />
        </ReduxProvider>
      </React.StrictMode>
    );
  };
  const root = ReactDOM.createRoot(container);
  root.render(<Component options={options} />);

  const rerender = (newOptions: Options) =>
    root.render(<Component options={{ ...options, ...newOptions }} />);

  return rerender;
};

Object.assign(window, { initReact });
