import { Reducer, UnknownAction } from "@reduxjs/toolkit";
import { type Delta, clone, diff, patch } from "jsondiffpatch";
import "setimmediate";
import { type RootState, store } from ".";
import { throttle } from "../utils/throttle";

type CompareState = Pick<RootState, "conversation"> & {
  apphost: Pick<RootState["apphost"], "authToken">;
};

export const SESSION_SYNC_BROADCAST_CHANNEL =
  "agentforce_messaging__session_sync";

const sessionSyncBroadcastChannel = new BroadcastChannel(
  SESSION_SYNC_BROADCAST_CHANNEL
);

const broadcastChanges = (instanceId: string, changes: Delta) => {
  setImmediate(() => {
    try {
      console.debug("Broadcasting changes", changes);
      sessionSyncBroadcastChannel.postMessage({
        changes,
        sourceInstanceId: instanceId,
      });
    } catch (ex) {
      console.error("Error broadcasting changes", ex);
    }
  });
};

export const selectBroadcastableChanges = (state: RootState): CompareState => {
  return {
    apphost: { authToken: state.apphost.authToken },
    conversation: state.conversation,
  };
};

// defers execution of `compareStatesAndBroadcastChanges`
export const deferCompareStatesAndBroadcastChanges = (
  oldState: RootState,
  newState: RootState
) => {
  setImmediate(() => {
    compareStatesAndBroadcastChanges(oldState, newState);
  });
};

export const compareStatesAndBroadcastChanges = (
  oldState: RootState,
  newState: RootState
) => {
  const instanceId = newState.apphost.instanceId;
  if (!instanceId) {
    console.warn("`instanceId` has not been set; unable to broadcast changes");
    return;
  }
  // determine if the new state is different from the old state
  // if it is, we need to broadcast just the changes
  // we will use JSON Patch for this
  const oldCompareState = selectBroadcastableChanges(oldState);
  const newCompareState = selectBroadcastableChanges(newState);
  const changes = diff(oldCompareState, newCompareState);
  if (changes) {
    broadcastChanges(instanceId, changes);
  }
};

const createBroadcastQueue = () => {
  let lastComparedState: RootState | undefined = undefined;
  let instanceId: string | undefined = undefined;

  const setInstanceId = (id: string) => {
    instanceId = id;
  };
  const hasInstanceId = () => !!instanceId;

  const queueChangesForComparison = throttle(
    (oldState: RootState, newState: RootState) => {
      if (!hasInstanceId()) {
        console.error(
          "Instance ID not set; skipping state comparison for broadcast"
        );
        return;
      }
      if (!lastComparedState) {
        lastComparedState = oldState;
      }

      const changes = diff(lastComparedState, newState);
      lastComparedState = newState;
      if (changes) {
        broadcastChanges(instanceId!, changes);
      }
    },
    400
  );

  return { queue: queueChangesForComparison, setInstanceId, hasInstanceId };
};

export const createStateSyncReducer = (
  rootReducer: Reducer<RootState>
): Reducer<RootState> => {
  const broadcastQueue = createBroadcastQueue();

  return (incomingState: RootState | undefined, action: UnknownAction) => {
    let state: RootState | undefined = incomingState;
    if (!state) {
      state = rootReducer(undefined, { type: "@@INIT" });
    }

    const instanceId = state.apphost.instanceId;
    if (state && action.type === "@@session_sync/state_change") {
      console.debug("Received state change action", action);
      // ensure the `sourceInstanceId` does not match our own
      if (action.synced) {
        const changes = action.payload as Delta;
        console.debug("Applying new state");
        const newState = patch(clone(state), changes) as RootState;
        return newState;
      }
      console.warn(
        "State change was not applied",
        instanceId,
        action.sourceInstanceId
      );
      return state;
    }

    if (!broadcastQueue.hasInstanceId()) {
      broadcastQueue.setInstanceId(instanceId!);
    }

    const newState = rootReducer(state, action);
    broadcastQueue.queue(state, newState);
    return newState;
  };
};

sessionSyncBroadcastChannel.onmessage = (event) => {
  if (!event.data.sourceInstanceId) return; // ignore changes that lack a `sourceInstanceId`

  console.debug("Received state change", event.data);
  store.dispatch({
    type: "@@session_sync/state_change",
    payload: event.data.changes,
    synced: true,
  });
};
