import { FocusTrap } from "focus-trap-react";
import { ArrowDown } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import {
  ComponentProps,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import "setimmediate";
import { useConfigurationContext } from "../hooks/useConfigurationContext";
import { useLayoutMode } from "../hooks/useLayoutMode";
import { useAppSelector } from "../store/hooks";
import { selectIsSessionStarting } from "../store/slices";
import { cn } from "../utils";
import {
  CHAT_WINDOW_DIMENSIONS,
  CHAT_WINDOW_PADDING_BOTTOM,
  TEXTAREA_INPUT_MIN_HEIGHT,
} from "../utils/constants";
import { debounce } from "../utils/debounce";
import { ChatHeader } from "./ChatHeader";
import { ChatInput } from "./ChatInput";
import { ChatMessage } from "./ChatMessage";
import { ChatProgressIndicator } from "./ChatProgressIndicator";
import { useChatContext } from "./ChatProvider";
import { ChatSystemMessage } from "./ChatSystemMessage";
import { TextShimmer } from "./ui/TextShimmer";

const ScrollButton = ({
  scrollToBottom,
  unreadMessageCount,
}: {
  scrollToBottom: () => void;
  unreadMessageCount: number;
}) => {
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        scrollToBottom();
      }
    },
    [scrollToBottom]
  );

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 10 }}
      transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
      className="absolute top-[-48px] z-[60] flex items-center justify-center"
    >
      <button
        onClick={scrollToBottom}
        onKeyDown={handleKeyDown}
        onKeyUp={(e) => e.key === "Escape" && e.currentTarget.blur()}
        className="inline-flex items-center justify-center gap-2 rounded-full bg-white p-2 text-center font-sans text-sm text-black shadow-lg drop-shadow-sm transition-opacity hover:bg-gray-100 focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2 focus-visible:outline-none"
        title="Scroll to latest message"
      >
        <ArrowDown className="size-5" aria-hidden="true" />
        {unreadMessageCount > 0 && (
          <span
            className="absolute -top-1.5 -right-1.5 flex h-5 min-w-[20px] items-center justify-center rounded-full bg-red-500 px-1 text-xs text-white"
            role="status"
            aria-label={`${unreadMessageCount} unread messages`}
          >
            {unreadMessageCount}
          </span>
        )}
      </button>
    </motion.div>
  );
};

// Memoize animation properties for better performance
const animationProps = {
  initial: {
    transition: { duration: 0.2, ease: "easeInOut" },
    opacity: 0,
  },
  animate: {
    transition: { duration: 0.25, ease: "easeInOut" },
    opacity: 1,
  },
  exit: {
    transition: { duration: 0.2, ease: "easeInOut" },
    opacity: 0,
  },
};

export const ChatWindow = () => {
  const {
    messages,
    isChatOpen,
    isTabActive,
    isExpanded,
    showProgressIndicator,
    progressIndicatorText,
  } = useChatContext();

  const isSessionStarting = useAppSelector(selectIsSessionStarting);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);
  const shouldAutoScrollRef = useRef(true);
  const prevScrollTopRef = useRef(0);
  const [showScrollButton, setShowScrollButton] = useState(false);
  const [unreadMessageCount, setUnreadMessageCount] = useState(0);
  const [isFocusTrapActive, setIsFocusTrapActive] = useState(true);

  const prevMessagesLengthRef = useRef(messages.length);
  const { chatInput, chatWindow, chatHeader } = useConfigurationContext();
  const { poweredByEnabled } = chatInput;
  const { loadingText, backgroundColor } = chatWindow;

  const {
    mode,
    shouldUseConstrainedFloating,
    shouldUseFullViewport,
    isInIframe,
    isInlineMode,
    isSmallWindow,
  } = useLayoutMode();

  const [textAreaHeight, setTextAreaHeight] = useState(
    TEXTAREA_INPUT_MIN_HEIGHT
  );

  // Immediate scroll-up detection to break auto-scroll
  const handleScrollUpDetection = useCallback(() => {
    if (chatContainerRef.current) {
      const { scrollTop } = chatContainerRef.current;
      if (scrollTop < prevScrollTopRef.current) {
        shouldAutoScrollRef.current = false;
      }
      prevScrollTopRef.current = scrollTop;
    }
  }, []);

  // Memoize scroll handler
  const updateScrollState = useCallback(() => {
    if (chatContainerRef.current) {
      const { scrollTop, scrollHeight, clientHeight } =
        chatContainerRef.current;
      const isNearBottom = scrollHeight - scrollTop - clientHeight < 100;

      // Re-enable auto-scroll if near bottom
      if (isNearBottom) {
        shouldAutoScrollRef.current = true;
      }
      setShowScrollButton(!isNearBottom);

      if (isNearBottom) {
        setUnreadMessageCount(0);
      }
    }
  }, []);

  // Memoize scroll to bottom function
  const scrollToBottom = useCallback(
    ({ animate = true }: { animate?: boolean } = {}) => {
      messagesEndRef.current?.scrollIntoView({
        behavior: animate ? "smooth" : "instant",
      });
      shouldAutoScrollRef.current = true;
      setShowScrollButton(false);
    },
    []
  );

  // Memoize debounced scroll handler using useMemo for efficiency
  const debouncedUpdateScrollState = useMemo(
    () => debounce(updateScrollState, 60),
    [updateScrollState]
  );
  const onScrollEvent = useCallback(() => {
    handleScrollUpDetection();
    debouncedUpdateScrollState();
  }, [handleScrollUpDetection, debouncedUpdateScrollState]);

  useEffect(() => {
    return () => {
      // cancel the debounced scroll handler
      debouncedUpdateScrollState?.cancel?.();
    };
  }, [debouncedUpdateScrollState]);

  // Memoize text area size change handler
  const onTextAreaHeightChange = useCallback(
    (height: number) => {
      setTextAreaHeight(height);

      if (shouldAutoScrollRef.current) {
        setImmediate(() => {
          scrollToBottom({ animate: false });
        });
      }
    },
    [scrollToBottom]
  );

  useEffect(() => {
    if (shouldAutoScrollRef.current) {
      setImmediate(() => {
        scrollToBottom({ animate: false });
      });
    }
  }, [showProgressIndicator, isExpanded, scrollToBottom]);

  // Scroll to bottom effect
  useEffect(() => {
    if (messages.length === 0) return;

    const lastMessage = messages[messages.length - 1];
    const isUserMessage = lastMessage?.direction === "outgoing";

    // Check if this is a new message
    const isNewMessage = messages.length !== prevMessagesLengthRef.current;

    // Always scroll for new user messages, scroll for agent messages if shouldAutoScroll is true
    if (
      (isNewMessage && isUserMessage) ||
      (!isUserMessage && shouldAutoScrollRef.current)
    ) {
      messagesEndRef.current?.scrollIntoView({
        behavior: isUserMessage ? "smooth" : "instant",
      });
    }

    // Increment unread count for new agent messages when user is not at bottom
    if (isNewMessage && !isUserMessage && !shouldAutoScrollRef.current) {
      setUnreadMessageCount((prev) => prev + 1);
    }

    // Update the ref to current length
    prevMessagesLengthRef.current = messages.length;
  }, [messages]);

  useEffect(() => {
    if (isChatOpen) {
      scrollToBottom({ animate: false });
    }
  }, [isChatOpen, scrollToBottom]);

  const renderedMessages = useMemo(() => {
    return messages.map((msg: Message, index: number) => {
      const prevMsg: Message | undefined = messages[index - 1];
      const nextMsg: Message | undefined = messages[index + 1];
      let position: ComponentProps<typeof ChatMessage>["position"] = "single";
      if (prevMsg?.sender === msg.sender && nextMsg?.sender === msg.sender) {
        position = "normal";
      } else if (
        prevMsg?.sender !== msg.sender &&
        nextMsg?.sender === msg.sender &&
        nextMsg?.type !== "system"
      ) {
        position = "first";
      } else if (
        prevMsg?.sender === msg.sender &&
        nextMsg?.sender !== msg.sender
      ) {
        position = "last";
      }

      // Check if the current message is the latest message from the user
      const isLatestMessageFromUser =
        msg.direction === "outgoing" &&
        messages.slice(index + 1).every((m) => m.direction === "incoming");

      // Check if the current message is the latest message from the agent
      const isLatestMessageFromAgent =
        msg.direction === "incoming" &&
        messages.slice(index + 1).every((m) => m.direction === "outgoing");

      return (
        <motion.div
          key={msg.id}
          initial={{ opacity: 0, y: 20, x: 0 }}
          animate={{ opacity: 1, y: 0, x: 0 }}
          transition={{
            duration: 0.4,
            ease: [0.16, 1, 0.3, 1],
            delay: 0.2,
          }}
        >
          {msg.type === "system" ? (
            <ChatSystemMessage
              key={msg.id}
              sentTime={msg.sentTime}
              message={msg.message}
            />
          ) : (
            <ChatMessage
              message={msg.message}
              sentTime={msg.sentTime}
              sender={msg.sender}
              direction={msg.direction}
              position={position}
              isLatestMessageFromUser={isLatestMessageFromUser}
              isLatestMessageFromAgent={isLatestMessageFromAgent}
              type={msg.type}
              onTimeout={msg.onTimeout}
              status={msg.status}
              id={msg.id}
              functionName={msg.functionName}
              isFirstMessage={index === 0}
            />
          )}
        </motion.div>
      );
    });
  }, [messages]);

  // Get floating window dimensions based on expanded state
  const getFloatingDimensions = () => {
    if (isExpanded) {
      return {
        width: CHAT_WINDOW_DIMENSIONS.EXPANDED.WIDTH,
        height: CHAT_WINDOW_DIMENSIONS.EXPANDED.HEIGHT,
      };
    }
    return {
      width: CHAT_WINDOW_DIMENSIONS.NORMAL.WIDTH,
      height: CHAT_WINDOW_DIMENSIONS.NORMAL.HEIGHT,
    };
  };

  const floatingDimensions = getFloatingDimensions();
  const focusTrapEnabled = isInIframe && !isInlineMode;

  const useRoundedCorners = !(
    mode === "inline" ||
    (isSmallWindow && shouldUseFullViewport)
  );

  return (
    <AnimatePresence initial={false}>
      {isChatOpen && (
        <FocusTrap
          active={focusTrapEnabled && isChatOpen && isFocusTrapActive}
          focusTrapOptions={{
            escapeDeactivates: false,
          }}
        >
          <motion.div
            role="region"
            aria-labelledby="agent-name" // reference to the agent name in the chat header
            className={cn(
              "overflow-hidden bg-white font-sans shadow-2xl drop-shadow-sm",
              useRoundedCorners && "rounded-2xl",
              // For constrained floating mode (desktop floating only)
              shouldUseConstrainedFloating && "fixed",
              // For full viewport modes, use different positioning based on mode
              shouldUseFullViewport &&
                mode === "floating" &&
                "fixed right-0 bottom-0 h-[var(--vh,100dvh)] w-[100vw]",
              // For inline mode, use parent-relative sizing to fill the parent container
              mode === "inline" && "relative h-full w-full"
            )}
            {...(isTabActive && {
              initial: animationProps.initial,
              animate: animationProps.animate,
              exit: animationProps.exit,
            })}
            style={{
              // Apply constrained floating dimensions only for desktop floating mode
              ...(shouldUseConstrainedFloating && {
                position: "fixed",
                width: floatingDimensions.width,
                height: floatingDimensions.height,
                right: "20px",
                bottom: "20px",
              }),
            }}
          >
            <div className="flex h-full flex-col overflow-hidden pb-8">
              {chatHeader.visible && (
                <ChatHeader setIsFocusTrapActive={setIsFocusTrapActive} />
              )}

              <div
                ref={chatContainerRef}
                aria-label="Chat messages"
                className={cn(
                  "mb-6 flex-1 px-4",
                  isSessionStarting ? "overflow-hidden" : "overflow-y-auto"
                )}
                onScroll={onScrollEvent}
                style={{ backgroundColor }}
              >
                <div
                  className={cn(
                    "relative flex min-h-full flex-col pt-4",
                    isSessionStarting ? "h-full" : "h-auto",
                    poweredByEnabled
                      ? showProgressIndicator
                        ? "pb-[112px]"
                        : "pb-[56px]"
                      : "pb-[24px]"
                  )}
                  style={{
                    paddingBottom: `${textAreaHeight + CHAT_WINDOW_PADDING_BOTTOM + (showProgressIndicator ? 36 : 0)}px`,
                  }}
                >
                  <AnimatePresence initial={true}>
                    {isSessionStarting && (
                      <div
                        data-testid="loading-overlay"
                        className="absolute inset-0 flex h-full w-full overflow-hidden"
                        style={{ backgroundColor }}
                      >
                        <motion.div
                          role="status"
                          aria-label="Initializing chat"
                          initial={{ opacity: 0, y: 20 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{
                            duration: 4,
                            ease: [0.16, 1, 0.3, 1],
                          }}
                          className="mx-auto flex h-full w-full items-center justify-center"
                        >
                          <div
                            className="flex max-w-[80%] flex-col items-center gap-3"
                            role="status"
                          >
                            <TextShimmer
                              duration={2}
                              className="font-segoe-ui text-center text-3xl leading-10 tracking-[0.2em] text-black"
                              color="#000"
                              aria-label={`Loading chat interface, ${loadingText}`}
                            >
                              {loadingText}
                            </TextShimmer>
                          </div>
                        </motion.div>
                      </div>
                    )}
                  </AnimatePresence>

                  {!isSessionStarting && (
                    <AnimatePresence initial={false}>
                      {renderedMessages}
                    </AnimatePresence>
                  )}

                  <div ref={messagesEndRef} tabIndex={-1} />
                </div>
                {/* <IFrameDebugger /> */}
              </div>

              {/* Progress indicator */}
              <AnimatePresence>
                {showProgressIndicator && (
                  <ChatProgressIndicator
                    message={progressIndicatorText}
                    textAreaHeight={textAreaHeight}
                  />
                )}
              </AnimatePresence>

              <div
                className="absolute right-0 bottom-0 left-0 flex items-center justify-center gap-2"
                style={{ backgroundColor }}
              >
                <AnimatePresence>
                  {showScrollButton && (
                    <ScrollButton
                      scrollToBottom={scrollToBottom}
                      unreadMessageCount={unreadMessageCount}
                    />
                  )}
                </AnimatePresence>
                <ChatInput
                  onTextAreaHeightChange={onTextAreaHeightChange}
                  textAreaHeight={textAreaHeight}
                />
              </div>
            </div>
          </motion.div>
        </FocusTrap>
      )}
    </AnimatePresence>
  );
};
