import { useEffect, useMemo, useState } from "react";
import { useAppSelector } from "../store/hooks";
import { layout } from "../store/slices/ui";
import { debounce } from "../utils/debounce";

/**
 * Centralizes layout mode determination logic.
 */
export const useLayoutMode = () => {
  const [isSmallWindow, setIsSmallWindow] = useState(false);
  const [isInIframe, setIsInIframe] = useState(true);

  const mode = useAppSelector(layout.selectMode);

  // Set up window size detection
  useEffect(() => {
    const mediaQuery = window.matchMedia("(max-width: 640px)");
    setIsSmallWindow(mediaQuery.matches);

    const handleResize = () => {
      setIsSmallWindow(mediaQuery.matches);
    };

    // Debounce the resize handler
    const debouncedHandleResize = debounce(handleResize, 100);

    mediaQuery.addEventListener("change", debouncedHandleResize);
    return () => {
      mediaQuery.removeEventListener("change", debouncedHandleResize);
      debouncedHandleResize.cancel?.();
    };
  }, []);

  // Set up iframe detection
  useEffect(() => {
    setIsInIframe(window.parent !== window);
  }, []);

  // Compute derived layout states
  const layoutConfig = useMemo(() => {
    const isInlineMode = mode === "inline";
    const isFloatingMode = mode === "floating";
    const isFloatingDesktop = isFloatingMode && !isInIframe && !isSmallWindow;
    const shouldUseConstrainedFloating = isFloatingDesktop;
    const shouldUseFullViewport = isFloatingMode && !isFloatingDesktop;

    return {
      mode,
      isInlineMode,
      isFloatingMode,
      isFloatingDesktop,
      shouldUseConstrainedFloating,
      shouldUseFullViewport,
      isInIframe,
      isSmallWindow,
    };
  }, [mode, isInIframe, isSmallWindow]);

  return layoutConfig;
};
