let _api: AgentApi | undefined;
let _configuration: AgentApiConfiguration | undefined;

export const getAgentApi = () => _api;
export const setAgentApi = (api?: AgentApi) => {
  _api = api;
};
export const isAgentApiAvailable = () => !!_api;

export const getAgentApiConfiguration = () => _configuration;
export const setAgentApiConfiguration = (
  configuration?: AgentApiConfiguration
) => {
  // TODO: revert this after Friday 4/11 demo
  let newConfiguration = configuration;
  const ngcStorage = localStorage.getItem("_ngc");
  if (ngcStorage) {
    const ngcStorageObject = JSON.parse(ngcStorage);
    newConfiguration = {
      ...newConfiguration,
      endpoint: ngcStorageObject.endpoint,
    } as any;
  }
  _configuration = newConfiguration;
};
export const isAgentApiConfigurationAvailable = () => !!_configuration;
