import {
  LocalParticipant,
  Participant,
  RemoteParticipant,
  Room,
  RoomEvent,
  TrackPublication,
  type TranscriptionSegment,
} from "livekit-client";
import { useCallback, useEffect, useRef, useState } from "react";
import { LiveKitConfig, livekitService } from "../services/livekit";
import { useAppDispatch, useAppSelector, useAppState } from "../store/hooks";
import {
  selectConversationId,
  selectIsMuted,
  setIsMuted as setIsMutedAction,
  setPlanId,
  setVoiceModeError,
  upsertConversationEntryStreamingMessage,
} from "../store/slices";
import { useAgentSpeakingDeltas } from "./useAgentSpeakingDeltas";
import { stopAllMicrophoneStreams } from "./useAudioContext";

export interface UseLiveKitReturn {
  room: Room | undefined;
  localParticipant: LocalParticipant | undefined;
  remoteParticipants: RemoteParticipant[];
  isConnected: boolean;
  isConnecting: boolean;
  connect: (config: LiveKitConfig) => Promise<void>;
  disconnect: () => void;
  transcriptionSegments: { [id: string]: Transcription };
}

export interface Transcription {
  segment: TranscriptionSegment;
  participant?: Participant;
  publication?: TrackPublication;
}

export function useLiveKit(): UseLiveKitReturn {
  const [room, setRoom] = useState<Room | undefined>(undefined);
  const [localParticipant, setLocalParticipant] = useState<
    LocalParticipant | undefined
  >(undefined);
  const [rawRemoteParticipants, setRawRemoteParticipants] = useState<string>();
  const [remoteParticipants, setRemoteParticipants] = useState<
    RemoteParticipant[]
  >([]);
  const [isConnecting, setIsConnecting] = useState(false);
  const [isConnected, setIsConnected] = useState(false);
  const [isMuted] = useAppState(selectIsMuted, setIsMutedAction);

  useAgentSpeakingDeltas(room);

  // HACK to ensure the participants stay up-to-date
  // the remote participants weren't showing as joined
  const doUpdate = useCallback(() => {
    if (!room) return;

    setLocalParticipant(room.localParticipant);
    setRawRemoteParticipants([...room.remoteParticipants.keys()].join(","));
  }, [room]);
  useEffect(() => {
    setRemoteParticipants(Array.from(room?.remoteParticipants.values() ?? []));
  }, [room, rawRemoteParticipants]);

  const doConnect = useCallback(
    async (config: LiveKitConfig) => {
      try {
        setIsConnecting(true);
        const connectedRoom = await livekitService.connect(config);
        if (!connectedRoom) {
          throw new Error("Did not connect");
        }
        setRoom(connectedRoom);
        setIsConnected(true);
        // set the microphone enabled state based on the isMuted state
        await connectedRoom.localParticipant.setMicrophoneEnabled(!isMuted);
      } catch (error) {
        console.error("Failed to connect to LiveKit room:", error);
        setVoiceModeError("Failed to connect to voice mode");
        throw error;
      } finally {
        setIsConnecting(false);
      }
    },
    [isMuted]
  );

  const connect = useCallback(
    async (config: LiveKitConfig) => {
      if (isConnecting || isConnected) return;
      return doConnect(config);
    },
    [isConnecting, isConnected, doConnect]
  );

  const doDisconnect = useCallback(() => {
    stopAllMicrophoneStreams();
    livekitService.disconnect();
    setRoom(undefined);
    setLocalParticipant(undefined);
    setRemoteParticipants([]);
    setIsConnected(false);
  }, []);

  const disconnect = useCallback(() => {
    if (!isConnected || isConnecting) return;
    return doDisconnect();
  }, [isConnecting, isConnected, doDisconnect]);

  // Update state when room changes
  const currentRoom = livekitService.getRoom();
  useEffect(() => {
    if (!currentRoom) return;
    setRoom(currentRoom);
    setLocalParticipant(currentRoom.localParticipant);
    setRemoteParticipants(Array.from(currentRoom.remoteParticipants.values()));
    setIsConnected(true);

    const interval = setInterval(doUpdate, 500);

    return () => {
      clearInterval(interval);
    };
  }, [currentRoom, doUpdate]);

  // Add a ref to track the latest segments for cleanup
  const transcriptionSegmentsRef = useRef<{ [id: string]: Transcription }>({});
  const [transcriptionSegments, setTranscriptionSegments] = useState<{
    [id: string]: Transcription;
  }>({});

  const dispatch = useAppDispatch();
  // Add conversationId from Redux
  const conversationId = useAppSelector(selectConversationId);
  // Listen for transcription segments
  useEffect(() => {
    if (!room) return;

    // Track processed segment IDs and their last seen text to avoid duplicates
    const processedSegments = new Map<string, string>();
    // Keep track of the most recent segment ID for each participant
    const participantSegments = new Map<string, Set<string>>();
    // Max number of segments to keep in state to prevent memory issues
    const MAX_SEGMENTS_TO_KEEP = 20;

    const handleTranscriptionReceived = (
      segments: TranscriptionSegment[],
      participant?: Participant,
      publication?: TrackPublication
    ) => {
      segments.forEach((segment) => {
        if (!segment.text || segment.text.trim() === "") return;

        // Get participant identity for tracking
        const participantId = participant?.identity || "unknown";

        // Get or create set of segments for this participant
        let participantSet = participantSegments.get(participantId);
        if (!participantSet) {
          participantSet = new Set<string>();
          participantSegments.set(participantId, participantSet);
        }

        // Add current segment to participant's set
        participantSet.add(segment.id);

        // Skip if this is a duplicate with the same content
        const previousText = processedSegments.get(segment.id);
        if (previousText === segment.text) {
          return;
        }

        // Store the current text for future comparison
        processedSegments.set(segment.id, segment.text);

        // Log only once per segment, and only if it's a final segment or significant change
        if (
          segment.final ||
          !previousText ||
          Math.abs(segment.text.length - (previousText?.length || 0)) > 10
        ) {
          console.debug(
            `Processing ${segment.final ? "final" : "interim"} transcription (${participantId}):`,
            segment.text
          );
        }

        // Process segment immediately - no debounce
        setTranscriptionSegments((prev) => {
          // Only keep the most recent segments to prevent memory issues
          const allSegments = { ...prev };
          const newSegment = {
            segment,
            participant,
            publication,
          };

          // Update the ref with the latest data
          transcriptionSegmentsRef.current = {
            ...transcriptionSegmentsRef.current,
            [segment.id]: newSegment,
          };

          // If we have too many segments, only keep the most recent ones
          const segmentIds = Object.keys(allSegments);
          if (segmentIds.length > MAX_SEGMENTS_TO_KEEP) {
            // Sort segments by ID as a fallback (newest likely have higher IDs)
            const sortedIds = segmentIds.sort((a, b) => {
              // Use segment IDs for comparison (assuming newer segments have higher IDs)
              return b.localeCompare(a);
            });

            // Create a new object with only the most recent segments
            const updated: { [id: string]: Transcription } = {};
            sortedIds.slice(0, MAX_SEGMENTS_TO_KEEP).forEach((id) => {
              updated[id] = allSegments[id];
            });

            // Add the current segment
            updated[segment.id] = newSegment;
            return updated;
          }

          // Just add the current segment if we don't need to clean up yet
          allSegments[segment.id] = newSegment;
          return allSegments;
        });

        // Only add to conversation if we have a valid conversation ID
        if (conversationId) {
          // Determine if this is from the user or assistant based on participant
          const isLocalParticipant =
            participant?.identity === room.localParticipant.identity;

          // Use consistent message ID for this participant to consolidate updates
          // This helps avoid message fragmentation in the UI
          const speakerType = isLocalParticipant ? "user" : "assistant";
          const messageId = segment.id;
          const now = new Date().toISOString();

          dispatch(
            upsertConversationEntryStreamingMessage({
              id: messageId,
              message: segment.text,
              sentTime: now,
              sender: speakerType,
              direction: isLocalParticipant ? "outgoing" : "incoming",
              position: "single",
              offset: 0,
              replace: true, // Replace the entire message instead of appending
            })
          );
        }
      });
    };

    room.on(RoomEvent.TranscriptionReceived, handleTranscriptionReceived);

    return () => {
      room.off(RoomEvent.TranscriptionReceived, handleTranscriptionReceived);
    };
  }, [room, conversationId, dispatch]);

  // Listen for data message
  useEffect(() => {
    if (!room) return;

    const handleDataReceived = (
      payload: Uint8Array,
      participant?: RemoteParticipant,
      kind?: number,
      topic?: string
    ) => {
      const decoder = new TextDecoder();
      try {
        const dataString = decoder.decode(payload);
        const data = JSON.parse(dataString);

        console.debug("Data message received:", {
          data,
          participant,
          topic,
          kind,
        });

        switch (data.type) {
          case "PlanMessage":
            dispatch(setPlanId({ planId: data.planId }));
            break;
          default:
            console.debug("Unknown data message type: ", data.type, {
              data,
              participant,
              topic,
              kind,
            });
            break;
        }
      } catch (error) {
        const rawData = decoder.decode(payload);
        console.error("Raw data received:", rawData);
        console.error("Error processing data message:", error);
      }
    };

    room.on(RoomEvent.DataReceived, handleDataReceived);

    return () => {
      room.off(RoomEvent.DataReceived, handleDataReceived);
    };
  }, [room, dispatch]);

  return {
    connect,
    disconnect,
    isConnected,
    isConnecting,
    room,
    localParticipant,
    remoteParticipants,
    transcriptionSegments,
  };
}
