import { getAgentApiConfiguration } from "../../connectors";

export const agentConfigurationAdapterFactory: AdapterFactory<
  AgentConfigurationAdapter
> = (getAdapters) => {
  //   const getApi = () => {
  //     const api = getAgentApi();
  //     if (!api) {
  //       throw new Error("Agent API is not available");
  //     }
  //     return api;
  //   };

  const getConversationId = () => {
    const sessionId = (getAdapters().conversation as AgentConversationAdapter)
      .sessionId;
    if (!sessionId) {
      throw new Error("No session is currently active");
    }
    return sessionId;
  };

  const getAgentConfiguration = async () => {
    const configuration = getAgentApiConfiguration();
    if (!configuration) {
      throw new Error("Agent API configuration has not been provided");
    }
    return configuration;
  };

  return {
    adapterType: "configuration",
    getAgentConfiguration,
    getConversationId,
  };
};
