import storage from "@piotr-cz/redux-persist-idb-storage";
import { Reducer, UnknownAction } from "@reduxjs/toolkit";
import {
  FLUSH,
  PAUSE,
  PERSIST,
  persistReducer,
  PURGE,
  REGISTER,
  REHYDRATE,
} from "redux-persist";
import createTransform from "redux-persist/es/createTransform";
import type { PersistConfig } from "redux-persist/es/types";
import { RootState } from "./slices";

export const filterStateToIncludeOnlyCurrentConversation = (
  state: RootState["conversation"],
  resetLoadingToFalse = false
) => {
  // only save/restore the current conversation
  const { currentConversationId } = state;
  const currentConversation:
    | RootState["conversation"]["conversations"][string]
    | undefined = currentConversationId
    ? state.conversations[currentConversationId]
    : undefined;
  // determine if we can/should handle this conversation
  // anything stale for more than 30 minutes will be discarded
  let canSaveOrRestoreConversation = !!currentConversation;
  let canSaveOrRestoreVoiceMode = canSaveOrRestoreConversation;
  if (currentConversation?.ids && currentConversation?.entities) {
    const lastMessageId =
      currentConversation.ids[currentConversation.ids.length - 1];
    const lastMessage = currentConversation.entities[lastMessageId];
    const lastSentTimeStr = lastMessage?.sentTime;
    if (lastSentTimeStr) {
      const lastSentTime = Date.parse(lastSentTimeStr);
      const TEN_MINUTES = 10 * 60 * 1000;
      const THIRTY_MINUTES = 30 * 60 * 1000;
      if (lastSentTime + THIRTY_MINUTES < Date.now()) {
        canSaveOrRestoreConversation = false;
      }
      if (lastSentTime + TEN_MINUTES < Date.now()) {
        canSaveOrRestoreVoiceMode = false;
      }
    } else {
      canSaveOrRestoreConversation = false;
      canSaveOrRestoreVoiceMode = false;
    }
  }
  return {
    ...state,
    ...(resetLoadingToFalse && {
      loading: false,
      isVoiceModeLoading: false,
    }),
    ...(canSaveOrRestoreConversation &&
      currentConversation && {
        currentConversationId,
        conversations: canSaveOrRestoreConversation
          ? {
              [currentConversationId!]: {
                ...currentConversation,
                ...(resetLoadingToFalse && {
                  loading: false,
                  chatState: {
                    ...currentConversation.chatState,
                    voiceModeError: undefined,
                  },
                }),
                ...(!canSaveOrRestoreVoiceMode && {
                  chatState: {
                    ...currentConversation.chatState,
                    activeVoiceInstanceId: undefined,
                    isVoiceMode: false,
                    isMuted: false,
                    voiceModeError: undefined,
                  },
                }),
              },
            }
          : {},
      }),
    ...(!canSaveOrRestoreConversation && {
      currentConversationId: "",
      conversations: {},
    }),
    // if we don't have a current conversation, ensure the chat isn't open
    // otherwise, it'll be stuck in a bad state
    ...((!currentConversation || !canSaveOrRestoreConversation) &&
      state.isChatOpen && {
        isChatOpen: false,
      }),
  };
};

