// Configure persistence
type PersistConfigWithDeserialize = PersistConfig<RootState> & {
  deserialize?: boolean; // missing from type declaration
};
export const persistConfig: PersistConfigWithDeserialize = {
  key: "root",
  version: 1,
  storage: storage({
    name: "agentforce-messaging",
    storeName: "root",
    version: 1,
  }),
  deserialize: false,
  serialize: false,
  whitelist: ["conversation"], // TODO whitelist
  transforms: [
    createTransform(
      (stateToBePersisted, key) => {
        if (key !== "conversation" || !stateToBePersisted)
          return stateToBePersisted;
        // only save the current conversation
        const state = stateToBePersisted as RootState["conversation"];
        return filterStateToIncludeOnlyCurrentConversation(state);
      },
      (stateToBeRehydrated: RootState["conversation"], key) => {
        if (key !== "conversation") return stateToBeRehydrated;
        const state = stateToBeRehydrated as RootState["conversation"];
        // we can't be in a `loading` state after a refresh
        return filterStateToIncludeOnlyCurrentConversation(state, true);
      },
      { whitelist: ["conversation"] }
    ),
  ],
};

// Since we can't use `persistReducer` more than once at the root (eg: with multiple configs),
// we will just create another reducer to handle persisting/restoring the `instanceId`
// TODO switch this to use the nested persists?

const tryGetJson = <T extends object>(
  json: string | null | undefined
): T | undefined => {
  if (!json) return undefined;

  try {
    return JSON.parse(json) as T;
  } catch (_ex) {
    /* Do nothing */
  }
  return undefined;
};

export const PERSIST_INSTANCE_ID_KEY = "agentforce-messaging::instance-id";
export const PERSIST_AUTH_TOKEN = "agentforce-messaging::auth-token";
export const createTabPersistenceReducer = (
  reducer: Reducer<RootState>
): Reducer<RootState> => {
  let lastInstanceId: string = "";
  let lastAuthToken: AuthToken | null = null;

  return (incomingState: RootState | undefined, action: UnknownAction) => {
    const persistedInstanceId = sessionStorage.getItem(PERSIST_INSTANCE_ID_KEY);
    const persistedAuthToken = tryGetJson<AuthToken>(
      sessionStorage.getItem(PERSIST_AUTH_TOKEN)
    );
    let state: RootState | undefined = incomingState;
    if (!state) {
      state = reducer(undefined, { type: "@@INIT" });
      state = {
        ...state,
        apphost: {
          ...state.apphost,
          ...(persistedInstanceId && {
            instanceId: persistedInstanceId,
          }),
          ...(persistedAuthToken && {
            authToken: persistedAuthToken,
          }),
        },
      };
    }
    lastInstanceId = state.apphost.instanceId;
    lastAuthToken = state.apphost.authToken;

    if (
      lastInstanceId &&
      (!persistedInstanceId || persistedInstanceId !== lastInstanceId)
    ) {
      sessionStorage.setItem(PERSIST_INSTANCE_ID_KEY, lastInstanceId);
    }
    if (lastAuthToken !== persistedAuthToken) {
      if (!lastAuthToken) {
        sessionStorage.removeItem(PERSIST_AUTH_TOKEN);
      } else {
        sessionStorage.setItem(
          PERSIST_AUTH_TOKEN,
          JSON.stringify(lastAuthToken)
        );
      }
    }
    return reducer(state, action);
  };
};

export const createPersistedReducer = (rootReducer: Reducer<RootState>) => {
  const persistedTabReducer = createTabPersistenceReducer(rootReducer);

  // Create persisted reducer from root reducer
  const persistedSessionReducer = persistReducer(
    persistConfig,
    persistedTabReducer
  );

  return persistedSessionReducer;
};

export const IGNORED_PERSIST_ACTIONS = [
  FLUSH,
  REHYDRATE,
  PAUSE,
  PERSIST,
  PURGE,
  REGISTER,
];

/**
 * Deletes the IndexedDB entry for persistence and refreshes the page
 */
export const resetPersistence = () => {
  try {
    indexedDB.deleteDatabase("agentforce-messaging");
    try {
      window.parent.location.reload();
    } catch (_ex) {
      console.warn(
        "Unable to reload parent page. Please refresh the page manually."
      );
    }
  } catch (ex) {
    console.error(
      "Failed to delete the `agentforce-messaging` database from `indexedDB`. To do this manually, open Developer Tools, go to Applications > IndexedDB, select the 'agentforce-messaging' entry, and click 'Delete Database' to remove it. Then refresh the page.",
      ex
    );
  }
};
Object.assign(window, { resetPersistence });
