import { useVoice } from "../providers/VoiceProvider";
import { VoiceInputVisualizer } from "./FrequencyVisualizer";
import { LoadingDots } from "./LoadingDots";
import { StaticDots } from "./StaticDots";

interface MicrophoneVisualizationProps {
  color?: string;
}

export const MicrophoneVisualization = ({
  color = "#ffffff",
}: MicrophoneVisualizationProps) => {
  const { isMuted, isConnected, isConnectingToAgent } = useVoice();

  if (!isConnected || isConnectingToAgent) {
    return <LoadingDots color={color} />;
  } else if (isMuted) {
    return <StaticDots color={color} />;
  }
  return <VoiceInputVisualizer color={color} />;
};
