// Add interface for choices
interface ChoiceOption {
  itemType: string;
  titleItem: {
    itemType: string;
    title: string;
  };
  optionIdentifier: string;
}

interface ChatMessageProps {
  message: string;
  sentTime: string;
  sender: "user" | "assistant";
  direction: "outgoing" | "incoming";
  position: "single" | "first" | "normal" | "last";
  isVoiceMode?: boolean;
  isLatestMessageFromUser?: boolean;
  isLatestMessageFromAgent?: boolean;
  type?: Message["type"];
  onTimeout?: () => void;
  status?: "pending" | "completed" | "failed";
  id: string;
  functionName?: string;
  isFirstMessage?: boolean;
}

// Memoize complex class string calculations
const getMessageClasses = (
  isUser: boolean,
  isVoiceMode: boolean,
  position: string
) => {
  const baseClasses = "flex flex-col w-fit leading-normal py-3 px-4";

  const colorClasses = isUser ? "bg-black text-white ml-auto" : "bg-gray-100";

  const roundedClasses =
    position === "last" || position === "single"
      ? isUser
        ? "rounded-2xl rounded-br-none"
        : "rounded-2xl rounded-bl-none"
      : "rounded-2xl";

  const widthClasses = isVoiceMode ? "max-w-full" : isUser ? "max-w-full" : "";

  return cn(
    baseClasses,
    colorClasses,
    roundedClasses,
    widthClasses,
    // Optional enhancements
    isVoiceMode && "shadow-xl"
  );
};

// Extract YouTube-related logic into a separate component
function YouTubeEmbed({ videoId, title }: { videoId: string; title: string }) {
  return (
    <div key={videoId} className="relative my-4 w-full pt-[56.25%]">
      <iframe
        className="absolute top-0 left-0 h-full w-full rounded-lg"
        src={`https://www.youtube.com/embed/${videoId}`}
        title={title || "YouTube video player"}
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
      />
    </div>
  );
}

// Extract message parsing logic into a custom hook
function useMessageSegments(message: string) {
  return useMemo(() => {
    const YOUTUBE_LINK_REGEX =
      /(\[.*?\]\((?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/watch\?v=|youtu\.be\/)[^\s)]+\))/;
    const YOUTUBE_ID_REGEX = /(?:youtube\.com\/watch\?v=|youtu\.be\/)([^&\s]+)/;

    const parts = message.split(YOUTUBE_LINK_REGEX);

    return parts.map((part) => {
      const youtubeMatch = part.match(
        /\[(.*?)\]\(((?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/watch\?v=|youtu\.be\/)[^\s)]+)\)/
      );

      if (!youtubeMatch) return part;

      const [title, url] = youtubeMatch.slice(1);
      const videoId = YOUTUBE_ID_REGEX.exec(url)?.[1];

      return videoId ? (
        <YouTubeEmbed key={videoId} videoId={videoId} title={title} />
      ) : (
        part
      );
    });
  }, [message]);
}

// Extract metadata component
function MessageMetadata({
  isUser,
  sentTime,
}: {
  isUser: boolean;
  sentTime: string;
}) {
  const { chatMessage, chatHeader } = useConfigurationContext();
  const { textColor } = chatMessage.metadata;
  const { agentName } = chatHeader;

  return isUser ? (
    <span className="mt-2 text-right text-xs" style={{ color: textColor }}>
      Read · {sentTime}
    </span>
  ) : (
    <span className="mt-2 text-xs" style={{ color: textColor }}>
      {agentName} · {sentTime}
    </span>
  );
}

function TextMessage({
  message,
  isUser,
  showMetadata,
  sentTime,
  position,
  isVoiceMode = false,
  isChoices = false,
}: {
  message: string;
  isUser: boolean;
  showMetadata: boolean;
  sentTime: string;
  position: "single" | "first" | "normal" | "last";
  isVoiceMode?: boolean;
  isChoices?: boolean;
}) {
  const segments = useMessageSegments(message);

  const messageClasses = useMemo(
    () => getMessageClasses(isUser, isVoiceMode, position),
    [isUser, isVoiceMode, position]
  );

  const markdownClasses = useMemo(
    () =>
      cn(
        "prose [overflow-wrap:anywhere]",
        isUser
          ? "prose-white [&>p>code]:bg-blue-600 whitespace-pre-wrap"
          : "[&>p>code]:bg-gray-200",
        "[&>*:last-child]:mb-0 [&>*]:mb-3",
        "[&>h3]:mt-4 [&>h3]:text-lg [&>h3]:font-semibold",
        "[&>ol]:ml-4 [&>ol]:list-decimal",
        "[&>p>code]:rounded-sm [&>p>code]:px-1",
        "[&>p>strong]:font-semibold",
        "[&>ul>li]:marker:text-current [&>ul]:ml-4 [&>ul]:list-disc",
        "[&>*]:[overflow-wrap:anywhere]"
      ),
    [isUser]
  );

  // Create custom components with isUser information
  const customComponents = useMemo(() => {
    return {
      ...defaultMarkdownComponents,
      a: ({ ...props }) => {
        return (
          <a
            {...props}
            href={props.href}
            rel="noopener noreferrer"
            className={`underline ${isUser ? "text-blue-300" : "text-blue-600"}`}
          />
        );
      },
    };
  }, [isUser]);

  const { chatMessage } = useConfigurationContext();
  const { backgroundColor, textColor } = isUser
    ? chatMessage.user
    : chatMessage.agent;
  const avatarEnabled = !isUser && chatMessage.agent.avatarEnabled;

  return (
    <div className={`flex flex-row items-end ${!isUser ? "gap-2" : ""}`}>
      {!isUser && showMetadata && avatarEnabled && (
        <div className="mb-6 flex shrink-0 flex-col">
          <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full">
            <ChatAgentIcon className="text-gray-500" />
          </div>
        </div>
      )}
      {!isUser && !avatarEnabled && <div className="w-0" />}
      {/* Spacings for agent messages w avatar that are not last in group */}
      {!isUser && !showMetadata && avatarEnabled && !isChoices && (
        <div className="w-6" data-testid="agent-avatar-spacing" />
      )}
      <div className="flex min-w-0 flex-1 flex-col">
        <motion.div
          className={messageClasses}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.3 }}
          aria-label={`${isUser ? "Your" : "Agent's"} message`}
          style={{
            backgroundColor,
            color: textColor,
          }}
        >
          {segments.map((segment, index) =>
            React.isValidElement(segment) ? (
              segment
            ) : isUser ? (
              <div key={index} className={markdownClasses}>
                <p className="flex">{segment}</p>
              </div>
            ) : (
              <div key={index} className={markdownClasses}>
                <Markdown components={customComponents}>
                  {segment as string}
                </Markdown>
              </div>
            )
          )}
        </motion.div>
        {showMetadata && (
          <MessageMetadata isUser={isUser} sentTime={sentTime} />
        )}
      </div>
    </div>
  );
}

// Add new TableMessage component
function TableMessage({
  message,
  isUser,
  showMetadata,
  sentTime,
  // position,
}: {
  message: string;
  isUser: boolean;
  showMetadata: boolean;
  sentTime: string;
  // position: "single" | "first" | "normal" | "last";
}) {
  const { toggleExpanded } = useChatContext();
  const { chatMessage } = useConfigurationContext();
  const avatarEnabled = !isUser && chatMessage.agent.avatarEnabled;

  const isTableFormatComplete = useMemo(() => {
    const lines = message.split("\n");
    if (lines.length < 3) return false;
    const hasSeparator = lines.some(
      (line) => line.includes("|") && line.includes("-")
    );
    return hasSeparator;
  }, [message]);

  useEffect(() => {
    if (isTableFormatComplete) {
      toggleExpanded(true);
    }
  }, [isTableFormatComplete, toggleExpanded]);

  const markdownClasses = useMemo(
    () =>
      cn(
        "prose prose-sm max-w-none",
        isUser ? "prose-invert" : "prose-gray",
        "[&>*:last-child]:mb-0 [&>*]:mb-3"
      ),
    [isUser]
  );

  return (
    <div
      className="flex flex-row items-end gap-2"
      aria-label={`Agent's message with table`}
    >
      <div className="mb-6 flex shrink-0 flex-col">
        {!isUser && showMetadata && avatarEnabled && (
          <div
            className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full"
            aria-hidden="true"
          >
            <ChatAgentIcon className="text-gray-500" />
          </div>
        )}
      </div>
      <div className="flex min-w-0 flex-1 flex-col">
        <article className="max-w-full">
          {!isTableFormatComplete ? (
            <div
              className="mx-auto flex items-center gap-2 text-gray-500"
              role="status"
              aria-label="Loading table content"
            >
              <Loader2 className="size-6 animate-spin" aria-hidden="true" />
            </div>
          ) : (
            <div className={markdownClasses}>
              <Markdown>{message}</Markdown>
            </div>
          )}
        </article>
        {showMetadata && (
          <MessageMetadata isUser={isUser} sentTime={sentTime} />
        )}
      </div>
    </div>
  );
}

/**
 * SurfaceAction component for handling different types of interactive UI elements
 * that can be displayed in the chat interface. This includes:
 * - Rich links: Display link previews with title, URL, and optional image
 * - Choices: Present a set of clickable options for the user to select from
 */
function SurfaceActionMessage({
  message,
  isUser,
  showMetadata,
  sentTime,
  position,
  isVoiceMode = false,
}: {
  message: string;
  isUser: boolean;
  showMetadata: boolean;
  sentTime: string;
  position: "single" | "first" | "normal" | "last";
  isVoiceMode?: boolean;
}) {
  const data = useMemo(() => {
    try {
      return JSON.parse(message);
    } catch (e) {
      console.error(
        "Error parsing surface action:",
        e,
        "Message:",
        message.substring(0, 100)
      );
      return undefined;
    }
  }, [message]);

  if (
    data === undefined ||
    !data.result ||
    !Array.isArray(data.result) ||
    data.result.length === 0
  ) {
    console.error("Invalid surface action format or parse error:", data);
    return undefined;
  }

  // We're currently assuming there's only one result in the array,
  // but this may change in the future to support multiple surface actions
  // in a single message.
  const resultItem = data.result[0];
  const messageText = data.message || "";

  const messageComponent = data.message ? (
    <TextMessage
      message={messageText}
      isUser={isUser}
      showMetadata={false}
      sentTime={sentTime}
      position={position}
      isVoiceMode={isVoiceMode}
      isChoices={resultItem.type === SURFACE_ACTION_TYPES.CHOICES}
    />
  ) : undefined;

  switch (resultItem.type) {
    case SURFACE_ACTION_TYPES.RICH_LINK: {
      return (
        <RichLinkSurfaceAction
          resultItem={resultItem}
          isUser={isUser}
          showMetadata={showMetadata}
          sentTime={sentTime}
          messageComponent={messageComponent}
        />
      );
    }

    case SURFACE_ACTION_TYPES.CHOICES: {
      return (
        <ChoicesMenuSurfaceAction
          resultItem={resultItem}
          isUser={isUser}
          showMetadata={showMetadata}
          sentTime={sentTime}
          position={position}
          isVoiceMode={isVoiceMode}
          messageComponent={messageComponent}
        />
      );
    }

    default: {
      console.error(`Unhandled surface action type: ${resultItem.type}`);
      if (messageComponent) {
        return (
          <div className="flex flex-col">
            {messageComponent}
            {showMetadata && (
              <MessageMetadata isUser={isUser} sentTime={sentTime} />
            )}
          </div>
        );
      }
      return undefined;
    }
  }
}

function RichLinkSurfaceAction({
  resultItem,
  isUser,
  showMetadata,
  sentTime,
  messageComponent,
}: {
  resultItem: { type: string; value?: string };
  isUser: boolean;
  showMetadata: boolean;
  sentTime: string;
  isVoiceMode?: boolean;
  messageComponent: React.ReactNode | undefined;
}) {
  const parsedContent = useMemo(() => {
    try {
      return resultItem.value ? parseRichLinkData(resultItem.value) : undefined;
    } catch (e) {
      console.error("Error parsing rich link data:", e, resultItem.value);
      return undefined;
    }
  }, [resultItem.value]);

  const { chatMessage } = useConfigurationContext();
  const avatarEnabled = !isUser && chatMessage.agent.avatarEnabled;

  if (!parsedContent) {
    console.error("RichLinkSurfaceAction: parsedContent is undefined.");
    return undefined;
  }

  return (
    <div
      className={`flex flex-row items-end ${!isUser && showMetadata ? "gap-2" : ""}`}
    >
      <div className="mb-6 flex shrink-0 flex-col">
        {!isUser && showMetadata && avatarEnabled && (
          <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full">
            <ChatAgentIcon className="text-gray-500" />
          </div>
        )}
      </div>
      <div className="flex min-w-0 flex-1 flex-col">
        {messageComponent}
        <div className="mt-2 max-w-[60%] min-w-[40%]">
          <a
            href={parsedContent.linkUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex flex-col overflow-hidden rounded-lg border border-gray-200 bg-white hover:bg-gray-50 active:bg-gray-100"
          >
            {parsedContent.imageUrl && (
              <div className="w-full overflow-hidden">
                <img
                  src={parsedContent.imageUrl}
                  alt={parsedContent.title}
                  className="h-auto w-full object-contain"
                />
              </div>
            )}
            <div className="flex flex-col p-4">
              <h3 className="mb-1 font-semibold">
                {parsedContent.title || "Visit link"}
              </h3>
              <div className="truncate text-xs text-gray-500">
                {parsedContent.linkUrl}
              </div>
            </div>
          </a>
        </div>
        {showMetadata && (
          <MessageMetadata isUser={isUser} sentTime={sentTime} />
        )}
      </div>
    </div>
  );
}

function ChoicesMenuSurfaceAction({
  resultItem,
  isUser,
  showMetadata,
  sentTime,
  position,
  isVoiceMode,
  messageComponent,
}: {
  resultItem: { type: string; value?: string };
  isUser: boolean;
  showMetadata: boolean;
  sentTime: string;
  position: "single" | "first" | "normal" | "last";
  isVoiceMode?: boolean;
  messageComponent: React.ReactNode | undefined;
}) {
  const { chatMessage } = useConfigurationContext();
  const avatarEnabled = !isUser && chatMessage.agent.avatarEnabled;
  const showChoicesMetadata = showMetadata && !messageComponent;

  const parsedChoicesMessageData = useMemo(() => {
    return resultItem.value
      ? (parseChoicesMessageData(resultItem.value) as {
          text: string;
          optionItems: ChoiceOption[];
        })
      : { text: "", optionItems: [] };
  }, [resultItem.value]);

  return (
    <>
      {messageComponent && (
        <div className="flex flex-row items-end gap-2">
          <div className="mb-6 flex shrink-0 flex-col">
            {!isUser && showMetadata && avatarEnabled && (
              <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full">
                <ChatAgentIcon />
              </div>
            )}
          </div>
          <div className="flex min-w-0 flex-1 flex-col">
            {messageComponent}
            {showMetadata && !showChoicesMetadata && (
              <MessageMetadata isUser={isUser} sentTime={sentTime} />
            )}
          </div>
        </div>
      )}
      <ChoicesMessage
        message={parsedChoicesMessageData.text}
        choices={parsedChoicesMessageData.optionItems}
        isUser={isUser}
        showMetadata={showChoicesMetadata}
        sentTime={sentTime}
        position={position}
        isVoiceMode={isVoiceMode}
      />
    </>
  );
}

// Add ChoiceMessage component
function ChoicesMessage({
  message,
  isUser,
  showMetadata,
  choices,
  sentTime,
  position,
  isVoiceMode = false,
}: {
  message: string;
  isUser: boolean;
  showMetadata: boolean;
  choices: ChoiceOption[];
  sentTime: string;
  position: string;
  isVoiceMode?: boolean;
}) {
  const { sendMessage } = useChatContext();
  const isLoading = useAppSelector(selectIsLoading);
  const { chatMessage } = useConfigurationContext();
  const avatarEnabled = !isUser && chatMessage.agent.avatarEnabled;

  const messageClasses = useMemo(
    () => getMessageClasses(isUser, isVoiceMode, position),
    [isUser, isVoiceMode, position]
  );

  const handleClick = useCallback(
    (event: React.MouseEvent) => {
      const selectedOption = event.currentTarget;
      const selectedOptionText = selectedOption.textContent
        ? selectedOption.textContent
        : "";
      sendMessage(selectedOptionText);
    },
    [sendMessage]
  );

  return (
    <div>
      {message && (
        <div className="flex flex-row items-end gap-2">
          <div className="flex shrink-0 flex-col">
            {!isUser && avatarEnabled && (
              <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full">
                <ChatAgentIcon className="text-gray-500" />
              </div>
            )}
          </div>
          <div className="flex min-w-0 flex-1 flex-col">
            <div className={`${messageClasses} w-fit max-w-full`}>
              <p className="inline-block">{message}</p>
            </div>
            {showMetadata && (
              <MessageMetadata isUser={isUser} sentTime={sentTime} />
            )}
          </div>
        </div>
      )}
      <div className="flex flex-1 flex-col pt-2">
        {choices.map((option, index) => (
          <div key={index} className="py-1 pl-9">
            <button
              className={`min-h-[45px] rounded-xl border border-gray-200 px-4 focus-visible:bg-gray-100 focus-visible:outline-none ${!isLoading ? "hover:underline" : ""}`}
              onClick={handleClick}
              disabled={isLoading}
            >
              {option.titleItem.title}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

// Update ChatMessage component
export function ChatMessage({
  message,
  sentTime,
  sender,
  position,
  isVoiceMode,
  isLatestMessageFromUser,
  // isLatestMessageFromAgent,
  type = "text",
  id,
  onTimeout,
  status,
  functionName,
  isFirstMessage,
}: ChatMessageProps) {
  const isUser = sender === "user";
  const sentTimeFormatted = format(new Date(sentTime), "h:mmaaa");
  // const { toggleExpanded } = useChatContext();
  const showMetadata =
    (isUser && !isVoiceMode && isLatestMessageFromUser) ||
    ((position === "last" || position === "single") && !isUser && !isVoiceMode);

  // Update the streaming message splitting logic in ChatMessage component
  const streamingParts = useMemo(() => {
    // Check if this is a function call message or a surface action type
    if (type === "function" || type === "surfaceaction") {
      return [{ type, content: message }];
    }

    // Split on both complete tables and table starts
    const parts: { type: "text" | "table" | "function"; content: string }[] =
      [];
    const lines = message?.split("\n") ?? [];
    let currentText = "";
    let currentTable = "";
    let inTable = false;

    for (const line of lines) {
      const trimmedLine = line.trim();

      // Check if this line starts a table
      if (trimmedLine.startsWith("|") || trimmedLine.startsWith("+-")) {
        if (!inTable) {
          // If we have accumulated text, add it as a text part
          if (currentText.trim()) {
            parts.push({ type: "text", content: currentText.trim() });
            currentText = "";
          }
          inTable = true;
          currentTable = line + "\n";
        } else {
          currentTable += line + "\n";
        }
      } else if (inTable) {
        const trimmed = currentTable.trim();
        // If we're in a table but hit a non-table line, end the table
        if (trimmed) {
          parts.push({ type: "table", content: trimmed });
        }
        inTable = false;
        currentTable = "";
        currentText = line + "\n";
      } else {
        currentText += line + "\n";
      }
    }

    const trimmed = currentTable.trim();
    // Handle any remaining content
    if (inTable && trimmed) {
      parts.push({
        type: !isUser ? "table" : "text",
        content: trimmed,
      });
    } else if (currentText.trim()) {
      parts.push({ type: "text", content: currentText.trim() });
    }

    return parts;
  }, [message, type, isUser]);

  return (
    <>
      {streamingParts.map((part, index) => (
        <div
          key={index}
          className={`flex ${
            part.type === "function"
              ? "justify-center"
              : isUser
                ? "justify-end"
                : "justify-start"
          } ${
            position === "normal" || position === "last" || isFirstMessage
              ? "mt-0"
              : "mt-2"
          } ${position === "normal" || position === "first" ? "mb-2" : "mb-2"}`}
        >
          <div
            className={`flex text-sm ${isUser ? "max-w-[85%]" : "max-w-full"} ${
              part.type === "function" ? "w-full justify-center" : "flex-col"
            }`}
          >
            {part.type === "text" ? (
              <TextMessage
                message={part.content}
                isUser={isUser}
                showMetadata={
                  showMetadata && index === streamingParts.length - 1
                }
                sentTime={sentTimeFormatted}
                position={position}
                isVoiceMode={isVoiceMode}
              />
            ) : part.type === "table" ? (
              <TableMessage
                message={part.content}
                isUser={isUser}
                showMetadata={
                  showMetadata && index === streamingParts.length - 1
                }
                sentTime={sentTimeFormatted}
                // position={position}
              />
            ) : part.type === "surfaceaction" ? (
              <SurfaceActionMessage
                message={part.content}
                isUser={isUser}
                showMetadata={
                  showMetadata && index === streamingParts.length - 1
                }
                sentTime={sentTimeFormatted}
                position={position}
                isVoiceMode={isVoiceMode}
              />
            ) : (
              <FunctionMessage
                message={part.content}
                status={status}
                onTimeout={onTimeout}
                messageId={id}
                functionName={functionName}
              />
            )}
          </div>
        </div>
      ))}
    </>
  );
}
