import { ReactElement, useEffect, useState } from "react";
import { useResolvedUrl } from "../../hooks/useResolvedUrl";
import { cn } from "../../utils";

interface BaseIconProps {
  iconUrl: string;
  defaultIconUrl: string;
  fallbackSvg: ReactElement;
  altText: string;
  className?: string;
  "aria-hidden"?: boolean | "true" | "false";
  style?: React.CSSProperties;
  width?: number;
  height?: number;
}

/**
 * BaseIcon is a reusable component that handles icon rendering with fallback logic.
 * It attempts to load a custom image from iconUrl, and falls back to a provided SVG
 * if the image fails to load or if using the default icon URL.
 */
export const BaseIcon = ({
  iconUrl,
  defaultIconUrl,
  fallbackSvg,
  altText,
  className,
  "aria-hidden": ariaHidden,
  style,
  width = 24,
  height = 24,
}: BaseIconProps) => {
  const [imageError, setImageError] = useState(false);
  const resolvedIconUrl = useResolvedUrl(iconUrl);

  // Reset error state when iconUrl changes to give new URLs a chance to load
  useEffect(() => {
    setImageError(false);
  }, [resolvedIconUrl]);

  // Check if this is the default icon (when iconUrl matches the default)
  const isDefaultIcon = iconUrl === defaultIconUrl;

  // Show SVG if it's the default icon OR if custom image failed to load
  if (isDefaultIcon || imageError || !resolvedIconUrl) {
    return (
      <div
        className={cn("select-none", className)}
        aria-hidden={ariaHidden}
        style={style}
        data-testid="agent-icon"
      >
        {fallbackSvg}
      </div>
    );
  }

  // Render custom image
  return (
    <img
      src={resolvedIconUrl}
      alt={altText}
      width={width}
      height={height}
      className={cn("shrink-0 select-none", className)}
      aria-hidden={ariaHidden}
      style={style}
      data-testid="agent-icon"
      draggable={false}
      onError={() => {
        // Fallback: show default SVG when custom image fails to load
        setImageError(true);
      }}
    />
  );
};
