import { motion } from "motion/react";

interface LoadingDotsProps {
  color?: string;
}

export const LoadingDots = ({ color = "#ffffff" }: LoadingDotsProps) => (
  <div
    className="flex h-10 w-10 items-center justify-center gap-[2px]"
    role="status"
    aria-label="Connecting"
  >
    {[0, 0.3, 0.6].map((delay, index) => (
      <motion.div
        key={index}
        className="h-2 w-2 rounded-full"
        style={{ backgroundColor: color }}
        aria-hidden="true"
        animate={{
          y: [0, -4, 0],
        }}
        transition={{
          duration: 0.3,
          repeat: Infinity,
          ease: "easeInOut",
          delay,
          repeatDelay: 0.9,
        }}
      />
    ))}
  </div>
);
