import { useEffect } from "react";
import { useAppSelector } from "../store/hooks";
import { selectConversationId, selectPlanId } from "../store/slices";
import { dispatchEventToHost } from "../utils/events";

export const EventDispatcher = () => {
  const sessionId = useAppSelector(selectConversationId);
  const planId = useAppSelector(selectPlanId);

  useEffect(() => {
    if (sessionId) {
      dispatchEventToHost("onAgentforceMessagingSessionStarted", {
        sessionId,
      });
    }
  }, [sessionId]);

  useEffect(() => {
    if (planId) {
      dispatchEventToHost("onAgentforceMessagingPlanEvent", {
        planId,
      });
    }
  }, [planId]);

  return null;
};
