import "setimmediate";
import { miawAdapterDefinition } from "./miaw";
const defaultAdapterDefinition: AdapterDefinition = miawAdapterDefinition;
const defaultAdaptersToCreate = ["configuration", "conversation"] as const;

let currentAdapterDefinition: AdapterDefinition | undefined;
let currentAdapters: AdaptersWithGetter | undefined;

const listenerMap = new WeakMap<Adapter, AdapterListener>();

export const getAdapterFactoryFromDefinition = (
  adapterDefinition: AdapterDefinition,
  adapterType: keyof Adapters
) => {
  if (!adapterDefinition.supports.includes(adapterType)) {
    throw new Error(
      `Adapter definition ${adapterDefinition.name} does not support adapter type ${adapterType}`
    );
  }
  if (!adapterDefinition.adapters[adapterType]) {
    throw new Error(
      `Adapter definition ${adapterDefinition.name} does not define an adapter factory for ${adapterType}`
    );
  }

  return adapterDefinition.adapters[adapterType];
};

const makeListenerEventsAsync = (
  listener: AdapterListener
): AdapterListener => {
  const { onAdapterCreated, onAdapterEvent, onAdapterDestroyed } = listener;

  const newListener: AdapterListener = {
    onAdapterCreated(adapter) {
      setImmediate(() => {
        onAdapterCreated(adapter);
      });
    },
    onAdapterEvent(event) {
      setImmediate(() => {
        onAdapterEvent(event);
      });
    },
    onAdapterDestroyed(adapter) {
      setImmediate(() => {
        onAdapterDestroyed(adapter);
      });
    },
  };

  return newListener;
};

/**
 * Generally, you do not want to directly call this method. Instead, use `configureAdapters` to use the full adapter lifecycle.
 * @param adapterDefinition The adapter definition to use when creating the adapters
 * @param adapterListener A listener object that receives adapter events
 * @param adaptersToCreate (optional) A list of the adapters to create
 * @returns
 */
export const createAdaptersFromDefinition = (
  adapterDefinition: AdapterDefinition,
  adapterListener: AdapterListener,
  adaptersToCreate = defaultAdaptersToCreate
): AdaptersWithGetter => {
  const adapterInstances: Partial<Record<keyof Adapters, Adapter>> = {};
  const initializeAdapterInstance = (
    factory: AdapterFactory<Adapter>,
    getAdapters: GetAdaptersFn,
    adapterListener: AdapterListener,
    initValues?: any
  ) => {
    const asyncListener = makeListenerEventsAsync(adapterListener);
    const adapterInstance = factory(getAdapters, asyncListener, initValues);

    listenerMap.set(adapterInstance, asyncListener);
    // NOTE: This is a WeakMap and should let go once the adapter is unused
    //       However, unless it was created with `configureAdapters`, the
    //       listener won't get notified of its destruction

    adapterInstances[adapterInstance.adapterType as keyof Adapters] =
      adapterInstance;
    return adapterInstance;
  };

  const getAdapters =
    (
      fromDefinition: AdapterDefinition,
      except: (keyof Adapters)[],
      withListener: AdapterListener
    ) =>
    (): Adapters => {
      const adaptersGetter = adaptersToCreate.reduce(
        (adapters, adapterType) => {
          Object.defineProperty(adapters, adapterType, {
            get: () => {
              if (adapterInstances[adapterType]) {
                return adapterInstances[adapterType];
              }
              if (except.includes(adapterType)) {
                throw new Error(
                  `Adapter tried to get an instance of another adapter that hasn't finished initializing (${adapterType})`
                );
              }
              const newGetAdapters = getAdapters(
                fromDefinition,
                [...except, adapterType],
                withListener
              );
              const adapterFactory = getAdapterFactoryFromDefinition(
                fromDefinition,
                adapterType
              );
              const initValues = adapterDefinition.getInitValues?.(adapterType);
              const adapterInstance = initializeAdapterInstance(
                adapterFactory,
                newGetAdapters,
                adapterListener,
                initValues
              );
              adapterListener.onAdapterCreated(adapterInstance);
              return adapterInstance;
            },
          });

          return adapters;
        },
        {}
      ) as Adapters;

      return adaptersGetter;
    };

  const getters = getAdapters(adapterDefinition, [], adapterListener)();
  Object.defineProperty(getters, "getWithoutCreate", {
    get: () => (adapterType: keyof typeof adapterInstances) =>
      adapterInstances[adapterType],
  });
  return getters as AdaptersWithGetter;
};

export const configureAdapters = (
  adapterDefinition = defaultAdapterDefinition,
  adapterListener: AdapterListener
): Adapters => {
  if (adapterDefinition === currentAdapterDefinition && currentAdapters) {
    return currentAdapters;
  }
  resetAdapters();

  currentAdapters = createAdaptersFromDefinition(
    adapterDefinition,
    adapterListener
  );
  currentAdapterDefinition = adapterDefinition;
  return currentAdapters;
};

export const getCurrentAdapters = () => currentAdapters;
export const setCurrentAdapters = (adapters: Adapters) => {
  currentAdapters = adapters as AdaptersWithGetter;
};

/**
 * Destroys the current adapters invoking any necessary cleanup
 * @returns Promise that resolves once all adapters have been destroyed
 */
export const resetAdapters = () => {
  let resetAwait = () => Promise.resolve();
  if (currentAdapters && currentAdapterDefinition) {
    const destroyers = currentAdapterDefinition?.supports.map((adapterName) => {
      const adapter = currentAdapters?.getWithoutCreate(adapterName);
      if (!adapter) {
        return Promise.resolve();
      }

      return new Promise((resolve) => {
        const listener = listenerMap.get(adapter);
        listener?.onAdapterDestroyed(adapter);
        listenerMap.delete(adapter); // should happen automagically, but we do this to help stop memory leaks
        adapter?.destroy?.();
        resolve(undefined);
      });
    });

    resetAwait = async () => {
      await Promise.all(destroyers);
    };
    currentAdapters = undefined;
  }
  currentAdapterDefinition = undefined;

  return resetAwait();
};
