import "setimmediate";

interface TokenManagerProps {
  /**
   * Endpoint used to obtain authentication tokens
   */
  authEndpoint: string;
  /**
   * HTTP method for obtaining the token
   *
   * Default: `"GET"`
   */
  authMethod?: "GET" | "POST";
  /**
   * Endpoint used for refreshing auth tokens
   *
   * Default: {@link TokenManagerProps.authEndpoint | authEndpoint}
   */
  refreshEndpoint?: string;
  /**
   * Endpoint used for expiring auth tokens
   *
   * Default: {@link TokenManagerProps.authEndpoint | authEndpoint}
   */
  expireEndpoint?: string;
  /**
   * HTTP method for expiring the token
   *
   * Default: `"DELETE"`
   */
  expireMethod?: "POST" | "DELETE";
  /**
   * Enable token refresh
   *
   * This property controls whether or not a token _can_ be refreshed. If `false`, a new token will be obtained
   * when calling {@link TokenManager.getAuthToken | getAuthToken()}.
   *
   * Default: `true`
   */
  enableRefresh?: boolean;
  /**
   * Enable token auto-refresh
   *
   * Requires {@link TokenManagerProps.enableRefresh | enableRefresh} to be `true`.
   *
   * Default: `true`
   */
  autoRefresh?: boolean;
  /**
   * Number of seconds before token expiration to perform auto-refresh
   *
   * Requires {@link TokenManagerProps.autoRefresh | autoRefresh} to be `true`.
   *
   * Default: `120`
   */
  refreshWithin?: number;
}

export const getTokenExpiration = (checkToken: string) => {
  const tokenParts = checkToken.split(/\./g);
  const parsedTokenParts = tokenParts.reduce((parts, part) => {
    try {
      parts.push(JSON.parse(atob(part)));
    } catch (_ex) {
      /* do nothing */
    }
    return parts;
  }, [] as Token[]);
  const expirations = parsedTokenParts.reduce((exps, { exp }) => {
    if (exp !== undefined) {
      exps.push(exp);
    }
    return exps;
  }, [] as number[]);
  if (!expirations.length) return -1; // no expirations found, assume expired

  // return earliest expiration
  return Math.min(...expirations);
};

export const isTokenExpired = (checkToken: string) => {
  const expires = getTokenExpiration(checkToken);
  const now = Date.now() / 1000;
  return expires <= now;
};

export enum TokenStatus {
  ISSUED,
  EXPIRED,
  NO_TOKEN,
  FAILED,
  ERROR_PARSING,
  REFRESH_NOT_ENABLED,
  INVALID_CONFIGURATION,
  REFRESH_IN_PROGRESS,
}

export const isTokenStatus = (thing: unknown): thing is TokenStatus => {
  return Object.values(TokenStatus).includes(thing as any);
};

interface TokenManager {
  getAuthToken: () => Promise<AuthToken | TokenStatus>;
  refreshToken: () => Promise<AuthToken | TokenStatus>;
  expireToken: () => Promise<void>;
  getTokenStatus: () => TokenStatus;
}

const handleTokenResponse = async (response: Response) => {
  if (response.status !== 200) {
    console.error(
      "Did not receive a token from the auth endpoint:",
      await response.text()
    );
    return TokenStatus.FAILED;
  }
  const text = await response.text();
  try {
    const json = JSON.parse(text);
    if (json.access_token && json.token_format === "jwt") {
      const token = json as AuthToken;
      if (isTokenExpired(token.access_token)) {
        return TokenStatus.EXPIRED;
      }
      return token;
    }
  } catch (ex) {
    console.error("Unable to parse token response", ex, text);
  }
  return TokenStatus.ERROR_PARSING;
};

/**
 * An object designed to obtain, refresh, and expire authentication tokens
 *
 * @param Props to use to initialize the token manager
 */
export const createTokenManager = ({
  authEndpoint,
  authMethod = "GET",
  refreshEndpoint = authEndpoint,
  expireEndpoint = authEndpoint,
  expireMethod = "DELETE",
  enableRefresh = true,
  autoRefresh = true,
  refreshWithin = 120,
}: TokenManagerProps): TokenManager => {
  let tokenStatus: TokenStatus = TokenStatus.NO_TOKEN;
  let token: AuthToken | undefined;
  // TODO handle in-flight requests

  const setTokenStatus = (
    status:
      | TokenStatus.ERROR_PARSING
      | TokenStatus.EXPIRED
      | TokenStatus.FAILED
      | TokenStatus.INVALID_CONFIGURATION
      | TokenStatus.ISSUED
      | TokenStatus.NO_TOKEN
  ) => {
    tokenStatus = status;
    return status;
  };

  const getAuthToken = async (): Promise<AuthToken | TokenStatus> => {
    if (!authEndpoint) return setTokenStatus(TokenStatus.INVALID_CONFIGURATION);
    if (token && !isTokenExpired(token.access_token)) return token;

    const tokenRequest = await fetch(authEndpoint, {
      method: authMethod,
      mode: "cors",
    }).then(handleTokenResponse);

    if (!isTokenStatus(tokenRequest)) {
      token = tokenRequest;
      setTokenStatus(TokenStatus.ISSUED);
      startRefreshWait();
      return tokenRequest;
    }
    return setTokenStatus(tokenRequest);
  };

  let refreshTimeout: ReturnType<typeof setTimeout> | undefined;
  let isRefreshing = false;
  const startRefreshWait = () => {
    if (isRefreshing) return;

    stopRefreshWait();
    if (!token) return;
    if (!autoRefresh) return;

    const expiration = getTokenExpiration(token.access_token);
    const now = Date.now();
    const refreshAt = (expiration - refreshWithin) * 1000;
    if (refreshAt <= now) {
      // refresh immediately
      refreshToken();
      return;
    }

    setTimeout(refreshToken, refreshAt - now);
  };
  const stopRefreshWait = () => {
    if (refreshTimeout) {
      clearTimeout(refreshTimeout);
      refreshTimeout = undefined;
    }
  };

  const refreshToken = async (): Promise<AuthToken | TokenStatus> => {
    if (isRefreshing) return TokenStatus.REFRESH_IN_PROGRESS;
    stopRefreshWait();
    isRefreshing = true;

    if (!refreshEndpoint) {
      return setTokenStatus(TokenStatus.INVALID_CONFIGURATION);
    }
    if (!enableRefresh) return TokenStatus.REFRESH_NOT_ENABLED;
    if (!token) return TokenStatus.NO_TOKEN;
    if (isTokenExpired(token.access_token)) {
      return setTokenStatus(TokenStatus.EXPIRED);
    }

    const tokenRequest = await fetch(refreshEndpoint, {
      method: "POST",
      mode: "cors",
      body: token.access_token,
    }).then(handleTokenResponse);

    if (!isTokenStatus(tokenRequest)) {
      token = tokenRequest;
      setTokenStatus(TokenStatus.ISSUED);
      isRefreshing = false;
      startRefreshWait();
      return tokenRequest;
    }

    isRefreshing = false;
    return setTokenStatus(tokenRequest);
  };

  const expireToken = async (): Promise<void> => {
    stopRefreshWait();
    if (!token) return;
    if (!expireEndpoint) return;

    await fetch(refreshEndpoint, {
      method: expireMethod,
      mode: "cors",
    }).then(async (response) => {
      if (response.status !== 200) {
        // we failed to expire
        // log to console and continue
        console.error("Failed to expire token", await response.text());
      }
      token = undefined;
      setTokenStatus(TokenStatus.NO_TOKEN);
    });
  };

  const getTokenStatus = () => tokenStatus;

  return {
    getAuthToken,
    refreshToken,
    expireToken,
    getTokenStatus,
  };
};
