import { useMemo } from "react";

/**
 * A hook that synchronously resolves URLs, handling both absolute and relative paths.
 *
 * This hook takes a URL string and immediately returns a fully resolved URL:
 * - Returns undefined if the input URL is undefined
 * - Returns the original URL if it's already absolute (has a protocol scheme like http:, https:, data:, file:, etc.)
 * - Returns the original URL if it's protocol-relative (starts with //)
 * - Resolves root-relative URLs (starting with /) against the current window.location.origin
 * - Resolves other relative URLs (including dot-relative paths) against the current window.location.href
 *
 * The hook uses useMemo for efficient memoization and will only recompute when the input URL changes.
 *
 * @param url - The URL to resolve, can be absolute, relative, or undefined
 * @returns The resolved URL string immediately, or undefined if no URL was provided
 *
 * @example
 * // Absolute URL
 * const url = useResolvedUrl('https://example.com/icon.png');
 * // Returns: 'https://example.com/icon.png'
 *
 * @example
 * // Protocol-relative URL
 * const url = useResolvedUrl('//cdn.example.com/icon.png');
 * // Returns: '//cdn.example.com/icon.png'
 *
 * @example
 * // Root-relative URL
 * const url = useResolvedUrl('/assets/icon.png');
 * // Returns: 'https://current-origin.com/assets/icon.png'
 *
 * @example
 * // Relative URL
 * const url = useResolvedUrl('assets/icon.png');
 * // Returns: 'https://current-origin.com/current/path/assets/icon.png'
 *
 * @example
 * // Dot-relative URL
 * const url = useResolvedUrl('../assets/icon.png');
 * // Returns: 'https://current-origin.com/parent/assets/icon.png'
 */
export function useResolvedUrl(url: string | undefined): string | undefined {
  return useMemo(() => {
    if (url === undefined || url === null) {
      return undefined;
    }

    // Check if the URL is protocol-relative (starts with //)
    if (url.startsWith("//")) {
      return url;
    }

    // Check if the URL is absolute (has a protocol scheme)
    if (/^[a-z][a-z0-9+.-]*:/i.test(url)) {
      return url;
    }

    // Check if it's a root-relative URL (starts with /)
    if (url.startsWith("/")) {
      return new URL(url, window.location.origin).href;
    }

    // For other relative URLs (including dot-relative and empty strings), resolve against current location
    return new URL(url, window.location.href).href;
  }, [url]);
}
