import { LocalParticipant, RemoteParticipant } from "livekit-client";
import {
  createContext,
  ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useAgentLiveKit } from "../hooks/useAgentLiveKit";
import { useAppDispatch, useAppSelector, useAppState } from "../store/hooks";
import {
  selectActiveVoiceInstanceId,
  selectInstanceId,
  selectIsMuted,
  selectIsVoiceMode,
  selectIsVoiceModeLoading,
  selectVoiceModeError,
  setActiveVoiceInstanceId,
  setConversationChatState,
  setIsMuted as setIsMutedAction,
  setIsVoiceModeLoading as setIsVoiceModeLoadingAction,
  setVoiceModeError as setVoiceModeErrorAction,
} from "../store/slices";

export interface VoiceContextType {
  isConnected: boolean;
  isConnecting: boolean;
  isConnectingToAgent: boolean;
  localParticipant: LocalParticipant | undefined;
  remoteParticipants: RemoteParticipant[];
  connect: (forceReconnect?: boolean) => Promise<void>;
  disconnect: () => void;
  isVoiceMode: boolean;
  isVoiceModeLoading: boolean;
  isOtherVoiceMode: boolean;
  isMuted: boolean;
  microphonePermission: PermissionState;
  toggleVoiceMode: () => Promise<void>;
  toggleMute: () => void;
  voiceModeError: string | undefined;
  requestMicrophonePermission: () => Promise<boolean>;
  handleRetryJoinVoice: () => Promise<void>;
  setIsVoiceModeLoading: (isVoiceModeLoading: boolean) => void;
}

const VOICE_MODE_ERROR_MESSAGES = {
  CONNECT_ERROR: "Failed to connect to voice mode",
  PERMISSION_ERROR: "Allow microphone access to enable voice mode",
} as const;

const VoiceContext = createContext<VoiceContextType | undefined>(undefined);

export const useVoice = () => {
  const context = useContext(VoiceContext);
  if (!context) {
    throw new Error("useVoice must be used within a VoiceProvider");
  }
  return context;
};

interface VoiceProviderProps {
  children: ReactNode;
  joinVoice?: (forceReconnect?: boolean) => Promise<any>;
}

export const VoiceProvider = ({ children, joinVoice }: VoiceProviderProps) => {
  const dispatch = useAppDispatch();
  const isVoiceMode = useAppSelector(selectIsVoiceMode);
  const voiceInstanceId = useAppSelector(selectActiveVoiceInstanceId);
  const instanceId = useAppSelector(selectInstanceId);
  const [voiceModeError, setVoiceModeError] = useAppState<string | undefined>(
    selectVoiceModeError,
    setVoiceModeErrorAction
  );
  const [isMuted, setIsMuted] = useAppState(selectIsMuted, setIsMutedAction);
  const [isVoiceModeLoading, setIsVoiceModeLoading] = useAppState(
    selectIsVoiceModeLoading,
    setIsVoiceModeLoadingAction
  );
  const [microphonePermission, setMicrophonePermission] =
    useState<PermissionState>("prompt");
  const isInitialRender = useRef(true);

  const agentLiveKitProps = useMemo(
    () => ({ joinVoice: joinVoice ?? (async () => {}) }),
    [joinVoice]
  );
  const {
    isConnected,
    isConnecting,
    connect: doConnect,
    disconnect,
    localParticipant,
    remoteParticipants,
  } = useAgentLiveKit(agentLiveKitProps);

  const isOtherVoiceMode =
    isVoiceMode &&
    voiceInstanceId !== undefined &&
    instanceId !== voiceInstanceId;

  const isConnectingToAgent = useMemo(() => {
    if (!isVoiceMode || isOtherVoiceMode) return false;
    console.debug("remoteParticipants", remoteParticipants);
    return remoteParticipants.length === 0;
  }, [isVoiceMode, isOtherVoiceMode, remoteParticipants]);

  const requestMicrophonePermission = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach((track) => track.stop());
      setMicrophonePermission("granted");
      return true;
    } catch (_error) {
      setMicrophonePermission("denied");
      setIsVoiceModeLoading(false);
      setVoiceModeError(VOICE_MODE_ERROR_MESSAGES.PERMISSION_ERROR);
      return false;
    }
  }, [setVoiceModeError, setIsVoiceModeLoading]);

  const toggleVoiceMode = useCallback(async () => {
    if (!isVoiceMode && microphonePermission !== "granted") {
      setIsVoiceModeLoading(true);
      if (!(await requestMicrophonePermission())) {
        return;
      }
    }
    dispatch(setConversationChatState({ isVoiceMode: !isVoiceMode }));
    if (!isVoiceMode) {
      setIsMuted(false); // unmute if we're toggling on voice mode
      dispatch(setActiveVoiceInstanceId(instanceId));
      await doConnect();
    } else {
      disconnect();
    }
    setIsVoiceModeLoading(false);
  }, [
    isVoiceMode,
    microphonePermission,
    dispatch,
    requestMicrophonePermission,
    instanceId,
    doConnect,
    disconnect,
    setIsVoiceModeLoading,
    setIsMuted,
  ]);

  const toggleMute = useCallback(() => {
    setIsMuted((prev) => !prev);
  }, [setIsMuted]);

  const connect = useCallback(
    async (forceReconnect = false) => {
      await doConnect(forceReconnect);
    },
    [doConnect]
  );

  useEffect(() => {
    localParticipant?.setMicrophoneEnabled(!isMuted);
  }, [localParticipant, isMuted]);

  useEffect(() => {
    if (isInitialRender.current) return;
    if (!isVoiceMode) {
      disconnect();
    }
  }, [isVoiceMode, disconnect]);

  const handleRetryJoinVoice = useCallback(async () => {
    if (isConnecting) return;
    try {
      await connect(true);
    } catch (error) {
      setVoiceModeError(VOICE_MODE_ERROR_MESSAGES.CONNECT_ERROR);
      console.error("Failed to reconnect to LiveKit:", error);
    }
  }, [connect, isConnecting, setVoiceModeError]);

  const contextValue = useMemo(
    () => ({
      isConnected,
      isConnecting,
      isConnectingToAgent,
      localParticipant,
      remoteParticipants,
      connect,
      disconnect,
      isVoiceMode,
      isVoiceModeLoading,
      isOtherVoiceMode,
      isMuted,
      microphonePermission,
      toggleVoiceMode,
      toggleMute,
      requestMicrophonePermission,
      handleRetryJoinVoice,
      voiceModeError,
      setIsVoiceModeLoading,
    }),
    [
      isConnected,
      isConnecting,
      isConnectingToAgent,
      localParticipant,
      remoteParticipants,
      connect,
      disconnect,
      isVoiceMode,
      isVoiceModeLoading,
      isOtherVoiceMode,
      isMuted,
      microphonePermission,
      toggleVoiceMode,
      toggleMute,
      requestMicrophonePermission,
      handleRetryJoinVoice,
      voiceModeError,
      setIsVoiceModeLoading,
    ]
  );

  useEffect(() => {
    if (isInitialRender.current) {
      isInitialRender.current = false;
    }
  }, []);

  return (
    <VoiceContext.Provider value={contextValue}>
      {children}
    </VoiceContext.Provider>
  );
};
