import { useCallback, useEffect, useState } from "react";
import { useAppState } from "../store/hooks";
import {
  selectVoiceModeError,
  setVoiceModeError as setVoiceModeErrorAction,
} from "../store/slices";
import { AudioContextState } from "../types";

// A global store to track all active microphone streams
// This will allow us to close all streams when LiveKit disconnects
const activeMicrophoneStreams = new Set<MediaStream>();

// Function to stop all active microphone streams
export const stopAllMicrophoneStreams = async () => {
  if (activeMicrophoneStreams.size) {
    console.debug(
      `Stopping ${activeMicrophoneStreams.size} active microphone stream(s)`
    );

    activeMicrophoneStreams.forEach((stream) => {
      stream.getTracks().forEach((track) => {
        track.stop();
      });
    });

    activeMicrophoneStreams.clear();
  }

  try {
    const tracks = await navigator.mediaDevices.getUserMedia({ audio: true });
    if (tracks) {
      console.debug(`Stopping all tracks from reset stream`);
      tracks.getTracks().forEach((track) => {
        console.debug(`Stopping track: ${track.id}`);
        track.stop();
      });
    }
  } catch (err) {
    throw new Error(`Failed to get media during reset: ${err}`);
  }
};

export const useAudioContext = (
  useMicrophone?: boolean,
  fftSize: number = 2048,
  smoothingTimeConstant: number = 0.8,
  minDecibels: number = -90,
  maxDecibels: number = -10,
  isOtherVoiceMode?: boolean
): AudioContextState => {
  const [audioState, setAudioState] = useState<AudioContextState>({
    audioContext: null,
    analyser: null,
    dataArray: null,
    source: null,
  });
  const [voiceModeError, setVoiceModeError] = useAppState<string | undefined>(
    selectVoiceModeError,
    setVoiceModeErrorAction
  );

  const createAnalyser = useCallback(
    (audioContext: AudioContext) => {
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = fftSize;
      analyser.smoothingTimeConstant = smoothingTimeConstant;
      analyser.minDecibels = minDecibels;
      analyser.maxDecibels = maxDecibels;
      const dataArray = new Uint8Array(analyser.frequencyBinCount);
      return { analyser, dataArray };
    },
    [fftSize, smoothingTimeConstant, minDecibels, maxDecibels]
  );

  const initializeAudioContext = useCallback(async () => {
    try {
      const audioContext = new (window.AudioContext ||
        window.webkitAudioContext)();
      const { analyser, dataArray } = createAnalyser(audioContext);

      if (useMicrophone) {
        const stream = await navigator.mediaDevices.getUserMedia({
          audio: true,
        });

        // Store stream reference globally for management
        activeMicrophoneStreams.add(stream);

        const source = audioContext.createMediaStreamSource(stream);
        source.connect(analyser);
        setAudioState({ audioContext, analyser, dataArray, source, stream });
        setVoiceModeError(undefined);
      }
    } catch (error) {
      console.error("Audio initialization error:", error);

      // Check if it's a permission error to prevent retrying
      if (error instanceof DOMException && error.name === "NotAllowedError") {
        setVoiceModeError("Allow microphone access to enable voice mode");
      } else {
        setVoiceModeError(`Audio initialization failed`);
      }

      // Reset state on error
      setAudioState({
        audioContext: null,
        analyser: null,
        dataArray: null,
        source: null,
      });
    }
  }, [useMicrophone, createAnalyser, setVoiceModeError]);

  // Effect for initializing audio context
  useEffect(() => {
    if (!isOtherVoiceMode && !voiceModeError) {
      initializeAudioContext();
    }
  }, [initializeAudioContext, isOtherVoiceMode, voiceModeError]);

  // Effect for cleanup
  useEffect(() => {
    return () => {
      if (audioState.source) {
        if (audioState.source instanceof AudioBufferSourceNode) {
          audioState.source.stop();
        }
        audioState.source.disconnect();
      }
      // Clean up microphone stream on component unmount
      if (audioState.stream) {
        audioState.stream.getTracks().forEach((track) => track.stop());
        activeMicrophoneStreams.delete(audioState.stream);
      }
      audioState.analyser?.disconnect();
      audioState.audioContext?.close();
    };
  }, [audioState]);

  return audioState;
};
