import { useCallback, useMemo, useRef } from "react";
import {
  type TypedUseSelectorHook,
  useDispatch,
  useSelector,
} from "react-redux";
import { type AppDispatch, type RootState, store } from "./index";
import { selectScriptUrl } from "./slices";

// Use throughout your app instead of plain `useDispatch` and `useSelector`
export const useAppDispatch: () => AppDispatch = useDispatch;
export const useAppSelector: TypedUseSelectorHook<RootState> = useSelector;

type FunctionType<T = unknown> = (...args: unknown[]) => T;
type SetterType<T = unknown> = (
  newValueOrFn: T | ((oldValue: T) => T)
) => unknown;
/**
 * Mimic's a `useState` hook in Redux by building a custom `useX` function from a selector and setter function.
 * The selector can be any function that accepts the current state and returns a value.
 * The setter can be any function that accepts the new value and returns a valid, dispatchable action.
 * @param selector the selector used to get the current value; should match what is passed to a `useSelector` hook
 * @param setter the action creator function for setting the value; you can either pass the action creator directly or a custom function
 * @returns `[currentValue, setValue]` mimicking `useState`
 */
export const useAppState = <T>(
  selector: (state: RootState) => T,
  setter: (newValue: T) => Parameters<ReturnType<typeof useDispatch>>[0]
): [T, SetterType<T>] => {
  const currentValue = useAppSelector(selector);
  const currentValueRef = useRef(currentValue);
  currentValueRef.current = currentValue;
  const setValue = useCallback(
    (newValueOrFn: SetterType<T>) => {
      let newValue: T;
      if (typeof newValueOrFn === "function") {
        const currentValue = currentValueRef.current;
        newValue = (newValueOrFn as FunctionType<T>)(currentValue);
      } else {
        newValue = newValueOrFn;
      }
      store.dispatch(setter(newValue));
    },
    [setter]
  );
  const memoized = useMemo(() => {
    return [currentValue, setValue];
  }, [currentValue, setValue]) as [T, SetterType<T>];
  return memoized;
};

export const useScriptResolver = () => {
  const scriptUrl = useAppSelector(selectScriptUrl);
  const scriptRoot = scriptUrl.replace(/\/[^/]+$/, "") || "/";

  const url = (path?: string) =>
    path
      ? `${scriptRoot}${path.startsWith("/") ? "" : "/"}${path}`.replace(
          /^\/\//,
          "/"
        )
      : scriptRoot;

  return { url };
};
