import {
  createListenerMiddleware,
  isAnyOf,
  UnknownAction,
} from "@reduxjs/toolkit";
import { REHYDRATE } from "redux-persist";
import { throttle } from "../../utils/throttle";
import { conversationDataManager } from "../conversationDataManager";
import {
  ConversationState,
  sessionTerminated,
  setConversationData,
  setCurrentConversationId,
} from "../slices/conversation";

interface PartialState {
  conversation: ConversationState;
}

export const conversationDataMiddleware = createListenerMiddleware();

type ListenerApi = Parameters<
  Parameters<typeof conversationDataMiddleware.startListening>[0]["effect"]
>[1];
const handleUpdate = (_action: UnknownAction, listenerApi: ListenerApi) => {
  const state = listenerApi.getState() as PartialState;
  conversationDataManager._updateFromState(state);
};

conversationDataMiddleware.startListening({
  matcher: isAnyOf(setCurrentConversationId, setConversationData),
  effect: handleUpdate,
});

// Listen for Redux-persist REHYDRATE action to update conversationDataManager
// when state is restored from persistence after page refresh
conversationDataMiddleware.startListening({
  type: REHYDRATE,
  effect: handleUpdate,
});

conversationDataMiddleware.startListening({
  // trigger on state changes
  // debounce to avoid excessive updates
  // this action is a string
  predicate: (action) => action.type === "@@session_sync/state_change",
  effect: throttle(handleUpdate, 100),
});

conversationDataMiddleware.startListening({
  actionCreator: sessionTerminated,
  effect: () => {
    conversationDataManager._clearSession();
  },
});
