import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import ReactMarkdown, { type Components } from "react-markdown";
import remarkGfm from "remark-gfm";

// TableWithScrollShadow for table rendering
export function TableWithScrollShadow({
  children,
}: {
  children: React.ReactNode;
}) {
  const [showLeftShadow, setShowLeftShadow] = useState(false);
  const [showRightShadow, setShowRightShadow] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const handleScroll = useCallback(() => {
    if (!scrollRef.current) return;
    const { scrollLeft, scrollWidth, clientWidth } = scrollRef.current;
    const maxScroll = scrollWidth - clientWidth;
    setShowLeftShadow(scrollLeft > 20);
    setShowRightShadow(scrollLeft < maxScroll - 20);
  }, []);

  useEffect(() => {
    const scrollElement = scrollRef.current;
    if (scrollElement) {
      handleScroll();
      scrollElement.addEventListener("scroll", handleScroll);
      const resizeObserver = new ResizeObserver(handleScroll);
      resizeObserver.observe(scrollElement);
      return () => {
        scrollElement.removeEventListener("scroll", handleScroll);
        resizeObserver.disconnect();
      };
    }
  }, [handleScroll]);

  return (
    <div className="relative w-full">
      <div
        className={`pointer-events-none absolute top-2 bottom-2.5 left-0 w-8 bg-gradient-to-r from-black/10 to-transparent transition-opacity duration-200 ${
          showLeftShadow ? "opacity-100" : "opacity-0"
        }`}
      />
      <div
        ref={scrollRef}
        className="scrollbar-thin scrollbar-thumb-gray-300 scrollbar-track-gray-100 w-full overflow-x-auto pt-2 pb-1"
      >
        <div className="inline-block min-w-full overflow-hidden rounded-xl border border-gray-300">
          <table className="w-full table-auto text-sm break-words">
            {children}
          </table>
        </div>
      </div>
      <div
        className={`pointer-events-none absolute top-2 right-0 bottom-2.5 w-8 bg-gradient-to-l from-black/10 to-transparent transition-opacity duration-200 ${
          showRightShadow ? "opacity-100" : "opacity-0"
        }`}
      />
    </div>
  );
}

const liBase =
  (allowTopLevelDecimal: boolean = false): Components["li"] =>
  ({ children, node }) => {
    // @ts-expect-error: node.parent?.parent?.type is not typed by react-markdown
    const isNested = node.parent?.parent?.type === "listItem";
    const listClass =
      isNested || !allowTopLevelDecimal
        ? "list-disc list-inside ml-4"
        : "list-decimal list-inside [&>p]:inline-block";
    return <li className={listClass}>{children}</li>;
  };
export const liWithTopLevelDecimal = liBase(true);
export const liWithoutTopLevelDecimal = liBase(false);

// Default markdown components
export const defaultMarkdownComponents: Components = {
  li: liWithTopLevelDecimal,
  ol: ({ children }) => <ol className="ml-4 list-decimal">{children}</ol>,
  ul: ({ children }) => <ul className="mb-1 ml-4 list-disc">{children}</ul>,
  table: ({ children }) => (
    <TableWithScrollShadow>{children}</TableWithScrollShadow>
  ),
  thead: ({ children }) => <thead className="bg-gray-200">{children}</thead>,
  th: ({ children }) => (
    <th
      title={typeof children === "string" ? children : undefined}
      className="min-w-[100px] border-r border-b border-gray-300 px-4 py-2 text-left font-semibold whitespace-nowrap last:border-r-0"
    >
      {children}
    </th>
  ),
  td: ({ children }) => (
    <td className="min-w-[100px] border-r border-b border-gray-300 bg-white px-4 py-2 break-words last:border-r-0 [tr:last-child_&]:border-b-0">
      {children}
    </td>
  ),
  p: ({ children }) => <p>{children}</p>,
};

export interface MarkdownProps {
  children: string;
  className?: string;
  components?: Components;
}

export function Markdown({ children, className, components }: MarkdownProps) {
  // Merge custom components with defaults
  const mergedComponents = useMemo(
    () => ({ ...defaultMarkdownComponents, ...components }),
    [components]
  );
  return (
    <div className={className}>
      <ReactMarkdown remarkPlugins={[remarkGfm]} components={mergedComponents}>
        {children}
      </ReactMarkdown>
    </div>
  );
}
