import type { PayloadAction } from "@reduxjs/toolkit";
import type {
  Action,
  Dispatch,
  Middleware,
  MiddlewareAPI,
  UnknownAction,
} from "redux";
import "setimmediate";

type AsyncDispatch = (asyncAction: Action) => unknown;
export type ActionWithAsyncDispatch = Action & { asyncDispatch: AsyncDispatch };

type IgnoreCheck = string | string[] | ((action: UnknownAction) => boolean);
type IgnoreChecks = IgnoreCheck | IgnoreCheck[];

export const shouldIgnoreAction = (
  action: UnknownAction,
  ignoreChecks?: IgnoreChecks
): boolean => {
  if (!ignoreChecks) return false;

  const actionType = action.type;
  const ignoreChecksAsArray = Array.isArray(ignoreChecks)
    ? ignoreChecks
    : [ignoreChecks];

  return ignoreChecksAsArray.some((ignoreCheck) => {
    if (typeof ignoreCheck === "string") {
      return ignoreCheck === actionType;
    }
    if (Array.isArray(ignoreCheck)) {
      return shouldIgnoreAction(action, ignoreCheck);
    }
    // ignoreCheck is a function
    return ignoreCheck(action);
  });
};

export const asAsyncAction = (action: UnknownAction | PayloadAction) =>
  action as unknown as ActionWithAsyncDispatch;

export const createAsyncDispatchMiddleware = (ignore?: IgnoreChecks) => {
  return ((store: MiddlewareAPI) => {
    return (next: Dispatch<Action>) => {
      return (action: Action) => {
        if (shouldIgnoreAction(action, ignore)) return next(action);
        let syncActivityFinished = false;
        let actionQueue: Action[] = [];

        const flushQueue = () => {
          actionQueue.forEach((a) => store.dispatch(a)); // flush queue
          actionQueue = [];
        };

        const asyncDispatch: AsyncDispatch = (asyncAction: Action) => {
          actionQueue = actionQueue.concat([asyncAction]);

          if (syncActivityFinished) {
            setImmediate(() => {
              flushQueue();
            });
          }
        };

        const actionWithAsyncDispatch = Object.assign({}, action, {
          asyncDispatch,
        }) as ActionWithAsyncDispatch;

        syncActivityFinished = true;
        flushQueue();
        return next(actionWithAsyncDispatch);
      };
    };
  }) as Middleware; // using `as Middleware` avoids some type issues
};

export const asyncDispatchMiddleware = createAsyncDispatchMiddleware();
