import { v4 } from "uuid";
import { getConfiguration, isConfigurationAvailable } from "../../connectors";
import { createMiawEventSourceHandlers } from "./miawEventSourceHandlers";
import { createMiawInAppService } from "./miawInAppService";

export const miawConversationAdapterFactory: AdapterFactory<
  MiawConversationAdapter
> = (_getAdapters: GetAdaptersFn, listener: AdapterListener) => {
  const ref: {
    adapter: MiawConversationAdapter | undefined;
  } = {
    adapter: undefined,
  };

  const getApi = (() => {
    if (!isConfigurationAvailable()) {
      throw new Error("MIAW configuration is not available");
    }
    const miawConfiguration = getConfiguration()!;
    const api = createMiawInAppService({
      orgId: miawConfiguration.orgId,
      name: miawConfiguration.name,
      scrt2URL: miawConfiguration.scrt2URL,
    });
    return async () => api;
  })();

  let currentConversationId: string | undefined;

  ref.adapter = {
    adapterType: "conversation",
    get conversationId(): string | undefined {
      return currentConversationId;
    },
    set conversationId(value: string | undefined) {
      currentConversationId = value;
      getApi().then((api) => {
        api.setConversationId(value);
      });
    },
    startConversation: async () => {
      if (currentConversationId) {
        throw new Error("Conversation in progress");
      }
      const api = await getApi();
      await api.getAccessToken();
      currentConversationId = await api.createConversation();
      const miawEventSourceHandlers = createMiawEventSourceHandlers(
        listener,
        ref
      );
      await api.subscribeToEventSource(miawEventSourceHandlers);
      listener.onAdapterEvent({
        eventName: "startConversation",
        eventData: {
          sessionId: currentConversationId,
        },
        adapter: ref.adapter!,
      });
      return currentConversationId;
    },
    endConversation: async () => {
      const api = await getApi();
      await api.closeConversation();
      listener.onAdapterEvent({
        eventName: "receivedMessage",
        eventData: {
          type: "system",
          message: "Conversation has ended",
          sentTime: new Date().toISOString(),
          id: v4(),
        },
        adapter: ref.adapter!,
      });
      await api.closeEventSource();
      currentConversationId = "";
      listener.onAdapterEvent({
        eventName: "endConversation",
        eventData: {
          sessionId: currentConversationId,
        },
        adapter: ref.adapter!,
      });
      listener.onAdapterEvent({
        eventName: "sessionTerminated",
        eventData: {
          sessionId: currentConversationId,
        },
        adapter: ref.adapter!,
      });
    },
    sendMessage: async (
      messageId: string,
      messageText: string,
      replyingToMessage?: string
    ) => {
      const api = await getApi();
      api.sendTextMessage(
        messageText,
        messageId,
        replyingToMessage ?? "",
        false
      );
    },
    setIsTyping: async (_isTyping: boolean) => {
      // TODO finish
    },
    destroy: async () => {
      // TODO remove listeners
    },
  };

  return ref.adapter;
};
