import { useEffect, useMemo, useRef } from "react";
import { Provider } from "react-redux";
import { PersistGate } from "redux-persist/integration/react";
import { configureAdapters, getCurrentAdapters } from "../../adapters";
import { createAgentAdapterDefinition } from "../../adapters/agent";
import { createMiawAdapterDefinition } from "../../adapters/miaw";
import {
  setAgentApi,
  setAgentApiConfiguration,
  setConfiguration,
} from "../../connectors";
import {
  configurePersistor,
  conversationDataManager,
  store,
} from "../../store";
import { useAppSelector } from "../../store/hooks";
import {
  registerAdapters,
  selectConversationId,
  setHostUrl,
  setScriptUrl,
  updateConfiguration,
} from "../../store/slices";
import { createAgentAdapterListener } from "./agentAdapterListener";
import { ReduxProviderConnectors, ReduxProviderProps } from "./interfaces";
import { createMiawAdapterListener } from "./miawAdapterListener";

const connectorMap: {
  [K in keyof ReduxProviderConnectors]: (
    getApi: ReduxProviderConnectors[K]
  ) => unknown;
} = {
  agentApi: (getApi) => setAgentApi(getApi()),
  agentApiConfiguration: (getConfiguration) =>
    setAgentApiConfiguration(getConfiguration()),
  miawConfiguration: (getConfiguration) => setConfiguration(getConfiguration()),
};

export const ReduxProvider = (props: ReduxProviderProps) => {
  const {
    adapter,
    children,
    connectors,
    disablePersistence = false,
    hostUrl,
    listener,
    scriptBase,
  } = props;
  const shouldUseAgentApi = adapter === "agent";
  const adapterDefinitionRef = useRef<AdapterDefinition | undefined>(undefined);
  useEffect(() => {
    if (connectors) {
      const connectorsToSet = Object.keys(
        connectors
      ) as (keyof ReduxProviderConnectors)[];
      connectorsToSet.forEach((connectorName) => {
        if (connectors[connectorName]) {
          console.debug(`Setting connector for ${connectorName}`);
          // super annoying type typing topiweiortuwhoeihjw!!!!!
          connectorMap[connectorName](connectors[connectorName] as any);
        }
      });
    }
    // TODO disconnect from connectors on change
  }, [connectors]);
  const adapterRef = useRef<Adapters>(undefined);
  const adapterListener: AdapterListener = useMemo(() => {
    if (listener) {
      return listener;
    }

    const getAdapter = () => adapterRef.current;
    const getAdapterDefinition = () => adapterDefinitionRef.current;

    if (shouldUseAgentApi) {
      return createAgentAdapterListener({
        getAgentAdapter: getAdapter,
        getAdapterDefinition,
      });
    } else {
      return createMiawAdapterListener({
        getMiawAdapter: getAdapter,
        getAdapterDefinition,
      });
    }
  }, [listener, shouldUseAgentApi]);

  const Init = () => {
    const initRef = useRef(false);
    useEffect(() => {
      if (initRef.current) return;
      console.debug("Init");
      initRef.current = true;

      let adapterDefinition: AdapterDefinition;
      const state = store.getState();
      const { currentConversationId } = state.conversation;
      const initValues = {
        conversation: {
          currentConversationId,
          getData: () => {
            return conversationDataManager.getData();
          },
          setData: (data: Record<string, unknown>) => {
            conversationDataManager.setData(data);
          },
        },
      };

      if (shouldUseAgentApi) {
        adapterDefinition = createAgentAdapterDefinition(initValues);
      } else if (adapter === "miaw") {
        adapterDefinition = createMiawAdapterDefinition(initValues);
        // Set allowVoiceMode to false for miaw adapter
        store.dispatch(updateConfiguration({ allowVoiceMode: false }));
      } else {
        throw new Error(`Unknown adapter type: ${adapter}`);
      }

      adapterDefinitionRef.current = adapterDefinition;

      const adapters = configureAdapters(adapterDefinition, adapterListener);
      adapterRef.current = adapters;
      store.dispatch(registerAdapters(adapters));

      store.dispatch(setHostUrl(hostUrl ?? ""));
      store.dispatch(setScriptUrl(scriptBase ?? ""));
      console.debug("Init done");
    }, []);

    const sessionId = useAppSelector(selectConversationId);
    useEffect(() => {
      const adapters = getCurrentAdapters();

      console.debug("Setting session ID", sessionId, adapters);

      if (shouldUseAgentApi) {
        if (adapters?.conversation) {
          (adapters.conversation as AgentConversationAdapter).sessionId =
            sessionId;
        }
      } else {
        if (adapters?.conversation) {
          (adapters.conversation as MiawConversationAdapter).conversationId =
            sessionId;
        }
      }
    }, [sessionId]);

    return <></>;
  };

  const persistor = useMemo(
    () => configurePersistor(disablePersistence),
    [disablePersistence]
  );

  return (
    <Provider store={store}>
      <PersistGate loading={null} persistor={persistor}>
        <Init />
        {children}
      </PersistGate>
    </Provider>
  );
};
