export const createMiawEventSourceHandlers = (
  listener: AdapterListener,
  adapterRef: { adapter: MiawConversationAdapter | undefined }
) => ({
  CONVERSATION_MESSAGE: (eventData: MessageEvent) => {
    const data = JSON.parse(eventData.data) as MiawServerSentEvent;
    const entryPayload = JSON.parse(
      data.conversationEntry.entryPayload
    ) as ConversationMessageEntryPayload;
    const messageObject = entryPayload.abstractMessage;
    listener.onAdapterEvent({
      eventName: "receivedMessage",
      eventData: {
        id: messageObject.id,
        message: messageObject.staticContent.text,
        sentTime: new Date(
          data.conversationEntry.transcriptedTimestamp
        ).toISOString(),
        sender:
          data.conversationEntry.sender.role === "EndUser"
            ? "user"
            : "assistant",
        senderDisplayName: data.conversationEntry.senderDisplayName,
        direction:
          data.conversationEntry.sender.role === "EndUser"
            ? "outgoing"
            : "incoming",
        position: "single",
        type: "text",
      },
      adapter: adapterRef.adapter!,
    });
  },

  CONVERSATION_PARTICIPANT_CHANGED: (eventData: MessageEvent) => {
    const data = JSON.parse(eventData.data) as MiawServerSentEvent;
    const entryPayload = JSON.parse(
      data.conversationEntry.entryPayload
    ) as ConversationParticipantChangedEntryPayload;

    const operation = entryPayload.entries[0].operation;
    switch (operation) {
      case "add":
      case "remove": {
        listener.onAdapterEvent({
          eventName: "participantChanged",
          eventData: entryPayload,
          adapter: adapterRef.adapter!,
        });
        break;
      }
      default: {
        console.debug("Unknown operation", operation);
        break;
      }
    }
  },

  // TODO: Add more handlers
});
