import {
  LocalParticipant,
  RemoteParticipant,
  Room,
  RoomEvent,
} from "livekit-client";

export interface LiveKitConfig {
  url: string;
  token: string;
  roomName: string;
}

class LiveKitService {
  private room: Room | null = null;

  async connect(config: LiveKitConfig): Promise<Room> {
    this.room = new Room({
      adaptiveStream: true,
      dynacast: true,
    });

    // Set up event listeners
    this.room
      .addListener(
        RoomEvent.ParticipantConnected,
        this.handleParticipantConnected
      )
      .addListener(
        RoomEvent.ParticipantDisconnected,
        this.handleParticipantDisconnected
      )
      .addListener(RoomEvent.Disconnected, this.handleDisconnected)
      .addListener(RoomEvent.TrackPublished, (publication, participant) => {
        console.log(
          "Track published:",
          publication.trackSid,
          publication.kind,
          "by",
          participant.identity
        );
        // Subscribe to the track - attachment will happen in TrackSubscribed event
        publication.setSubscribed(true);
        participant.setVolume(1);
      })
      .addListener(
        RoomEvent.TrackSubscribed,
        (track, publication, participant) => {
          console.debug(
            "Track subscribed:",
            publication.trackSid,
            track.kind,
            "by",
            participant.identity
          );
          // Attach the track now that it's subscribed and available
          const element = track.attach();
          if (element) {
            console.debug(
              "Track element attached on subscribe:",
              element.tagName,
              "for track",
              publication.trackSid
            );
            // Make sure audio elements are not muted and have appropriate volume
            if (element instanceof HTMLAudioElement) {
              element.muted = false;
              element.volume = 1.0;
              element
                .play()
                .catch((err) => console.error("Error playing audio:", err));
            }
            document.body.appendChild(element);
          } else {
            console.error(
              "Failed to attach element for subscribed track:",
              publication.trackSid
            );
          }
        }
      );

    try {
      await this.room.connect(config.url, config.token);
      await this.room.localParticipant.setMicrophoneEnabled(true);
      this.room.remoteParticipants.forEach((participant) => {
        participant.trackPublications.forEach((publication) => {
          publication.setSubscribed(true);
          const element = publication.track?.attach();
          if (element) {
            element.muted = false;
            element.volume = 1;
            document.body.appendChild(element);
          }
        });
      });
      console.log("Connected to room:", config.roomName, this.room);
      // DEBUG
      (window as any).__room = this.room;
      return this.room;
    } catch (error) {
      console.error("Failed to connect to room:", error);
      throw error;
    }
  }

  private handleParticipantConnected = (participant: RemoteParticipant) => {
    console.log("Participant connected:", participant.identity);
  };

  private handleParticipantDisconnected = (participant: RemoteParticipant) => {
    console.log("Participant disconnected:", participant.identity);
  };

  private handleDisconnected = async () => {
    console.log("Disconnected from room");
    this.room = null;
    // DEBUG
    (window as any).__room = this.room;
  };

  disconnect() {
    if (this.room) {
      this.room.disconnect();
      this.room = null;
    }
  }

  getRoom(): Room | null {
    return this.room;
  }

  getLocalParticipant(): LocalParticipant | null {
    return this.room?.localParticipant || null;
  }

  getRemoteParticipants(): RemoteParticipant[] {
    return this.room ? Array.from(this.room.remoteParticipants.values()) : [];
  }
}

export const livekitService = new LiveKitService();
