import { createSlice, type PayloadAction } from "@reduxjs/toolkit";

export const initialState: Configuration = {
  devMode: false,
  noSsePatch: false,
  language: "en-us",
  snippetSettings: { shouldMinimizeWindowOnNewTab: false },
  capabilitiesVersion: "254",
  name: "",
  deploymentType: "Web",
  hostUrl: "",
  siteUrl: "",
  site: "",
  attachments: {
    endUserToAgent: false,
    maxFileSize: 0,
  },
  htmlDirection: "LTR",
  termsAndConditions: {
    isTermsAndConditionsEnabled: false,
  },
  transcript: {
    allowTranscriptDownload: false,
  },
  fallbackMessage: {
    isFallbackMessageEnabled: false,
  },
  scrt2URL: "",
  orgId: "",
  isExistingSessionOnPageLoad: false,
  customLabels: [],
  standardLabels: [],
  allowVoiceMode: true,
};

export const configurationSlice = createSlice({
  name: "configuration",
  initialState,
  reducers: {
    updateConfiguration: (
      state,
      configurationAction: PayloadAction<Partial<Configuration>>
    ) => {
      const configuration =
        configurationAction.payload as Partial<Configuration>;
      Object.entries(configuration).forEach(([key, value]) => {
        (state as any)[key] = value;
      });
    },
  },
  selectors: {
    selectSlice: (state) => state,
    getLabel: (state, labelName: string, defaultValue?: string) => {
      const labels = [
        ...(state.standardLabels ?? []),
        ...(state.customLabels ?? []),
      ];
      return (
        labels
          .filter(
            (label: Label) =>
              label.labelName.toLowerCase() === labelName.toLowerCase()
          )
          .pop()?.labelValue ?? defaultValue
      );
    },
    getAllowVoiceMode: (state) => state.allowVoiceMode,
  },
});

export const { updateConfiguration } = configurationSlice.actions;
export const { selectSlice, getLabel, getAllowVoiceMode } =
  configurationSlice.selectors;

export default configurationSlice.reducer;
