import { v4 } from "uuid";
import { LIVEKIT_CONFIG } from "../../config/livekit";
import {
  getAgentApiConfiguration,
  isAgentApiConfigurationAvailable,
} from "../../connectors";
import { createAgentApi } from "./agentApi";

declare const __LIVEKIT_USE_DIRECTLY__: boolean;

const getConvertedMessageType = (
  messageType: AgentApiMessage["type"]
): string => {
  switch (messageType) {
    case "Inform":
      return "text";
    case "SessionEnded":
      return "system";
  }
  return "text";
};

const decoder = new TextDecoder();
/**
 * Convert the decoded stream result to an array of JSON objects
 * @param value - The decoded stream result
 * @returns An array of JSON objects
 */
const convertDecodedStreamResult = (
  value: string
): { originEventId: string; message: AgentApiStreamingMessage }[] => {
  return value
    .split("\n\n") // Split by double newlines to separate events
    .filter((chunk: string) => chunk.trim()) // Remove empty chunks
    .map((chunk: string) => {
      const match = chunk.match(/^data: (.+)$/m);
      if (!match) {
        return [];
      }
      try {
        return JSON.parse(match[1]);
      } catch (e) {
        console.error("Failed to parse JSON:", e);
        return [];
      }
    });
};

// Add type definition for initialization values
interface AgentConversationAdapterInitValues {
  currentConversationId?: string;
  sessionId?: string;
  getData: () => Record<string, unknown>;
  setData: (data: Record<string, unknown>) => void;
}

export const agentConversationAdapterFactory: AdapterFactory<
  AgentConversationAdapter
> = (
  _getAdapters: GetAdaptersFn,
  listener: AdapterListener,
  initValues: AgentConversationAdapterInitValues
) => {
  const ref: {
    adapter: AgentConversationAdapter | undefined;
    getData: () => Record<string, unknown>;
    currentData: Record<string, unknown>;
  } = {
    adapter: undefined,
    getData: initValues.getData,
    currentData: initValues.getData(),
  };

  const setData = (data: Record<string, unknown>) => {
    // First use externally provided setData function
    initValues.setData(data);

    // Also notify listeners directly, merging with our local reference
    const newData = {
      ...ref.currentData,
      ...data,
    };
    ref.currentData = newData; // Update our local reference

    listener?.onAdapterEvent({
      eventName: "setData",
      eventData: newData,
      adapter: ref.adapter!,
    });
  };

  const getApi = (() => {
    if (!isAgentApiConfigurationAvailable()) {
      throw new Error("Agent API configuration is not available");
    }
    const apiConfiguration = getAgentApiConfiguration()!;
    const api = createAgentApi({
      endpoint:
        "https://api.salesforce.com/einstein/ai-agent/v1/agents/{0}/sessions",
      ...apiConfiguration,
      currentSessionId:
        initValues.sessionId || initValues.currentConversationId,
      getData: ref.getData,
      setData,
    });

    return async () => api;
  })();

  // NOTE: For Agent API, the sessionId is probably going to be maintained in this adapter
  //       That means the configuration adapter can instead call over here to get the sessionId
  let currentSessionId: string | undefined = initValues.currentConversationId;
  // const getSessionId = () => {
  //   if (!currentSessionId) {
  //     throw new Error("No session is currently active");
  //   }
  //   return currentSessionId;
  // };

  // TODO listen for events from API

  ref.adapter = {
    adapterType: "conversation",
    adapterFeatures: ["voice"],
    get sessionId() {
      return currentSessionId;
    },
    set sessionId(value) {
      currentSessionId = value;
      getApi().then((api) => {
        api.setSessionId(value);
      });
    },
    startConversation: async () => {
      const api = await getApi();
      const sessionStarted = await api.startSession();
      currentSessionId = sessionStarted.sessionId;

      // If we received data with the session, use it
      if (sessionStarted.data) {
        // This will properly associate the data with the new session
        setData(sessionStarted.data);
      }

      listener.onAdapterEvent({
        eventName: "startConversation",
        eventData: {
          sessionId: currentSessionId,
          data: sessionStarted.data,
        },
        adapter: ref.adapter!,
      });
      const isDirectToVoice = ref.getData().directToVoice === true;
      // suppress initial conversation messages if directToVoice is true
      if (sessionStarted.messages?.length && !isDirectToVoice) {
        sessionStarted.messages.forEach((message) => {
          listener.onAdapterEvent({
            eventName: "receivedMessage",
            eventData: {
              ...message,
              sender: "system",
              timestamp: +new Date(),
              type: getConvertedMessageType(message.type),
            },
            adapter: ref.adapter!,
          });
        });
      }
      return currentSessionId;
    },
    startVoiceConversation: async () => {
      setData({ directToVoice: true });
      return await ref.adapter!.startConversation();
    },
    endConversation: async () => {
      const api = await getApi();
      // const sessionId = getSessionId();
      const { messages } = await api.endSession();
      if (messages?.length) {
        messages.forEach((message) => {
          listener.onAdapterEvent({
            eventName: "receivedMessage",
            eventData: {
              ...message,
              ...(message.type === "SessionEnded" && {
                type: "system",
                message: message.message || "Conversation has ended",
                timestamp: +new Date(),
                id: message.id || v4(),
              }),
            },
            adapter: ref.adapter!,
          });
        });
      }
      listener.onAdapterEvent({
        eventName: "endConversation",
        eventData: {
          sessionId: currentSessionId,
        },
        adapter: ref.adapter!,
      });
      listener.onAdapterEvent({
        eventName: "sessionTerminated",
        eventData: {
          sessionId: currentSessionId,
        },
        adapter: ref.adapter!,
      });
      currentSessionId = undefined;
      // TODO finish
    },
    sendStreamingMessage: async (messageText: string) => {
      const api = await getApi();

      const messageStream = await api.sendMessageStream(
        // sessionId,
        messageText
        // messageId,
        // replyingToMessage ?? "",
        // false
      );
      if (messageStream) {
        const reader = messageStream.getReader();
        while (true) {
          const { done, value } = await reader.read();
          if (done) {
            break;
          }
          convertDecodedStreamResult(
            decoder.decode(value, { stream: true })
          )?.forEach((data) => {
            switch (data?.message?.type) {
              case "ProgressIndicator": {
                listener.onAdapterEvent({
                  eventName: "receivedProgressIndicator",
                  eventData: {
                    ...data.message,
                    sender: "system",
                    timestamp: +new Date(),
                    type: getConvertedMessageType(data.message.type),
                  },
                  adapter: ref.adapter!,
                });
                break;
              }
              // When receive a ValidationFailureChunk,
              // remove all previously rendered chunks and display only the new subsequent streamed content.
              case "ValidationFailureChunk": {
                listener.onAdapterEvent({
                  eventName: "removeMessage",
                  eventData: {
                    ...data.message,
                    id: data.originEventId,
                    sender: "system",
                    timestamp: +new Date(),
                    type: getConvertedMessageType(data.message.type),
                  },
                  adapter: ref.adapter!,
                });
                break;
              }
              case "TextChunk": {
                listener.onAdapterEvent({
                  eventName: "upsertStreamingMessage",
                  eventData: {
                    ...data.message,
                    id: data.originEventId,
                    offset: data.message.offset,
                    sender: "system",
                    timestamp: +new Date(),
                    type: getConvertedMessageType(data.message.type),
                  },
                  adapter: ref.adapter!,
                });
                break;
              }
              case "Inform": {
                // Inform is the last & final message from this stream before EndOfTurn
                listener.onAdapterEvent({
                  eventName: "updateMessage",
                  eventData: {
                    ...data.message,
                    id: data.originEventId,
                    type: getConvertedMessageType(data.message.type),
                    timestamp: +new Date(),
                    sender: "system",
                  },
                  adapter: ref.adapter!,
                });
                break;
              }
              case "SessionEnded": {
                listener.onAdapterEvent({
                  eventName: "receivedMessage",
                  eventData: {
                    ...data.message,
                    id: data.message.id,
                    message: data.message.message || "Conversation has ended",
                    type: getConvertedMessageType(data.message.type),
                    timestamp: +new Date(),
                    direction: "incoming",
                  },
                  adapter: ref.adapter!,
                });

                listener.onAdapterEvent({
                  eventName: "endConversation",
                  eventData: {
                    sessionId: currentSessionId,
                  },
                  adapter: ref.adapter!,
                });

                listener.onAdapterEvent({
                  eventName: "sessionTerminated",
                  eventData: {
                    sessionId: currentSessionId,
                  },
                  adapter: ref.adapter!,
                });
                break;
              }
              case "EndOfTurn": {
                listener.onAdapterEvent({
                  eventName: "finishStreamingMessage",
                  eventData: {},
                  adapter: ref.adapter!,
                });
                break;
              }
            }
          });
        }
      }
    },
    sendSynchronousMessage: async (messageText: string) => {
      const api = await getApi();
      const messageResult = await api.sendMessage(
        // sessionId,
        messageText
        // messageId,
        // replyingToMessage ?? "",
        // false
      );
      messageResult?.forEach((message) => {
        listener.onAdapterEvent({
          eventName: "receivedMessage",
          eventData: {
            ...message,
            sender: "system",
            timestamp: new Date().toISOString(),
            type: getConvertedMessageType(message.type),
          },
          adapter: ref.adapter!,
        });
      });
    },
    sendMessage: async (
      _messageId: string,
      messageText: string,
      _replyingToMessage?: string
    ) => {
      // const sessionId = getSessionId(); // TODO handle new conversations
      const tempMessageId = v4();
      const eventData = {
        id: tempMessageId,
        message: messageText,
        type: "text",
        timestamp: +new Date(),
        sender: "user",
        status: "sent",
      };
      listener.onAdapterEvent({
        eventName: "sendMessage",
        eventData,
        adapter: ref.adapter!,
      });
      if (getAgentApiConfiguration()!.enableStreaming !== false) {
        ref.adapter!.sendStreamingMessage(messageText);
      } else {
        ref.adapter!.sendSynchronousMessage(messageText);
      }
      listener.onAdapterEvent({
        eventName: "updateMessage",
        eventData: {
          ...eventData,
          status: "delivered",
        },
        adapter: ref.adapter!,
      });
    },
    stopMessage: async () => {
      if (!getAgentApiConfiguration()!.enableStopMessage) {
        throw new Error("Stop message response is not enabled");
      }
      const api = await getApi();
      await api.stopMessage();
      listener.onAdapterEvent({
        eventName: "updateMessage",
        eventData: {
          status: "canceled",
        },
        adapter: ref.adapter!,
      });
    },
    setIsTyping: async (_isTyping: boolean) => {
      // not supported by Agent API
      // do nothing
    },
    getAgentApi: getApi,
    joinVoice: async () => {
      if (__LIVEKIT_USE_DIRECTLY__) {
        // bypasses the Agent API; only works in the dev server
        return {
          url: LIVEKIT_CONFIG.url,
          token: (await LIVEKIT_CONFIG.getToken())!,
          roomName: LIVEKIT_CONFIG.roomName,
        };
      }

      // Check if livekitConfig is already in data
      const data = ref.getData();
      if (data.livekitConfig) {
        return Promise.resolve(
          data.livekitConfig as ReturnType<
            ConversationWithVoiceAdapter["joinVoice"]
          >
        );
      }

      const isDirectToVoice = data.directToVoice === true;

      // If not, get it from the API and store it in data
      return (await getApi()).joinVoice(!isDirectToVoice).then((config) => {
        if (!config?.livekitConfig || config.error) return undefined;

        const livekitConfig = {
          url: config.livekitConfig.room.endpoint,
          token: config.livekitConfig.room.token,
          roomName: config.livekitConfig.room.name,
        };

        setData({ livekitConfig, isDirectToVoice: undefined });

        return livekitConfig;
      });
    },
    destroy: async () => {
      // TODO remove listeners
    },
  };

  return ref.adapter;
};
