/**
 * Utility functions for Surface Actions
 */
export const SURFACE_ACTION_TYPES = {
  CHOICES: "Choices",
  RICH_LINK: "RichLink",
};

interface RichLinkData {
  imageUrl: string;
  title: string;
  linkUrl: string;
  valid: boolean;
}

/**
 * Validates any surface action data based on its format type
 * @param value The surface action value to validate
 * @returns true if valid, false otherwise
 */
export const validateSurfaceAction = (value: string): boolean => {
  try {
    // Parse the surface action value
    const data = JSON.parse(value);

    // Check format type and validate accordingly
    if (data.staticContent?.formatType === "RichLink") {
      return !!parseRichLinkData(value);
    }

    // Check format type and validate accordingly
    if (data.messageType === "ChoicesMessage") {
      return !!parseChoicesMessageData(value);
    }

    // Add validation for other surface action types here
    // if (data.staticContent?.formatType === "OtherType") { ... }

    // If we don't recognize the format type, it's invalid
    console.error(
      "Unknown surface action format type:",
      data.staticContent?.formatType
    );
    return false;
  } catch (e) {
    console.error("Failed to parse surface action JSON:", e);
    return false;
  }
};

/**
 * Parse and validate rich link data from a message payload
 * @param message The message payload to parse
 * @returns Parsed rich link data or null if invalid
 */
export const parseRichLinkData = (
  message: string
): RichLinkData | undefined => {
  try {
    const data = JSON.parse(message);

    if (data.messageType === "StaticContentMessage" && data.staticContent) {
      const staticContent = data.staticContent;
      if (staticContent.formatType === "RichLink") {
        // Validate required objects
        if (!staticContent.image || !staticContent.linkItem?.titleItem) {
          console.error("RichLink missing required fields:", staticContent);
          return undefined;
        }

        const imageUrl = staticContent.image.assetUrl;
        const title = staticContent.linkItem.titleItem.title;
        const linkUrl = staticContent.linkItem.url;

        const valid = !(!imageUrl || !title || !linkUrl);
        if (!valid) {
          console.error("RichLink has empty required fields:", {
            imageUrl,
            title,
            linkUrl,
          });
        }
        return {
          imageUrl,
          title,
          linkUrl,
          valid,
        };
      }
    }

    console.error(
      "Message payload doesn't match any expected RichLink format:",
      data
    );
  } catch (e) {
    // Fallback for invalid JSON
    console.error("Failed to parse rich link JSON:", e);
  }
};

/**
 * Parse and validate rich link data from a message payload
 * @param message The message payload to parse
 * @returns Parsed rich link data or null if invalid
 */
export const parseChoicesMessageData = (message: string): any => {
  try {
    const data = JSON.parse(message);

    // Handle direct ChoicesMessage format
    if (
      data.messageType === "ChoicesMessage" &&
      data.choices?.formatType === "Buttons"
    ) {
      return data.choices;
    }

    // Handle StaticContentMessage format
    if (
      data.messageType === "StaticContentMessage" &&
      data.staticContent?.formatType === "ChoicesMessage" &&
      data.staticContent?.choices?.formatType === "Buttons"
    ) {
      return data.staticContent.choices;
    }

    console.error(
      "Message payload doesn't match any expected ChoicesMessage format:",
      data
    );
  } catch (e) {
    // Fallback for invalid JSON
    console.error("Failed to parse choices message JSON:", e);
  }
  return {};
};
