type Body = any;
type SomeFetchOptions = Omit<RequestInit, "body"> &
  Pick<RequestInit, "headers"> & { body?: Body | null; signal?: AbortSignal };
type SomeGetOptions = Omit<SomeFetchOptions, "body">;

export const doFetch = async (
  url: string,
  method: "GET" | "POST" | "DELETE",
  options?: SomeFetchOptions
) => {
  const { body, headers, signal } = options ?? {};
  return fetch(url, {
    method,
    ...(body && { body: JSON.stringify(body) }),
    ...(headers && { headers }),
    ...(signal && { signal }),
  });
};

export const doGet = async (url: string, options?: SomeGetOptions) => {
  return doFetch(url, "GET", options);
};

export const doPost = async (
  url: string,
  body: Body,
  options?: Omit<SomeFetchOptions, "body">
) => {
  const headers = new Headers(options?.headers);
  if (!headers.has("content-type")) {
    headers.append("content-type", "application/json");
  }
  return doFetch(url, "POST", {
    ...options,
    headers,
    body,
  });
};

export const doDelete = async (
  url: string,
  body?: Body,
  options?: Omit<SomeFetchOptions, "body">
) => {
  return doFetch(url, "DELETE", {
    ...options,
    body,
  });
};
