import { agentAdapterDefinition } from "../../adapters/agent";
import { store } from "../../store";
import {
  addConversationEntry,
  ConversationStatus,
  finishStreamingMessage,
  finishSynchronousMessage,
  removeConversationEntry,
  sessionTerminated,
  setAgentIsTyping,
  setConversationData,
  setConversationStatus,
  setCurrentConversationId,
  setPlanId,
  setProgressIndicator,
  updateConversationEntry,
  upsertConversationEntryStreamingMessage,
} from "../../store/slices";
import { validateSurfaceAction } from "../../utils";
import { SURFACE_ACTION_TYPES } from "../../utils/surfaceActions";

interface CreateAgentAdapterListenerProps {
  getAgentAdapter: () => Adapters | undefined;
  getAdapterDefinition: () => AdapterDefinition | undefined;
}
export const createAgentAdapterListener = ({
  getAgentAdapter,
  getAdapterDefinition,
}: CreateAgentAdapterListenerProps): AdapterListener => {
  return {
    onAdapterCreated: (adapter: Adapter) =>
      console.debug(`Adapter ${adapter.adapterType} created`, adapter),
    onAdapterDestroyed: (adapter: Adapter) =>
      console.debug(`Adapter ${adapter.adapterType} destroyed`, adapter),
    onAdapterEvent: (event: AdapterEvent) => {
      console.debug(
        `Received adapter ${event.adapter.adapterType} event ${event.eventName}`,
        event
      );

      const adapter = getAgentAdapter();
      if (!adapter) return;

      const adapterDefinition = getAdapterDefinition();
      if (
        !adapterDefinition ||
        adapterDefinition.name !== agentAdapterDefinition.name
      )
        return;

      // TODO move this async functionality into adapter initialization so all listeners get it
      //   setImmediate(() => {
      switch (event.eventName) {
        case "startConversation": {
          const sessionData = event.eventData as AgentAdapterSessionStarted;

          store.dispatch(setCurrentConversationId(sessionData.sessionId));
          store.dispatch(setConversationStatus(ConversationStatus.InProgress));

          // If data is available, set it in the store
          if (sessionData.data) {
            store.dispatch(
              setConversationData({
                data: sessionData.data,
              })
            );
          }
          break;
        }
        case "sendMessage":
        case "receivedMessage": {
          const message = event.eventData as AgentApiMessage;
          const convertedMessage = convertMessage(message);
          if (convertedMessage) {
            store.dispatch(addConversationEntry(convertedMessage));
          } else {
            console.error("Invalid message received, skipping:", message);
          }
          if (event.eventName === "receivedMessage") {
            store.dispatch(finishSynchronousMessage());
          }
          break;
        }
        case "updateMessage": {
          const message = event.eventData as AgentApiMessage & {
            oldMessageId?: string;
            planId?: string;
          };
          const convertedMessage = convertMessage(message);
          if (convertedMessage) {
            store.dispatch(
              updateConversationEntry({
                ...convertedMessage,
                ...(message.oldMessageId && {
                  oldId: message.oldMessageId,
                }),
              })
            );
          } else {
            console.error(
              "Invalid update message received, skipping:",
              message
            );
          }

          if (message.planId !== undefined) {
            store.dispatch(setPlanId({ planId: message.planId }));
          }
          break;
        }
        case "removeMessage": {
          const message = event.eventData as AgentApiMessage;
          const convertedMessage = convertMessage(message);
          if (convertedMessage) {
            store.dispatch(removeConversationEntry(convertedMessage));
            store.dispatch(setAgentIsTyping(false));
          } else {
            console.error(
              "Invalid remove message received, skipping:",
              message
            );
          }
          break;
        }
        case "receivedProgressIndicator": {
          const progressData =
            event.eventData as AgentApiProgressIndicatorMessage;
          store.dispatch(setProgressIndicator(progressData));
          break;
        }
        case "upsertStreamingMessage": {
          const message = event.eventData as AgentApiStreamingMessage;
          const convertedMessage = convertMessage(message);
          if (convertedMessage) {
            // Agent is typing
            store.dispatch(setAgentIsTyping(true));
            // Handle streaming text chunks
            store.dispatch(
              upsertConversationEntryStreamingMessage({
                ...convertedMessage,
                offset: message.offset,
              })
            );
          } else {
            console.error(
              "Invalid streaming message received, skipping:",
              message
            );
          }
          break;
        }
        case "finishStreamingMessage": {
          // Agent is done typing
          store.dispatch(setAgentIsTyping(false));
          store.dispatch(finishStreamingMessage());
          break;
        }
        case "endConversation":
          store.dispatch(setConversationStatus(ConversationStatus.Ended));
          break;
        case "sessionTerminated":
          store.dispatch(sessionTerminated());
          break;
        case "setData": {
          const data = event.eventData ?? ({} as Record<string, unknown>);
          store.dispatch(setConversationData({ data }));
          break;
        }
      }
      //   });
    },
  };
};

export const getConvertedMessageType = (
  message: AgentApiMessage
): Message["type"] => {
  if (
    message.result?.some(
      (item) =>
        item.type.match(SURFACE_ACTION_TYPES.RICH_LINK) ||
        item.type.match(SURFACE_ACTION_TYPES.CHOICES)
    )
  ) {
    return "surfaceaction";
  }

  // Default message type handling
  switch (message.type) {
    case "text":
    case "system":
      return message.type;
    case "form":
      return "text";
    default:
      return "text";
  }
};

// Function to validate message before conversion
const isValidMessage = (message: AgentApiMessage): boolean => {
  // Validate surface action content if present
  const messageType = getConvertedMessageType(message);
  if (messageType === "surfaceaction" && message.result?.length) {
    try {
      const resultItem = message.result[0]; // Assume only one surface action per message
      if (resultItem.value) {
        // Validate surface action
        if (!validateSurfaceAction(resultItem.value)) {
          console.error("Invalid surface action content:", resultItem.value);
          return false;
        }
      }
    } catch (e) {
      console.error("Error processing surface action message:", e);
      return false;
    }
  }

  return true;
};

export const convertMessage = (
  message: AgentApiMessage
): Message | undefined => {
  // Validate message first
  if (!isValidMessage(message)) {
    return undefined;
  }

  const messageType = getConvertedMessageType(message);

  const messageContent =
    messageType === "surfaceaction" ? JSON.stringify(message) : message.message;

  return {
    id: message.id,
    message: messageContent,
    sentTime: new Date(message.timestamp || 0).toISOString(),
    sender: message.sender === "system" ? "assistant" : message.sender,
    direction: message.sender === "user" ? "outgoing" : "incoming",
    position: "single",
    type: messageType,
  };
};
