import React, { CSSProperties, useCallback, useEffect, useRef } from "react";
import { useAudioContext } from "../hooks/useAudioContext";
import { useVoice } from "../providers/VoiceProvider";
import { AudioVisualizerProps } from "../types";

// Styled Components
interface ContainerProps {
  backgroundColor: string;
  children?: React.ReactNode;
}

const canvasStyle = {
  width: "100%",
  height: "100%",
};

const containerStyle: CSSProperties = {
  position: "relative",
  width: "100%",
  height: "100%",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
};

const Container: React.FC<ContainerProps> = ({ children, backgroundColor }) => (
  <div style={{ ...containerStyle, backgroundColor }}>{children}</div>
);

const Canvas = React.forwardRef<HTMLCanvasElement>((props, ref) => (
  <canvas {...props} ref={ref} style={canvasStyle} />
));

export const FrequencyVisualizer: React.FC<AudioVisualizerProps> = ({
  useMicrophone,
  width = 800,
  height = 200,
  backgroundColor = "transparent",
  gradientColors = ["#00bcd4", "#4CAF50", "#8BC34A"],
  smoothingTimeConstant = 0.8,
  fftSize = 2048,
  minDecibels = -120,
  maxDecibels = -10,
  minHeight = 10,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameId = useRef<number | null>(null);
  const gradientRef = useRef<CanvasGradient | null>(null);
  const { isOtherVoiceMode } = useVoice();

  const audioState = useAudioContext(
    useMicrophone,
    fftSize,
    smoothingTimeConstant,
    minDecibels,
    maxDecibels,
    isOtherVoiceMode
  );

  const BAR_COUNT = 3;
  const BAR_WIDTH = 20;

  const draw = useCallback(() => {
    const BAR_SPACING = width / 4;
    const START_X = BAR_SPACING / 2;
    const CENTER_Y = height / 2;

    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!canvas || !ctx || !audioState.analyser || !audioState.dataArray)
      return;

    const bufferLength = audioState.analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    audioState.analyser.getByteFrequencyData(dataArray);

    ctx.clearRect(0, 0, width, height);

    // Create gradient only once, with safety checks
    if (!gradientRef.current && gradientColors.length >= 2) {
      gradientRef.current = ctx.createLinearGradient(0, height, 0, 0);
      const stopIncrement = 1 / (gradientColors.length - 1);

      gradientColors.forEach((color, index) => {
        const stop = index * stopIncrement;
        if (Number.isFinite(stop)) {
          gradientRef.current?.addColorStop(stop, color);
        }
      });
    }

    // Fallback to first color if gradient creation failed
    ctx.fillStyle = gradientRef.current || gradientColors[0];

    for (let i = 0; i < BAR_COUNT; i++) {
      const frequencyIndex = Math.floor(
        bufferLength / 4 + (i * bufferLength) / 8
      );
      const amplifiedValue = Math.min(dataArray[frequencyIndex] * 2.5, 255);
      const maxHeight = i === 1 ? height / 2 : (height / 2) * 0.75;
      const barHeight = Math.max(
        (amplifiedValue / 255.0) * maxHeight,
        minHeight
      );
      const x = START_X + i * BAR_SPACING;

      // Draw upper and lower bars
      const roundedCorners = [BAR_WIDTH / 2, BAR_WIDTH / 2, 0, 0];
      const bottomRoundedCorners = [0, 0, BAR_WIDTH / 2, BAR_WIDTH / 2];

      ctx.beginPath();
      ctx.roundRect(
        x,
        CENTER_Y - barHeight,
        BAR_WIDTH,
        barHeight,
        roundedCorners
      );
      ctx.fill();

      ctx.beginPath();
      ctx.roundRect(x, CENTER_Y, BAR_WIDTH, barHeight, bottomRoundedCorners);
      ctx.fill();
    }

    animationFrameId.current = requestAnimationFrame(draw);
  }, [audioState, width, height, gradientColors, minHeight]);

  useEffect(() => {
    if (canvasRef.current) {
      canvasRef.current.width = width;
      canvasRef.current.height = height;
      gradientRef.current = null; // Reset gradient when dimensions change
    }

    draw();
    return () => {
      if (animationFrameId.current) {
        cancelAnimationFrame(animationFrameId.current);
      }
    };
  }, [width, height, draw]);

  return (
    <Container backgroundColor={backgroundColor}>
      <Canvas ref={canvasRef} />
    </Container>
  );
};

interface VoiceInputVisualizerProps {
  color?: string;
}

export const VoiceInputVisualizer = ({
  color = "#ffffff",
}: VoiceInputVisualizerProps) => (
  <div className="h-10 w-10" role="status" aria-label="Voice input visualizer">
    <FrequencyVisualizer
      useMicrophone={true}
      width={100}
      height={100}
      gradientColors={[color]}
      barWidth={10}
      barSpacing={5}
      barRadius={10}
      aria-hidden="true"
    />
  </div>
);
