import { useAppState } from "../store/hooks";
import {
  chatFab as chatFabSlice,
  chatHeader as chatHeaderSlice,
  chatInput as chatInputSlice,
  chatMessage as chatMessageSlice,
  chatVoice as chatVoiceSlice,
  chatWindow as chatWindowSlice,
  layout as layoutSlice,
} from "../store/slices/ui";

export interface ConfigurationContextType {
  layout: LayoutConfigurationContextType;
  chatInput: ChatInputConfigurationContextType;
  chatHeader: ChatHeaderConfigurationContextType;
  chatFab: ChatFabConfigurationContextType;
  chatVoice: ChatVoiceConfigurationContextType;
  chatWindow: ChatWindowConfigurationContextType;
  chatMessage: ChatMessageConfigurationContextType;
}

export interface LayoutConfigurationContextType {
  mode: ChatMode;
  setMode: (value: ChatMode) => void;
}

export interface ChatMessageConfigurationContextType {
  agent: {
    backgroundColor: string;
    setBackgroundColor: (value: string) => void;
    textColor: string;
    setTextColor: (value: string) => void;
    avatarEnabled: boolean;
    setAvatarEnabled: (value: boolean) => void;
    iconUrl: string;
    setIconUrl: (value: string) => void;
  };
  user: {
    backgroundColor: string;
    setBackgroundColor: (value: string) => void;
    textColor: string;
    setTextColor: (value: string) => void;
  };
  metadata: {
    textColor: string;
    setTextColor: (value: string) => void;
  };
}

export interface ChatWindowConfigurationContextType {
  loadingText: string;
  setLoadingText: (value: string) => void;
  backgroundColor: string;
  setBackgroundColor: (value: string) => void;
}

export interface ChatInputConfigurationContextType {
  poweredByEnabled: boolean;
  setPoweredByEnabled: (value: boolean) => void;
  backgroundColor: string;
  setBackgroundColor: (value: string) => void;
  placeholder: string;
  setPlaceholder: (value: string) => void;
  textColor: string;
  setTextColor: (value: string) => void;
}

export interface ChatHeaderConfigurationContextType {
  agentName: string;
  setAgentName: (value: string) => void;
  backgroundColor: string;
  setBackgroundColor: (value: string) => void;
  textColor: string;
  setTextColor: (value: string) => void;
  iconHoverBackgroundColor: string;
  setIconHoverBackgroundColor: (value: string) => void;
  visible: boolean;
  setVisible: (value: boolean) => void;
}

export interface ChatFabConfigurationContextType {
  cta: string;
  setCta: (value: string) => void;
  iconUrl: string;
  setIconUrl: (value: string) => void;
  backgroundColor: string;
  setBackgroundColor: (value: string) => void;
  textColor: string;
  setTextColor: (value: string) => void;
}

export interface ChatVoiceConfigurationContextType {
  backgroundColor: string;
  setBackgroundColor: (value: string) => void;
  textColor: string;
  setTextColor: (value: string) => void;
  microphoneIcon: {
    textColorMuted: string;
    setTextColorMuted: (value: string) => void;
    textColorUnmuted: string;
    setTextColorUnmuted: (value: string) => void;
  };
}

export function useConfigurationContext(): ConfigurationContextType {
  const { selectMode: selectLayoutMode, setMode: setLayoutMode } = layoutSlice;

  const {
    selectPoweredByEnabled: selectChatInputPoweredByEnabled,
    selectBackgroundColor: selectChatInputBackgroundColor,
    selectPlaceholder: selectChatInputPlaceholder,
    selectTextColor: selectChatInputTextColor,
    setPoweredByEnabled: setChatInputPoweredByEnabledAction,
    setBackgroundColor: setChatInputBackgroundColorAction,
    setPlaceholder: setChatInputPlaceholderAction,
    setTextColor: setChatInputTextColorAction,
  } = chatInputSlice;

  const {
    selectAgentName: selectChatHeaderAgentName,
    setAgentName: setChatHeaderAgentNameAction,
    selectBackgroundColor: selectChatHeaderBackgroundColor,
    setBackgroundColor: setChatHeaderBackgroundColorAction,
    selectTextColor: selectChatHeaderTextColor,
    setTextColor: setChatHeaderTextColorAction,
    selectIconHoverBackgroundColor: selectChatHeaderIconHoverBackgroundColor,
    setIconHoverBackgroundColor: setChatHeaderIconHoverBackgroundColorAction,
    selectVisible: selectChatHeaderVisible,
    setVisible: setChatHeaderVisibleAction,
  } = chatHeaderSlice;

  const {
    selectCta: selectChatFabCta,
    setCta: setChatFabCtaAction,
    selectIconUrl: selectChatFabIconUrl,
    setIconUrl: setChatFabIconUrlAction,
    selectTextColor: selectChatFabTextColor,
    setTextColor: setChatFabTextColorAction,
    selectBackgroundColor: selectChatFabBackgroundColor,
    setBackgroundColor: setChatFabBackgroundColorAction,
  } = chatFabSlice;

  const {
    selectBackgroundColor: selectChatVoiceBackgroundColor,
    setBackgroundColor: setChatVoiceBackgroundColorAction,
    selectTextColor: selectChatVoiceTextColor,
    setTextColor: setChatVoiceTextColorAction,
    microphoneIcon: {
      selectTextColorMuted: selectChatVoiceMicrophoneTextColorMuted,
      setTextColorMuted: setChatVoiceMicrophoneTextColorMutedAction,
      selectTextColorUnmuted: selectChatVoiceMicrophoneTextColorUnmuted,
      setTextColorUnmuted: setChatVoiceMicrophoneTextColorUnmutedAction,
    },
  } = chatVoiceSlice;

  const {
    selectLoadingText: selectChatWindowLoadingText,
    setLoadingText: setChatWindowLoadingTextAction,
    selectBackgroundColor: selectChatWindowBackgroundColor,
    setBackgroundColor: setChatWindowBackgroundColorAction,
  } = chatWindowSlice;

  const {
    agent: {
      selectBackgroundColor: selectChatMessageAgentBackgroundColor,
      setBackgroundColor: setChatMessageAgentBackgroundColorAction,
      selectTextColor: selectChatMessageAgentTextColor,
      setTextColor: setChatMessageAgentTextColorAction,
      selectAvatarEnabled: selectChatMessageAgentAvatarEnabled,
      setAvatarEnabled: setChatMessageAgentAvatarEnabledAction,
      selectIconUrl: selectChatMessageAgentIconUrl,
      setIconUrl: setChatMessageAgentIconUrlAction,
    },
    user: {
      selectBackgroundColor: selectChatMessageUserBackgroundColor,
      setBackgroundColor: setChatMessageUserBackgroundColorAction,
      selectTextColor: selectChatMessageUserTextColor,
      setTextColor: setChatMessageUserTextColorAction,
    },
    metadata: {
      selectTextColor: selectChatMessageMetadataTextColor,
      setTextColor: setChatMessageMetadataTextColorAction,
    },
  } = chatMessageSlice;

  const [chatInputPoweredByEnabled, setChatInputPoweredByEnabled] = useAppState(
    selectChatInputPoweredByEnabled,
    setChatInputPoweredByEnabledAction
  );

  const [chatInputBackgroundColor, setChatInputBackgroundColor] = useAppState(
    selectChatInputBackgroundColor,
    setChatInputBackgroundColorAction
  );

  const [chatInputPlaceholder, setChatInputPlaceholder] = useAppState(
    selectChatInputPlaceholder,
    setChatInputPlaceholderAction
  );

  const [chatInputTextColor, setChatInputTextColor] = useAppState(
    selectChatInputTextColor,
    setChatInputTextColorAction
  );

  const [chatHeaderAgentName, setChatHeaderAgentName] = useAppState(
    selectChatHeaderAgentName,
    setChatHeaderAgentNameAction
  );

  const [chatHeaderBackgroundColor, setChatHeaderBackgroundColor] = useAppState(
    selectChatHeaderBackgroundColor,
    setChatHeaderBackgroundColorAction
  );

  const [chatHeaderTextColor, setChatHeaderTextColor] = useAppState(
    selectChatHeaderTextColor,
    setChatHeaderTextColorAction
  );

  const [
    chatHeaderIconHoverBackgroundColor,
    setChatHeaderIconHoverBackgroundColor,
  ] = useAppState(
    selectChatHeaderIconHoverBackgroundColor,
    setChatHeaderIconHoverBackgroundColorAction
  );

  const [chatHeaderVisible, setChatHeaderVisible] = useAppState(
    selectChatHeaderVisible,
    setChatHeaderVisibleAction
  );

  const [chatFabCta, setChatFabCta] = useAppState(
    selectChatFabCta,
    setChatFabCtaAction
  );

  const [chatFabIconUrl, setChatFabIconUrl] = useAppState(
    selectChatFabIconUrl,
    setChatFabIconUrlAction
  );

  const [chatFabTextColor, setChatFabTextColor] = useAppState(
    selectChatFabTextColor,
    setChatFabTextColorAction
  );

  const [chatFabBackgroundColor, setChatFabBackgroundColor] = useAppState(
    selectChatFabBackgroundColor,
    setChatFabBackgroundColorAction
  );

  const [chatVoiceBackgroundColor, setChatVoiceBackgroundColor] = useAppState(
    selectChatVoiceBackgroundColor,
    setChatVoiceBackgroundColorAction
  );

  const [chatVoiceTextColor, setChatVoiceTextColor] = useAppState(
    selectChatVoiceTextColor,
    setChatVoiceTextColorAction
  );

  const [
    chatVoiceMicrophoneTextColorMuted,
    setChatVoiceMicrophoneTextColorMuted,
  ] = useAppState(
    selectChatVoiceMicrophoneTextColorMuted,
    setChatVoiceMicrophoneTextColorMutedAction
  );

  const [
    chatVoiceMicrophoneTextColorUnmuted,
    setChatVoiceMicrophoneTextColorUnmuted,
  ] = useAppState(
    selectChatVoiceMicrophoneTextColorUnmuted,
    setChatVoiceMicrophoneTextColorUnmutedAction
  );

  const [chatWindowLoadingText, setChatWindowLoadingText] = useAppState(
    selectChatWindowLoadingText,
    setChatWindowLoadingTextAction
  );

  const [chatWindowBackgroundColor, setChatWindowBackgroundColor] = useAppState(
    selectChatWindowBackgroundColor,
    setChatWindowBackgroundColorAction
  );

  const [chatMessageAgentBackgroundColor, setChatMessageAgentBackgroundColor] =
    useAppState(
      selectChatMessageAgentBackgroundColor,
      setChatMessageAgentBackgroundColorAction
    );

  const [chatMessageUserBackgroundColor, setChatMessageUserBackgroundColor] =
    useAppState(
      selectChatMessageUserBackgroundColor,
      setChatMessageUserBackgroundColorAction
    );

  const [chatMessageAgentTextColor, setChatMessageAgentTextColor] = useAppState(
    selectChatMessageAgentTextColor,
    setChatMessageAgentTextColorAction
  );

  const [chatMessageAgentAvatarEnabled, setChatMessageAgentAvatarEnabled] =
    useAppState(
      selectChatMessageAgentAvatarEnabled,
      setChatMessageAgentAvatarEnabledAction
    );

  const [chatMessageUserTextColor, setChatMessageUserTextColor] = useAppState(
    selectChatMessageUserTextColor,
    setChatMessageUserTextColorAction
  );

  const [chatMessageMetadataTextColor, setChatMessageMetadataTextColor] =
    useAppState(
      selectChatMessageMetadataTextColor,
      setChatMessageMetadataTextColorAction
    );

  const [chatMessageAgentIconUrl, setChatMessageAgentIconUrl] = useAppState(
    selectChatMessageAgentIconUrl,
    setChatMessageAgentIconUrlAction
  );

  const [layoutMode, setLayoutModeValue] = useAppState(
    selectLayoutMode,
    setLayoutMode
  );

  const layout = {
    mode: layoutMode,
    setMode: setLayoutModeValue,
  };

  const chatInput = {
    poweredByEnabled: chatInputPoweredByEnabled,
    setPoweredByEnabled: setChatInputPoweredByEnabled,
    backgroundColor: chatInputBackgroundColor,
    setBackgroundColor: setChatInputBackgroundColor,
    placeholder: chatInputPlaceholder,
    setPlaceholder: setChatInputPlaceholder,
    textColor: chatInputTextColor,
    setTextColor: setChatInputTextColor,
  };

  const chatHeader = {
    agentName: chatHeaderAgentName,
    setAgentName: setChatHeaderAgentName,
    backgroundColor: chatHeaderBackgroundColor,
    setBackgroundColor: setChatHeaderBackgroundColor,
    textColor: chatHeaderTextColor,
    setTextColor: setChatHeaderTextColor,
    iconHoverBackgroundColor: chatHeaderIconHoverBackgroundColor,
    setIconHoverBackgroundColor: setChatHeaderIconHoverBackgroundColor,
    visible: chatHeaderVisible,
    setVisible: setChatHeaderVisible,
  };

  const chatFab = {
    cta: chatFabCta,
    setCta: setChatFabCta,
    iconUrl: chatFabIconUrl,
    setIconUrl: setChatFabIconUrl,
    backgroundColor: chatFabBackgroundColor,
    setBackgroundColor: setChatFabBackgroundColor,
    textColor: chatFabTextColor,
    setTextColor: setChatFabTextColor,
  };

  const chatVoice = {
    backgroundColor: chatVoiceBackgroundColor,
    setBackgroundColor: setChatVoiceBackgroundColor,
    textColor: chatVoiceTextColor,
    setTextColor: setChatVoiceTextColor,
    microphoneIcon: {
      textColorMuted: chatVoiceMicrophoneTextColorMuted,
      setTextColorMuted: setChatVoiceMicrophoneTextColorMuted,
      textColorUnmuted: chatVoiceMicrophoneTextColorUnmuted,
      setTextColorUnmuted: setChatVoiceMicrophoneTextColorUnmuted,
    },
  };

  const chatWindow = {
    loadingText: chatWindowLoadingText,
    setLoadingText: setChatWindowLoadingText,
    backgroundColor: chatWindowBackgroundColor,
    setBackgroundColor: setChatWindowBackgroundColor,
  };

  const chatMessage = {
    agent: {
      backgroundColor: chatMessageAgentBackgroundColor,
      setBackgroundColor: setChatMessageAgentBackgroundColor,
      textColor: chatMessageAgentTextColor,
      setTextColor: setChatMessageAgentTextColor,
      avatarEnabled: chatMessageAgentAvatarEnabled,
      setAvatarEnabled: setChatMessageAgentAvatarEnabled,
      iconUrl: chatMessageAgentIconUrl,
      setIconUrl: setChatMessageAgentIconUrl,
    },
    user: {
      backgroundColor: chatMessageUserBackgroundColor,
      setBackgroundColor: setChatMessageUserBackgroundColor,
      textColor: chatMessageUserTextColor,
      setTextColor: setChatMessageUserTextColor,
    },
    metadata: {
      textColor: chatMessageMetadataTextColor,
      setTextColor: setChatMessageMetadataTextColor,
    },
  };

  return {
    layout,
    chatInput,
    chatHeader,
    chatFab,
    chatVoice,
    chatWindow,
    chatMessage,
  };
}
