import type { Store, Unsubscribe } from "@reduxjs/toolkit";
import type { RootState } from "../store/slices";

export interface SubscribeToSelectorOnceOptions {
  timeout?: number;
  skipInitialCheck?: boolean;
  isValid?: <T>(value: T) => boolean;
}

export type PromiseWithUnsubscribe<T> = Promise<T> & {
  unsubscribe: Unsubscribe;
};

/**
 * Subscribe to a Redux selector and resolve when the selector returns a valid value.
 * Useful for waiting for specific state changes to occur.
 *
 * @param store - The Redux store instance
 * @param selector - The selector function to monitor
 * @param options - Configuration options
 * @param options.timeout - Timeout in milliseconds (default: 10000ms)
 * @param options.skipInitialCheck - Skip checking the current value immediately (default: false)
 * @param options.isValid - Function to determine if a value is considered valid (default: checks for non-undefined)
 * @returns Promise that resolves with the selector value when it becomes valid, with unsubscribe method attached
 */
export const subscribeToSelectorOnce = <T>(
  store: Store,
  selector: (state: RootState) => T,
  options: SubscribeToSelectorOnceOptions = {}
): PromiseWithUnsubscribe<T> => {
  const {
    timeout = 10000,
    skipInitialCheck = false,
    isValid = (value: T) => value !== undefined,
  } = options;

  let unsubscribe: Unsubscribe | undefined;

  const promise = new Promise<T>((resolve, reject) => {
    // Check if already satisfied (unless skipping initial check)
    if (!skipInitialCheck) {
      const currentValue = selector(store.getState());
      if (isValid(currentValue)) {
        resolve(currentValue);
        return;
      }
    }

    let timeoutId: NodeJS.Timeout | undefined;

    // Set up timeout
    if (timeout > 0) {
      timeoutId = setTimeout(() => {
        if (unsubscribe) unsubscribe();
        reject(new Error(`Selector subscription timed out after ${timeout}ms`));
      }, timeout);
    }

    // Subscribe to store changes
    unsubscribe = store.subscribe(() => {
      const value = selector(store.getState());
      if (isValid(value)) {
        if (timeoutId) clearTimeout(timeoutId);
        if (unsubscribe) unsubscribe();
        resolve(value);
      }
    });
  }) as PromiseWithUnsubscribe<T>;

  promise.unsubscribe = unsubscribe!;

  return promise;
};
