import { format } from "date-fns";
import { cn } from "../utils";
import {
  defaultMarkdownComponents,
  liWithoutTopLevelDecimal,
  Markdown,
} from "./ui/Markdown";

interface Props {
  message: string;
  sentTime: string;
}

const systemMessageComponents = {
  ...defaultMarkdownComponents,
  li: liWithoutTopLevelDecimal,
};

export function ChatSystemMessage({ message, sentTime }: Props) {
  const sentTimeFormatted = format(new Date(sentTime), "h:mmaaa");
  const centered = !message.includes("\n");
  return (
    <div className="flex flex-row items-end gap-2 p-4">
      <div className="flex min-w-0 flex-1 flex-col">
        <div
          className={cn("text-on-surface-1 text-xs", centered && "text-center")}
        >
          <Markdown components={systemMessageComponents}>{message}</Markdown>
          {centered ? " · " : ""}
          {sentTimeFormatted}
        </div>
      </div>
    </div>
  );
}
