import {
  createAsyncThunk,
  createEntityAdapter,
  createSelector,
  createSlice,
  type PayloadAction,
} from "@reduxjs/toolkit";
import { getCurrentAdapters, setCurrentAdapters } from "../../adapters";
import { getAgentApiConfiguration } from "../../connectors";
import { asAsyncAction } from "../middleware/asyncDispatch";
import { setAuthToken } from "./apphost";

const compareTimes = (a: string, b: string) => {
  const aDate = a ? Date.parse(a) : 0;
  const bDate = b ? Date.parse(b) : 0;

  return aDate - bDate;
};

const conversationAdapter = createEntityAdapter<Message, string>({
  selectId: (entry: Message) => entry.id,
  sortComparer: (a, b) => compareTimes(a.sentTime, b.sentTime),
});

export enum ConversationStatus {
  NotStarted = "not-started",
  InProgress = "in-progress",
  Ended = "ended",
  Error = "error",
}

interface ConversationChat {
  isVoiceMode: boolean;
  isExpanded: boolean;
  isMuted: boolean;
  voiceModeError?: string;
  microphonePermission: PermissionState;
  /**
   * This value references `apphost.instanceId` and specifies which application instance has an
   * active voice chat. It is designed to ensure only one browser tab is actively
   * listening/speaking at a time.
   */
  activeVoiceInstanceId?: string;
}

interface SingleConversationState {
  conversationId: string;
  loading: boolean;
  participants: Participant[];
  agentIsTyping: boolean;
  showProgressIndicator: boolean;
  progressIndicatorText?: string;
  status: ConversationStatus;
  chatState: ConversationChat;
  data: Record<string, any>;
  startedAt?: string;
  lastMessageAt?: Date;
  planId?: string;
}
type SingleConversationStateWithEntities = SingleConversationState &
  ReturnType<typeof conversationAdapter.getInitialState>;
export interface ConversationState {
  loading: boolean;
  isVoiceModeLoading: boolean;
  currentConversationId?: string;
  conversations: Record<string, SingleConversationStateWithEntities>;
  // adapters?: Adapters;
  isChatOpen: boolean;
}
interface InitializeConversationEntries {
  conversationId: string;
  conversationEntries: Message[];
  participants?: Participant[];
  setAsCurrentConversation?: boolean; // default behavior is `true` when `undefined`
}

interface PayloadActionMaybeSynced<P> extends PayloadAction<P> {
  synced?: boolean;
  sourceInstanceId?: string;
}

type ActionMaybeSynced = PayloadActionMaybeSynced<undefined>;

const initialState: ConversationState = {
  loading: false,
  isVoiceModeLoading: false,
  conversations: {},
  currentConversationId: "",
  isChatOpen: false,
};

const createDefaultChatState = (): ConversationChat => ({
  isVoiceMode: false,
  isExpanded: false,
  isMuted: false,
  voiceModeError: undefined,
  microphonePermission: "prompt",
});

const createConversationInitialState = (
  conversationId: string,
  conversationEntries: Message[] = [],
  participants: Participant[] = [],
  loading = false
) => {
  return conversationAdapter.getInitialState(
    {
      conversationId,
      loading,
      participants,
      agentIsTyping: false,
      status: ConversationStatus.NotStarted,
      chatState: createDefaultChatState(),
      data: {},
      startedAt: new Date().toISOString(),
    } as SingleConversationState,
    conversationEntries
  );
};

const getConversationState = (
  state: ConversationState,
  conversationId: string | undefined = state.currentConversationId
): SingleConversationStateWithEntities | undefined => {
  if (!conversationId) {
    return undefined;
  }
  const conversationState = state.conversations[conversationId];
  return conversationState;
};

type StartConversationOptions = { directToVoiceAction?: boolean } | undefined;
export const startConversation = createAsyncThunk(
  "conversation/startConversation",
  async (options: StartConversationOptions, { getState }) => {
    const { directToVoiceAction } = { directToVoiceAction: false, ...options };

    const adapters = getCurrentAdapters();
    if (!adapters) {
      throw new Error(
        "Cannot perform client actions without registered adapters"
      );
    }

    const state = getState() as { conversation: ConversationState };
    const conversationState = getConversationState(state.conversation);

    if (
      state.conversation.currentConversationId &&
      conversationState?.status === ConversationStatus.InProgress
    ) {
      throw new Error("Cannot start a conversation while one is in progress");
    }

    let sessionId: string;
    if (
      directToVoiceAction &&
      adapters.conversation.adapterFeatures?.includes("voice")
    ) {
      sessionId = await (
        adapters.conversation as ConversationWithVoiceAdapter
      ).startVoiceConversation();
    } else {
      sessionId = await adapters.conversation.startConversation();
    }
    return sessionId;
  }
);

export const conversationSlice = createSlice({
  name: "conversation",
  initialState,
  reducers: {
    registerAdapters: (
      _state,
      registerAdaptersAction: PayloadAction<Adapters>
    ) => {
      const adapters = registerAdaptersAction.payload;
      setCurrentAdapters(adapters);
    },
    setCurrentConversationId: (
      state,
      setConversationIdAction: PayloadAction<string>
    ) => {
      const conversationId = setConversationIdAction.payload;
      state.currentConversationId = conversationId;
      if (!state.conversations[conversationId]) {
        state.conversations[conversationId] =
          createConversationInitialState(conversationId);
      }

      // Setup when conversation id is set
      state.loading = false;
    },
    setConversationData: (
      state,
      action: PayloadAction<{
        conversationId?: string;
        data: Record<string, any>;
      }>
    ) => {
      const { conversationId, data } = action.payload;
      const conversationState = getConversationState(
        state,
        conversationId ?? state.currentConversationId
      );
      if (conversationState) {
        conversationState.data = {
          ...conversationState.data,
          ...data,
        };
      }
    },
    initializeConversationEntries: (
      state,
      configurationEntriesAction: PayloadAction<InitializeConversationEntries>
    ) => {
      const {
        conversationId,
        conversationEntries,
        participants,
        setAsCurrentConversation,
      } = configurationEntriesAction.payload;
      state.conversations[conversationId] = createConversationInitialState(
        conversationId,
        conversationEntries,
        participants,
        false
      );
      if (setAsCurrentConversation !== false) {
        state.currentConversationId = conversationId; // TODO switch to an action?
      }
    },
    addConversationEntry: (
      state,
      conversationEntryAction: PayloadAction<Message>
    ) => {
      const entry = conversationEntryAction.payload;
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      conversationAdapter.addOne(conversationState, entry);
      // TODO what if entry is a duplicate?
    },
    updateConversationEntry: (
      state,
      updateEntryAction: PayloadAction<Message & { oldId?: string }>
    ) => {
      const entry = updateEntryAction.payload;
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      if (!conversationState.ids.includes(entry.oldId ?? entry.id)) {
        conversationAdapter.addOne(conversationState, entry);
      } else {
        conversationAdapter.updateOne(conversationState, {
          id: entry.oldId ?? entry.id,
          changes: entry,
        });
      }
    },
    removeConversationEntry: (
      state,
      removeEntryAction: PayloadAction<Message>
    ) => {
      const entry = removeEntryAction.payload;
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      conversationAdapter.removeOne(conversationState, entry.id);
    },
    upsertConversationEntryStreamingMessage: (
      state,
      updateEntryAction: PayloadAction<
        Message & { offset: number; replace?: boolean }
      >
    ) => {
      const entry = updateEntryAction.payload;
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }

      const message = conversationState.entities[entry.id];
      if (message?.messageTokens) {
        if (entry.replace) {
          // Replace the entire tokens array with the new message
          message.messageTokens = [entry.message];
        } else if (entry.offset === undefined) {
          message.messageTokens.push(entry.message);
        } else {
          message.messageTokens.splice(entry.offset, 0, entry.message);
        }
        // Join the message tokens into a single string
        message.message = message.messageTokens.join("");
      } else {
        conversationAdapter.addOne(conversationState, {
          ...entry,
          messageTokens: [entry.message],
        });
      }
    },
    addParticipant: (state, participantAction: PayloadAction<Participant>) => {
      const { role, subject, appType, displayName } = participantAction.payload;
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      // silently do nothing if the participant already exists
      // TODO: we may need to update the display name eventually
      if (conversationState.participants.find((p) => p.subject === subject)) {
        return;
      }
      conversationState.participants.push({
        role,
        subject,
        appType,
        displayName: displayName || role,
      });
    },
    removeParticipant: (
      state,
      participantAction: PayloadAction<Participant | string>
    ) => {
      const participant = participantAction.payload;
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      let index = -1;
      if (typeof participant === "string") {
        index = conversationState.participants.findIndex(
          ({ subject }) => subject === participant
        );
      } else {
        index = conversationState.participants.indexOf(participant);
        if (index === -1) {
          // try by subject
          index = conversationState.participants.findIndex(
            ({ subject }) => subject === participant.subject
          );
        }
      }
      if (index !== -1) {
        conversationState.participants.splice(index, 1);
      }
      // TODO throw if not found?
    },
    setAgentIsTyping: (state, isTypingAction: PayloadAction<boolean>) => {
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      conversationState.agentIsTyping = isTypingAction.payload;
    },
    setProgressIndicator: (
      state,
      progressIndicatorAction: PayloadAction<ProgressIndicator>
    ) => {
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }

      conversationState.showProgressIndicator =
        !!progressIndicatorAction.payload.message;
      conversationState.progressIndicatorText =
        progressIndicatorAction.payload.message;
    },
    setConversationStatus: (state, statusAction: PayloadAction<string>) => {
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      const status = statusAction.payload;
      const actualStatus = Object.entries(ConversationStatus).find(
        ([key, value]) => [key, value].includes(status)
      );
      if (actualStatus) {
        conversationState.status = actualStatus[1];
      } else {
        throw new Error(`${status} is not a valid conversation status`);
      }
    },
    setIsChatOpen: (state, isChatOpenAction: PayloadAction<boolean>) => {
      const conversationState = getConversationState(state);
      if (conversationState) {
        conversationState.chatState.voiceModeError = undefined;
      }
      state.isChatOpen = isChatOpenAction.payload;
    },
    setConversationChatState: (
      state,
      chatStateAction: PayloadAction<Partial<ConversationChat>>
    ) => {
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      (
        Object.keys(chatStateAction.payload) as (keyof ConversationChat)[]
      ).forEach((key) => {
        const value = chatStateAction.payload[key];
        if (value === undefined) return;
        // silly TypeScript type inference...
        (conversationState.chatState[key] as unknown) = value;
      });
    },
    setActiveVoiceInstanceId: (
      state,
      action: PayloadAction<string | undefined>
    ) => {
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      conversationState.chatState.activeVoiceInstanceId = action.payload;
    },
    sendMessage: (state, action: PayloadActionMaybeSynced<Message>) => {
      const adapters = getCurrentAdapters();
      if (!adapters) {
        throw new Error(
          "Cannot perform client actions without registered adapters"
        );
      }
      getConversationState(state)!.loading = true;
      if (!action.synced) {
        adapters.conversation.sendMessage(
          action.payload.id,
          action.payload.message
        );
      }
    },
    stopMessage: (state, action: ActionMaybeSynced) => {
      const adapters = getCurrentAdapters();
      if (!adapters) {
        throw new Error(
          "Cannot perform client actions without registered adapters"
        );
      }
      if (getAgentApiConfiguration()?.enableStopMessage) {
        if (!action.synced) {
          adapters.conversation.stopMessage?.();
        }
        getConversationState(state)!.loading = false;
      }
    },
    finishSynchronousMessage: (state) => {
      getConversationState(state)!.loading = false;
    },
    finishStreamingMessage: (state) => {
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }

      conversationState!.loading = false;

      // Hide progress indicator
      if (conversationState.showProgressIndicator) {
        conversationState.showProgressIndicator = false;
        delete conversationState.progressIndicatorText;
      }
    },
    endConversation: (_state, action: ActionMaybeSynced) => {
      const adapters = getCurrentAdapters();
      if (!adapters) {
        throw new Error(
          "Cannot perform client actions without registered adapters"
        );
      }
      if (!action.synced) {
        adapters.conversation.endConversation();
      }
    },
    sessionTerminated: (state, action: ActionMaybeSynced) => {
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      conversationState.loading = false;
      conversationState.status = ConversationStatus.Ended;
      if (!action.synced) {
        asAsyncAction(action).asyncDispatch(setAuthToken(undefined));
      }
    },
    setIsMuted: (state, action: PayloadAction<boolean>) => {
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      conversationState.chatState.isMuted = action.payload;
    },
    setIsVoiceModeLoading: (state, action: PayloadAction<boolean>) => {
      state.isVoiceModeLoading = action.payload;

      if (action.payload === true) {
        const conversationState = getConversationState(state);
        if (!conversationState) {
          return;
        }
        conversationState.chatState.voiceModeError = undefined;
      }
    },
    setVoiceModeError: (state, action: PayloadAction<string | undefined>) => {
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      conversationState.chatState.voiceModeError = action.payload;
    },
    setPlanId: (
      state,
      action: PayloadActionMaybeSynced<{ planId: string }>
    ) => {
      const conversationState = getConversationState(state);
      if (!conversationState) {
        return;
      }
      conversationState.planId = action.payload.planId;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(startConversation.pending, (state) => {
        state.loading = true;
      })
      .addCase(startConversation.fulfilled, (state) => {
        state.loading = false;
        // Update conversation status to in progress
        const conversationState = getConversationState(state);
        // BUG: this is ALWAYS `undefined`
        if (conversationState) {
          conversationState.status = ConversationStatus.InProgress;
          conversationState.startedAt = new Date().toISOString();
        }
      })
      .addCase(startConversation.rejected, (state, action) => {
        state.loading = false;
        console.error("Failed to start conversation:", action.error);
      });
  },
  selectors: {
    selectSlice: (state) => state,
    selectConversationId: (state) => state.currentConversationId,
    selectConversationEntryIndex: (state, entryId: string) => {
      const conversationState = getConversationState(state);
      if (!conversationState) return -1;
      return conversationState.ids.indexOf(entryId);
    },
    selectConversationEntryExists: (state, entryId: string) => {
      const conversationState = getConversationState(state);
      if (!conversationState) return false;
      return conversationState.ids.includes(entryId);
    },
    selectConversationEntriesAsArray: (state) => {
      const conversationState = getConversationState(state);
      if (!conversationState) return [];
      return conversationState.ids.map((id) => conversationState.entities[id]);
    },
    selectConversationStatus: (state) => {
      const conversationState = getConversationState(state);
      if (!conversationState) return undefined;
      return conversationState.status;
    },
    selectIsSessionStarting: (state) => state.loading,
    selectIsLoading: (state) =>
      (state.loading || getConversationState(state)?.loading) ?? false,
    selectOldestEntry: (state) => getConversationState(state)?.entities[0],
    selectConversationStartedAt: (state) =>
      getConversationState(state)?.startedAt,
    selectParticipants: (state) => getConversationState(state)?.participants,
    selectAgentIsTyping: (state) => getConversationState(state)?.agentIsTyping,
    selectShowProgressIndicator: (state) =>
      getConversationState(state)?.showProgressIndicator,
    selectProgressIndicatorText: (state) =>
      getConversationState(state)?.progressIndicatorText,
    selectMessageById: (state, messageId: string) =>
      getConversationState(state)?.entities[messageId],
    selectIsChatOpen: (state) => state.isChatOpen,
    selectIsVoiceMode: (state) =>
      getConversationState(state)?.chatState.isVoiceMode ?? false,
    selectIsMuted: (state) =>
      getConversationState(state)?.chatState.isMuted ?? false,
    selectIsVoiceModeLoading: (state) => state.isVoiceModeLoading,
    selectChatState: (state) => getConversationState(state)?.chatState,
    selectActiveVoiceInstanceId: (state) =>
      getConversationState(state)?.chatState.activeVoiceInstanceId,
    selectVoiceModeError: (state) =>
      getConversationState(state)?.chatState.voiceModeError,
    selectPlanId: (state) => getConversationState(state)?.planId,
    // TODO add grouping selectors, timestamp coalescing, etc.
  },
});

type State = { conversation: ConversationState };
export const selectConversationEntriesAsArray = createSelector(
  [
    (state: State) =>
      state.conversation.currentConversationId
        ? state.conversation.conversations[
            state.conversation.currentConversationId
          ]?.ids
        : undefined,
    (state: State) =>
      state.conversation.currentConversationId
        ? state.conversation.conversations[
            state.conversation.currentConversationId
          ]?.entities
        : undefined,
  ],
  (ids, entities) => ids?.map((id) => entities![id]) ?? []
);

enum ParticipantChangedOperation {
  ADD = "ADD",
  REMOVE = "REMOVE",
}

export const {
  registerAdapters,
  setCurrentConversationId,
  initializeConversationEntries,
  addConversationEntry,
  updateConversationEntry,
  upsertConversationEntryStreamingMessage,
  addParticipant,
  removeParticipant,
  setAgentIsTyping,
  setConversationChatState,
  setActiveVoiceInstanceId,
  setIsChatOpen,
  setProgressIndicator,
  // client actions
  setConversationStatus,
  sendMessage,
  stopMessage,
  finishStreamingMessage,
  finishSynchronousMessage,
  endConversation,
  sessionTerminated,
  removeConversationEntry,
  setIsMuted,
  setIsVoiceModeLoading,
  setVoiceModeError,
  setPlanId,
  setConversationData,
} = conversationSlice.actions;
export const {
  selectSlice,
  selectActiveVoiceInstanceId,
  selectChatState,
  selectConversationId,
  selectConversationEntryIndex,
  selectConversationEntryExists,
  selectConversationStartedAt,
  selectConversationStatus,
  selectIsChatOpen,
  selectIsSessionStarting,
  selectIsLoading,
  selectIsMuted,
  selectIsVoiceMode,
  selectIsVoiceModeLoading,
  selectOldestEntry,
  selectParticipants,
  selectAgentIsTyping,
  selectShowProgressIndicator,
  selectProgressIndicatorText,
  selectMessageById,
  selectVoiceModeError,
  selectPlanId,
} = conversationSlice.selectors;
export const { selectEntities: selectConversationEntries } =
  conversationAdapter.getSelectors(
    (state: State) => getConversationState(state.conversation)!
  );

type ChangeParticipants =
  | ReturnType<typeof addParticipant>
  | ReturnType<typeof removeParticipant>;
export const changeParticipants = (
  participants: (Participant & { operation: ParticipantChangedOperation })[]
): ChangeParticipants[] => {
  // TODO ignore supervisor participants
  return participants.map(({ operation, ...participant }) => {
    switch (operation) {
      case ParticipantChangedOperation.ADD:
        return addParticipant(participant);
      case ParticipantChangedOperation.REMOVE:
        return removeParticipant(participant);
      default:
        throw new Error(
          `"${operation}" is not a supported operation for a ParticipantChanged event`
        );
    }
  });
};

export const selectConversationData = (state: State) => {
  const conversationState = getConversationState(state.conversation);
  return conversationState?.data ?? {};
};

export default conversationSlice.reducer;
