import { configureStore } from "@reduxjs/toolkit";
import { Persistor, persistStore } from "redux-persist";
import { conversationDataManager } from "./conversationDataManager";
import { createAsyncDispatchMiddleware } from "./middleware/asyncDispatch";
import { conversationDataMiddleware } from "./middleware/conversationDataMiddleware";
import { createPersistedReducer, IGNORED_PERSIST_ACTIONS } from "./persistence";
import { createStateSyncReducer } from "./sessionSync";
import { connectApphost, rootReducer, type RootState } from "./slices";

// create the state sync reducer
const stateSyncReducer = createStateSyncReducer(rootReducer);

// Create persisted reducer
const persistedReducer = createPersistedReducer(stateSyncReducer);

export const store = configureStore({
  reducer: persistedReducer,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      serializableCheck: {
        ignoredActions: [
          ...IGNORED_PERSIST_ACTIONS,
          "conversation/registerAdapters",
        ],
      },
    })
      .prepend(conversationDataMiddleware.middleware)
      .concat(createAsyncDispatchMiddleware("conversation/registerAdapters")),
});

export const noopPersistor: Persistor = {
  pause: () => {},
  persist: () => {},
  purge: () => Promise.resolve(),
  flush: () => Promise.resolve(),
  dispatch: (action) => action,
  getState: () => ({
    registry: [],
    bootstrapped: true,
  }),
  subscribe: () => () => {},
};

export const configurePersistor = (disablePersistence: boolean) => {
  if (disablePersistence) {
    return noopPersistor;
  }
  return persistStore(store);
};

// Infer the `RootState` and `AppDispatch` types from the store itself
export type { RootState };
export type AppDispatch = typeof store.dispatch;

connectApphost(store.dispatch);

conversationDataManager.init(store);

export { conversationDataManager };
