/**
 * This is the adapter for MIAW services/APIS
 */

import { miawConfigurationAdapterFactory } from "./miawConfigurationAdapter";
import { miawConversationAdapterFactory } from "./miawConversationAdapter";

const definition: AdapterDefinition = {
  name: "MIAW Adapter",
  supports: ["configuration", "conversation"],
  adapters: {
    configuration: miawConfigurationAdapterFactory,
    conversation: miawConversationAdapterFactory,
  },
};

interface InitValues {
  configuration?: Record<string, unknown>;
  conversation?: Record<string, unknown>;
}

const createDefinitionWithInitValues = (
  initValues: InitValues
): AdapterDefinition => ({
  ...definition,
  getInitValues: (adapterType) => initValues[adapterType as keyof InitValues],
});

export { createDefinitionWithInitValues, definition };
