/**
 * This is the adapter for MIAW services/APIS
 */

import { agentConfigurationAdapterFactory } from "./agentConfigurationAdapter";
import { agentConversationAdapterFactory } from "./agentConversationAdapter";

const definition: AdapterDefinition = {
  name: "Agent API Adapter",
  supports: ["configuration", "conversation"],
  adapters: {
    configuration: agentConfigurationAdapterFactory,
    conversation: agentConversationAdapterFactory,
  },
};

interface InitValues {
  configuration?: Record<string, any>;
  conversation?: Record<string, any>;
}

const createDefinitionWithInitValues = (
  initValues: InitValues
): AdapterDefinition => ({
  ...definition,
  getInitValues: (adapterType) => initValues[adapterType as keyof InitValues],
});

export { createDefinitionWithInitValues, definition };
