import {
  createSlice,
  type Dispatch,
  type PayloadAction,
} from "@reduxjs/toolkit";
import { v4 } from "uuid";
import { asAsyncAction } from "../middleware/asyncDispatch";

interface ApphostState {
  authToken: AuthToken | null;
  hostUrl: string;
  scriptUrl: string; // TODO is this the right place for this?
  instanceId: string;
}

export const initialState: ApphostState = {
  authToken: null,
  hostUrl: "",
  scriptUrl: "",
  instanceId: v4(),
};

export const apphostSlice = createSlice({
  name: "apphost",
  initialState,
  reducers: {
    init: (state) => {
      const instanceId = state.instanceId || v4(); // generate a random ID for this instance
      state.instanceId = instanceId;
      window.parent.postMessage(
        {
          type: "init",
          data: { instanceId },
        },
        "*"
      );
    },
    initDone: (state) => {
      window.parent.postMessage(
        {
          type: "init-done",
        },
        state.hostUrl
      );
    },
    setAuthToken: (state, action: PayloadAction<AuthToken | undefined>) => {
      state.authToken = action.payload ?? null;
    },
    setHostUrl: (state, action: PayloadAction<string>) => {
      const hostUrl = action.payload.replace(
        /^(https?:\/\/[^/]+)\/?.*$/,
        "$1/"
      );
      state.hostUrl = hostUrl;
      asAsyncAction(action).asyncDispatch({
        type: "apphost/initDone",
      });
    },
    setScriptUrl: (state, action: PayloadAction<string>) => {
      state.scriptUrl = action.payload;
    },
    requestDimensions: (state) => {
      const width = document.documentElement.scrollWidth;
      const height = document.documentElement.scrollHeight;
      window.parent.postMessage(
        { type: "resize", width, height },
        state.hostUrl
      );
    },
  },
  selectors: {
    selectAuthToken: (state) => state.authToken,
    selectHostUrl: (state) => state.hostUrl,
    selectInstanceId: (state) => state.instanceId,
    selectScriptUrl: (state) => state.scriptUrl,
  },
});

const {
  init,
  initDone,
  setAuthToken,
  setHostUrl,
  setScriptUrl,
  requestDimensions,
} = apphostSlice.actions;
const { selectAuthToken, selectHostUrl, selectInstanceId, selectScriptUrl } =
  apphostSlice.selectors;
export {
  requestDimensions,
  selectAuthToken,
  selectHostUrl,
  selectInstanceId,
  selectScriptUrl,
  setAuthToken,
  setHostUrl,
  setScriptUrl,
};

export const connectApphost = (
  dispatch: Dispatch<
    ReturnType<
      | typeof init
      | typeof initDone
      | typeof setHostUrl
      | typeof requestDimensions
    >
  >
) => {
  const listener = (event: MessageEvent) => {
    switch (event.data.type) {
      case "requestDimensions": {
        dispatch(requestDimensions());
        break;
      }
      case "setHostUrl": {
        dispatch(setHostUrl(event.data.hostUrl));
        dispatch(initDone());
        break;
      }
      default:
        break;
    }
  };
  window.addEventListener("message", listener);
  const unsubscribe = () => {
    window.removeEventListener("message", listener);
  };
  setTimeout(() => {
    dispatch(init());
  }, 100);
  return unsubscribe;
};

export default apphostSlice.reducer;
