export const miawConfigurationAdapterFactory: AdapterFactory<
  ConfigurationAdapter
> = (getAdapters) => {
  const getConversationId = () => {
    const conversationId = (
      getAdapters().conversation as MiawConversationAdapter
    ).conversationId;
    if (!conversationId) {
      throw new Error("No conversation is currently active");
    }
    return conversationId;
  };

  return {
    adapterType: "configuration",
    getConversationId,
  };
};
